INSERT INTO exercises (external_id, name, name_fr, body_part, target_muscle, secondary_muscles, equipment, difficulty, instructions, gif_url, image_url, video_url) VALUES
('g9AsZ8P','kettlebell one arm row',NULL,'back','upper back','{"biceps","forearms"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Step:3 Pull the kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower the kettlebell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."}','https://static.exercisedb.dev/media/g9AsZ8P.gif','https://static.exercisedb.dev/media/g9AsZ8P.gif',NULL),
('GaSzzuh','back lever',NULL,'back','upper back','{"biceps","forearms","core"}','body weight',NULL,'{"Step:1 Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Engage your core and pull your shoulder blades down and back.","Step:3 Bend your knees and tuck them towards your chest.","Step:4 Slowly lift your legs up, keeping them straight, until your body is parallel to the ground.","Step:5 Hold this position for a few seconds, then slowly lower your legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/GaSzzuh.gif','https://static.exercisedb.dev/media/GaSzzuh.gif',NULL),
('gAwDzB3','cable triceps pushdown (v-bar)',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a v-bar attachment to the cable machine at the highest setting.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Step:6 Pause for a moment at the bottom of the movement, squeezing your triceps.","Step:7 Inhale as you slowly return the v-bar to the starting position, maintaining control.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gAwDzB3.gif','https://static.exercisedb.dev/media/gAwDzB3.gif',NULL),
('Gchi5Tr','cable alternate triceps extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.","Step:3 Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.","Step:4 Pause for a moment, then slowly return to the starting position.","Step:5 Repeat with your left arm.","Step:6 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gchi5Tr.gif','https://static.exercisedb.dev/media/Gchi5Tr.gif',NULL),
('GdMa1ET','incline scapula push up',NULL,'chest','serratus anterior','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Place your hands on the bench slightly wider than shoulder-width apart.","Step:3 Position your feet on the ground, hip-width apart.","Step:4 Lower your chest towards the bench, keeping your elbows tucked in.","Step:5 As you lower, retract your shoulder blades, squeezing your scapulae together.","Step:6 Push through your palms to extend your arms and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/GdMa1ET.gif','https://static.exercisedb.dev/media/GdMa1ET.gif',NULL),
('gdPIyyO','hanging pike with intense',NULL,'core','abs','{"hip flexors","shoulders"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up towards the bar, keeping them straight.","Step:3 (intense variation) Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.","Step:4 Hold the position for a moment, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gdPIyyO.gif','https://static.exercisedb.dev/media/gdPIyyO.gif',NULL),
('gEyURal','barbell single leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet hip-width apart, holding a barbell in front of your thighs with an overhand grip.","Step:2 Shift your weight onto your left foot and lift your right foot slightly off the ground.","Step:3 Hinge forward at the hips, keeping your back straight and your right leg extended behind you for balance.","Step:4 Lower the barbell towards the ground, keeping it close to your body and your left leg slightly bent.","Step:5 Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/gEyURal.gif','https://static.exercisedb.dev/media/gEyURal.gif',NULL),
('gf3ZjB9','sled closer hack squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.","Step:2 Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Step:3 Grip the handles on the sides of the machine for stability.","Step:4 Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.","Step:5 Continue lowering until your thighs are parallel to the ground or slightly below.","Step:6 Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gf3ZjB9.gif','https://static.exercisedb.dev/media/gf3ZjB9.gif',NULL),
('gfk9kD4','barbell overhead squat',NULL,'legs','quads','{"glutes","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and toes slightly turned out.","Step:2 Hold the barbell with a wide grip, positioning it overhead with your arms fully extended.","Step:3 Engage your core and lower your body down into a squat position, keeping your chest up and knees tracking over your toes.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gfk9kD4.gif','https://static.exercisedb.dev/media/gfk9kD4.gif',NULL),
('gFyFj9z','dumbbell step-up lunge',NULL,'legs','quads','{"glutes","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand in front of a step or platform with a dumbbell in each hand, palms facing your sides.","Step:2 Place your right foot on the step, ensuring your entire foot is on the surface.","Step:3 Push through your right heel and lift your body up onto the step, bringing your left foot up as well.","Step:4 Once both feet are on the step, lower your left foot back down to the starting position, keeping your right foot on the step.","Step:5 Repeat the movement, alternating which foot you step up with each time.","Step:6 Continue for the desired number of repetitions."}','https://static.exercisedb.dev/media/gFyFj9z.gif','https://static.exercisedb.dev/media/gFyFj9z.gif',NULL),
('gGNQmVt','barbell single leg split squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Step:2 Take a large step forward with one leg, keeping your torso upright.","Step:3 Lower your body by bending your front knee and hip, while keeping your back leg straight.","Step:4 Continue lowering until your front thigh is parallel to the ground.","Step:5 Pause for a moment, then push through your front heel to return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/gGNQmVt.gif','https://static.exercisedb.dev/media/gGNQmVt.gif',NULL),
('gH5fRsC','dumbbell seated alternate front raise',NULL,'shoulders','delts','{"trapezius","biceps"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell in each hand with your palms facing your body and arms extended down by your sides.","Step:3 Keeping your arms straight, raise one dumbbell in front of you until it is parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat with the other arm.","Step:6 Alternate between arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/gH5fRsC.gif','https://static.exercisedb.dev/media/gH5fRsC.gif',NULL),
('Gi2BXfK','dumbbell standing alternating tricep kickback',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Extend your arms straight back, keeping your elbows close to your body.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat with the other arm, alternating sides with each repetition."}','https://static.exercisedb.dev/media/Gi2BXfK.gif','https://static.exercisedb.dev/media/Gi2BXfK.gif',NULL),
('GibBPPg','glute bridge march',NULL,'legs','glutes','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.","Step:3 While keeping your hips lifted, lift one foot off the ground and bring your knee towards your chest.","Step:4 Lower your foot back to the ground and repeat the movement with the other leg.","Step:5 Continue alternating legs in a marching motion while maintaining the bridge position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/GibBPPg.gif','https://static.exercisedb.dev/media/GibBPPg.gif',NULL),
('Gk1r408','weighted close grip chin-up on dip cage',NULL,'back','lats','{"biceps","forearms"}','other',NULL,'{"Step:1 Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.","Step:2 Hang from the bars with your arms fully extended, feet off the ground, and body straight.","Step:3 Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.","Step:4 Continue pulling until your chin is above the bars, then pause for a moment.","Step:5 Slowly lower your body back down to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gk1r408.gif','https://static.exercisedb.dev/media/Gk1r408.gif',NULL),
('GKEH6jj','cable one arm incline press',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Adjust the cable machine to a low pulley position.","Step:2 Sit on an incline bench facing away from the cable machine.","Step:3 Grasp the handle with one hand and bring it up to shoulder height.","Step:4 Position your feet firmly on the ground and maintain a stable position.","Step:5 Press the handle forward and upward, extending your arm fully.","Step:6 Pause for a moment at the top, then slowly lower the handle back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/GKEH6jj.gif','https://static.exercisedb.dev/media/GKEH6jj.gif',NULL),
('gKozT8X','dumbbell single leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet hip-width apart, holding a dumbbell in your right hand.","Step:2 Shift your weight onto your left leg and lift your right foot slightly off the ground.","Step:3 Keeping your back straight, hinge forward at the hips and lower the dumbbell towards the ground.","Step:4 At the same time, extend your right leg straight behind you, maintaining a slight bend in your left knee.","Step:5 Lower the dumbbell until your torso and right leg are parallel to the ground.","Step:6 Pause for a moment, then engage your glutes and hamstrings to return to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/gKozT8X.gif','https://static.exercisedb.dev/media/gKozT8X.gif',NULL),
('Gm2Uv1z','exercise ball supine triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.","Step:3 Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Step:4 Pause for a moment, then raise the dumbbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gm2Uv1z.gif','https://static.exercisedb.dev/media/Gm2Uv1z.gif',NULL),
('gMyx3Qn','high style scapula push-up',NULL,'chest','serratus anterior','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your chest towards the ground, keeping your elbows close to your body.","Step:3 As you lower, squeeze your shoulder blades together and push your chest forward. Focus on high movement.","Step:4 Pause for a moment at the bottom, then push back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gMyx3Qn.gif','https://static.exercisedb.dev/media/gMyx3Qn.gif',NULL),
('Gn5FwYT','stability ball crunch (full range hands behind head)',NULL,'core','abs','{"hip flexors"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your upper body back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gn5FwYT.gif','https://static.exercisedb.dev/media/Gn5FwYT.gif',NULL),
('Gnfo4FM','barbell high bar squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Place the barbell on your upper back, resting it on your traps.","Step:3 Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees.","Step:4 Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Drive through your heels to stand back up, extending your hips and knees.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gnfo4FM.gif','https://static.exercisedb.dev/media/Gnfo4FM.gif',NULL),
('GNhAeJ0','dumbbell hammer curls (with arm blaster)',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your torso.","Step:2 Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","Step:3 This will be your starting position.","Step:4 Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Step:5 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Step:8 Repeat for the recommended amount of repetitions."}','https://static.exercisedb.dev/media/GNhAeJ0.gif','https://static.exercisedb.dev/media/GNhAeJ0.gif',NULL),
('goJ6ezq','cable lateral raise',NULL,'shoulders','delts','{"traps","triceps"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and grasp the cable handles with an overhand grip.","Step:2 Keep your arms straight and your core engaged.","Step:3 Raise your arms out to the sides until they are parallel to the floor.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/goJ6ezq.gif','https://static.exercisedb.dev/media/goJ6ezq.gif',NULL),
('GOJKFfO','exercise ball one legged diagonal kick hamstring curl',NULL,'legs','glutes','{"hamstrings","calves"}','other',NULL,'{"Step:1 Start by lying on your back with your legs extended and your heels resting on top of the stability ball.","Step:2 Place your arms by your sides for stability.","Step:3 Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.","Step:4 Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.","Step:5 Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.","Step:6 Slowly return your right leg to the starting position, maintaining control and stability.","Step:7 Repeat the movement with your left leg, alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/GOJKFfO.gif','https://static.exercisedb.dev/media/GOJKFfO.gif',NULL),
('Gpn4ADc','smith behind neck press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height of the smith machine so that the bar is at shoulder level.","Step:2 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:3 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lift the bar off the rack and step back, maintaining a stable stance.","Step:5 Lower the bar down to the back of your neck, keeping your elbows pointing forward.","Step:6 Press the bar up overhead until your arms are fully extended.","Step:7 Pause for a moment at the top, then slowly lower the bar back down to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gpn4ADc.gif','https://static.exercisedb.dev/media/Gpn4ADc.gif',NULL),
('GrO65fd','barbell decline bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your feet secured and your head lower than your hips.","Step:2 Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.","Step:3 Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.","Step:4 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/GrO65fd.gif','https://static.exercisedb.dev/media/GrO65fd.gif',NULL),
('gscGLOU','bodyweight side lying biceps curl',NULL,'arms','biceps','{"forearms"}','body weight',NULL,'{"Step:1 Lie on your side with your legs extended and your head supported by your arm.","Step:2 Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.","Step:3 Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gscGLOU.gif','https://static.exercisedb.dev/media/gscGLOU.gif',NULL),
('GSDioYu','upper back stretch',NULL,'back','upper back','{"shoulders"}','body weight',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart.","Step:2 Extend your arms straight in front of you, parallel to the ground.","Step:3 Interlace your fingers and rotate your palms away from your body.","Step:4 Slowly raise your arms overhead, keeping them straight and parallel to each other.","Step:5 As you raise your arms, squeeze your shoulder blades together.","Step:6 Hold the stretch for 15-30 seconds, then release and repeat."}','https://static.exercisedb.dev/media/GSDioYu.gif','https://static.exercisedb.dev/media/GSDioYu.gif',NULL),
('gSO0KpB','sit-up with arms on chest with mini',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Cross your arms over your chest.","Step:3 Engaging your abs, lift your upper body off the ground towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Maintain mini form throughout.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gSO0KpB.gif','https://static.exercisedb.dev/media/gSO0KpB.gif',NULL),
('gSw59a4','dumbbell lying one arm deltoid rear',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Step:2 Extend your arm straight down towards the floor, keeping it close to your body.","Step:3 Raise your arm up and back, squeezing your shoulder blade towards your spine.","Step:4 Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/gSw59a4.gif','https://static.exercisedb.dev/media/gSw59a4.gif',NULL),
('gTGciXz','alternating bear crawl',NULL,'cardio','cardiovascular system','{"core","shoulders","triceps"}','body weight',NULL,'{"Step:1 Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Step:2 Lift your knees slightly off the ground, keeping your back flat and your core engaged.","Step:3 Move your right hand and left foot forward simultaneously, followed by your left hand and right foot.","Step:4 Continue crawling forward, alternating your hand and foot movements.","Step:5 Maintain a steady pace and keep your core tight throughout the exercise.","Step:6 (alternating variation) Continue for the desired distance or time."}','https://static.exercisedb.dev/media/gTGciXz.gif','https://static.exercisedb.dev/media/gTGciXz.gif',NULL),
('gtO1ErP','weighted three bench dips',NULL,'arms','triceps','{"chest","shoulders"}','other',NULL,'{"Step:1 Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.","Step:3 Lower your body by bending your elbows, keeping your back close to the bench.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gtO1ErP.gif','https://static.exercisedb.dev/media/gtO1ErP.gif',NULL),
('Gu2ENkm','deep smith machine reverse decline close grip bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the smith machine to a decline position.","Step:2 Lie down on the bench with your feet secured under the foot pads.","Step:3 Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Focus on deep movement.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gu2ENkm.gif','https://static.exercisedb.dev/media/Gu2ENkm.gif',NULL),
('Gu2rNJd','smith chair squat',NULL,'legs','quads','{"glutes","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the height of the smith machine bar to a comfortable position.","Step:2 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:3 Place the barbell across your upper back, resting it on your traps.","Step:4 Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.","Step:5 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:6 Pause for a moment, then push through your heels to return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gu2rNJd.gif','https://static.exercisedb.dev/media/Gu2rNJd.gif',NULL),
('gUjqdei','curtsey squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Step:3 Bend both knees as if you were curtsying, lowering your body towards the ground.","Step:4 Keep your torso upright and your weight on your front foot.","Step:5 Push through your front foot to return to the starting position.","Step:6 Repeat on the other side, stepping diagonally behind and across your body with your left foot."}','https://static.exercisedb.dev/media/gUjqdei.gif','https://static.exercisedb.dev/media/gUjqdei.gif',NULL),
('GUT8I22','lever deadlift',NULL,'legs','glutes','{"hamstrings","quadriceps"}','machine',NULL,'{"Step:1 Adjust the seat height and foot platform to your desired position.","Step:2 Sit on the machine with your back against the pad and your feet flat on the foot platform.","Step:3 Grasp the handles or the sides of the seat for stability.","Step:4 Engage your glutes and hamstrings, and push through your heels to lift the weight up.","Step:5 Keep your back straight and avoid rounding your shoulders.","Step:6 Extend your hips fully at the top of the movement, squeezing your glutes.","Step:7 Lower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/GUT8I22.gif','https://static.exercisedb.dev/media/GUT8I22.gif',NULL),
('guT8YnS','biceps pull-up',NULL,'arms','biceps','{"forearms","shoulders"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.","Step:2 Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.","Step:3 Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/guT8YnS.gif','https://static.exercisedb.dev/media/guT8YnS.gif',NULL),
('gVlnLIJ','cable reverse one arm curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Grasp the cable handle with an underhand grip, palm facing down.","Step:3 Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.","Step:4 Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gVlnLIJ.gif','https://static.exercisedb.dev/media/gVlnLIJ.gif',NULL),
('gvsWLQw','dumbbell concentration curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Step:2 Fully extend your arm and hold the dumbbell with an underhand grip.","Step:3 Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.","Step:4 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly lower the dumbbell back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/gvsWLQw.gif','https://static.exercisedb.dev/media/gvsWLQw.gif',NULL),
('Gw2HFvW','dumbbell incline one arm fly',NULL,'chest','pectorals','{"deltoids","triceps"}','dumbbell',NULL,'{"Step:1 Adjust the incline bench to a 30-45 degree angle.","Step:2 Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Step:3 Lie back on the bench, keeping your feet flat on the ground.","Step:4 Hold the dumbbell with your arm extended straight up over your chest.","Step:5 Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Step:6 Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/Gw2HFvW.gif','https://static.exercisedb.dev/media/Gw2HFvW.gif',NULL),
('gw9PqGk','full planche push-up',NULL,'chest','pectorals','{"shoulders","triceps","core"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Step:2 Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","Step:3 As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands.","Step:4 Continue to lower your body until your chest is just above the ground.","Step:5 Push through your hands and extend your arms to lift your body back up to the starting position.","Step:6 Maintain a straight line from your head to your heels throughout the movement.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gw9PqGk.gif','https://static.exercisedb.dev/media/gw9PqGk.gif',NULL),
('gWcZD4q','horizontal dumbbell standing alternate overhead press',NULL,'shoulders','delts','{"triceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level with your palms facing forward.","Step:2 (horizontal variation) Press one dumbbell overhead, fully extending your arm.","Step:3 Lower the dumbbell back to shoulder level.","Step:4 Repeat with the other arm.","Step:5 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/gWcZD4q.gif','https://static.exercisedb.dev/media/gWcZD4q.gif',NULL),
('GWoKnIm','weighted cossack squats (male)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','other',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.","Step:2 Hold a weight in front of your chest with both hands.","Step:3 Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.","Step:4 Go as low as you can while maintaining balance and keeping your chest up.","Step:5 Push through the heel of the bent leg to return to the starting position.","Step:6 Repeat on the other side, alternating between legs."}','https://static.exercisedb.dev/media/GWoKnIm.gif','https://static.exercisedb.dev/media/GWoKnIm.gif',NULL),
('GwYwElT','self assisted inverse leg curl',NULL,'legs','hamstrings','{"glutes","calves"}','body weight',NULL,'{"Step:1 Lie flat on your back on a mat or bench with your legs extended.","Step:2 Place your hands by your sides or under your glutes for support.","Step:3 Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.","Step:4 Pause for a moment at the top, then slowly lower your legs back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/GwYwElT.gif','https://static.exercisedb.dev/media/GwYwElT.gif',NULL),
('gx7s7uF','barbell incline close grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Lie down on the bench with your feet flat on the ground.","Step:3 Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Step:4 Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Step:5 Pause for a moment when the barbell touches your chest.","Step:6 Push the barbell back up to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/gx7s7uF.gif','https://static.exercisedb.dev/media/gx7s7uF.gif',NULL),
('GxDwDX0','assisted lying calves stretch',NULL,'legs','calves','{"hamstrings"}','other',NULL,'{"Step:1 Lie on your back with your legs extended.","Step:2 Bend one knee and place your foot flat on the ground.","Step:3 Using your hands or a towel, gently pull your toes towards your body, feeling a stretch in your calf.","Step:4 Hold the stretch for 20-30 seconds.","Step:5 Release the stretch and repeat on the other leg."}','https://static.exercisedb.dev/media/GxDwDX0.gif','https://static.exercisedb.dev/media/GxDwDX0.gif',NULL),
('Gxg9lDc','barbell rollerout from bench',NULL,'core','abs','{"shoulders","triceps"}','barbell',NULL,'{"Step:1 Start by kneeling on the floor with a barbell placed on a bench in front of you.","Step:2 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Keeping your core engaged and your back straight, slowly roll the barbell forward, extending your arms in front of you.","Step:4 Continue rolling the barbell forward until your body is fully extended and your arms are overhead.","Step:5 Pause for a moment at the fully extended position, then slowly roll the barbell back towards your body, returning to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Gxg9lDc.gif','https://static.exercisedb.dev/media/Gxg9lDc.gif',NULL),
('GXoaSgn','barbell guillotine bench press',NULL,'chest','pectorals','{"shoulders","triceps"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lower the barbell slowly towards your neck, keeping your elbows pointed outwards.","Step:4 Pause for a moment when the barbell is just above your neck.","Step:5 Push the barbell back up to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/GXoaSgn.gif','https://static.exercisedb.dev/media/GXoaSgn.gif',NULL),
('h1ezqSu','kneeling plank tap shoulder (male)',NULL,'core','abs','{"shoulders","triceps"}','body weight',NULL,'{"Step:1 Start in a kneeling position with your hands on the ground, shoulder-width apart.","Step:2 Extend your legs behind you, resting on your toes, and lift your body into a plank position.","Step:3 Keeping your core engaged and your hips stable, lift one hand off the ground and tap the opposite shoulder.","Step:4 Return the hand to the ground and repeat with the other hand.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/h1ezqSu.gif','https://static.exercisedb.dev/media/h1ezqSu.gif',NULL),
('H1PESYI','stationary bike run',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','stationary bike',NULL,'{"Step:1 Adjust the seat height and position to ensure proper alignment.","Step:2 Place your feet on the pedals and secure them with the straps if available.","Step:3 Start pedaling at a comfortable pace.","Step:4 Maintain a steady rhythm and increase the resistance as desired.","Step:5 Engage your core muscles to maintain stability and proper posture.","Step:6 Continue pedaling for the desired duration of your workout.","Step:7 Gradually decrease the resistance and slow down before coming to a complete stop.","Step:8 Stretch your legs and cool down after the workout."}','https://static.exercisedb.dev/media/H1PESYI.gif','https://static.exercisedb.dev/media/H1PESYI.gif',NULL),
('H1XAdpk','dumbbell biceps curl v sit on bosu ball',NULL,'arms','biceps','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/H1XAdpk.gif','https://static.exercisedb.dev/media/H1XAdpk.gif',NULL),
('H6ETwO9','band v-up',NULL,'core','abs','{"hip flexors"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Engaging your abs, lift your legs and upper body off the ground simultaneously, reaching your hands towards your toes.","Step:3 Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/H6ETwO9.gif','https://static.exercisedb.dev/media/H6ETwO9.gif',NULL),
('H6ybluc','dumbbell single leg squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Step:2 Extend one leg forward and keep it off the ground throughout the exercise.","Step:3 Bend your standing leg and lower your body down as if sitting back into a chair.","Step:4 Keep your chest up and your back straight.","Step:5 Pause for a moment at the bottom, then push through your heel to return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/H6ybluc.gif','https://static.exercisedb.dev/media/H6ybluc.gif',NULL),
('h8LFzo9','barbell lying triceps extension skull crusher',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Step:4 Pause for a moment when the barbell is just above your forehead, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/h8LFzo9.gif','https://static.exercisedb.dev/media/h8LFzo9.gif',NULL),
('H9y3Dkr','cable two arm curl on incline bench',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Sit on an incline bench with your back against the pad and your feet flat on the ground.","Step:2 Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Step:4 Pause for a moment at the top of the movement, squeezing your biceps.","Step:5 Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/H9y3Dkr.gif','https://static.exercisedb.dev/media/H9y3Dkr.gif',NULL),
('Ha7SZ3y','kettlebell turkish get up (squat style)',NULL,'legs','glutes','{"quadriceps","hamstrings","core"}','kettlebell',NULL,'{"Step:1 Start by lying on your back with your legs extended and the kettlebell held in your right hand, arm fully extended above your shoulder.","Step:2 Bend your right knee and place your right foot flat on the ground, keeping your left leg extended.","Step:3 Pressing through your right foot, lift your hips off the ground, coming into a bridge position.","Step:4 Slide your left leg underneath your body, bending your left knee and placing your left foot flat on the ground.","Step:5 Rotate your torso to the left, bringing your left hand to the ground for support.","Step:6 Pressing through your right foot and left hand, lift your torso off the ground, coming into a kneeling position.","Step:7 From the kneeling position, stand up, keeping the kettlebell extended overhead.","Step:8 Reverse the movement to return to the starting position.","Step:9 Repeat the exercise on the other side, starting with the kettlebell in your left hand."}','https://static.exercisedb.dev/media/Ha7SZ3y.gif','https://static.exercisedb.dev/media/Ha7SZ3y.gif',NULL),
('hacCyUv','ez barbell close grip preacher curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Step:2 Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Step:3 Slowly curl the barbell towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Lower the barbell back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hacCyUv.gif','https://static.exercisedb.dev/media/hacCyUv.gif',NULL),
('hBGWILP','cable hip adduction',NULL,'legs','adductors','{"glutes","quadriceps"}','cable',NULL,'{"Step:1 Attach the ankle cuff to your ankle and stand facing the cable machine.","Step:2 Position yourself far enough away from the machine so that there is tension on the cable.","Step:3 Place your hands on the machine for support.","Step:4 Keeping your leg straight, slowly move your leg across your body towards the midline.","Step:5 Pause for a moment at the end of the movement, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hBGWILP.gif','https://static.exercisedb.dev/media/hBGWILP.gif',NULL),
('HbSG1Pw','isometric chest squeeze',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Extend your arms straight out in front of you, parallel to the ground, with your palms facing each other.","Step:3 Squeeze your chest muscles together as hard as you can, while keeping your arms straight.","Step:4 Hold this position for a few seconds, focusing on contracting your chest muscles.","Step:5 Release the squeeze and relax your chest muscles.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HbSG1Pw.gif','https://static.exercisedb.dev/media/HbSG1Pw.gif',NULL),
('hbY9wqG','front lever reps',NULL,'back','upper back','{"core","shoulders"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with an overhand grip, palms facing away from you.","Step:2 Engage your core and pull your shoulder blades down and back.","Step:3 Keeping your body straight, lift your legs up until they are parallel to the ground.","Step:4 Hold this position for as long as you can, aiming for 10-20 seconds.","Step:5 Slowly lower your legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hbY9wqG.gif','https://static.exercisedb.dev/media/hbY9wqG.gif',NULL),
('HBYyX94','barbell split squat v. 2',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, holding a barbell across your upper back.","Step:2 Take a large step forward with your right foot, keeping your torso upright.","Step:3 Lower your body by bending your knees and hips until your right thigh is parallel to the ground.","Step:4 Pause for a moment, then push through your right heel to return to the starting position.","Step:5 Repeat with your left leg forward for the desired number of repetitions."}','https://static.exercisedb.dev/media/HBYyX94.gif','https://static.exercisedb.dev/media/HBYyX94.gif',NULL),
('hC6oYY5','assisted side lying adductor stretch',NULL,'legs','adductors','{"hamstrings","glutes"}','other',NULL,'{"Step:1 Lie on your side with your legs straight and stacked on top of each other.","Step:2 Bend your bottom leg slightly for stability.","Step:3 Place your top foot on a stable surface, such as a bench or step.","Step:4 Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.","Step:5 Hold the stretch for 20-30 seconds.","Step:6 Return to the starting position and repeat on the other side."}','https://static.exercisedb.dev/media/hC6oYY5.gif','https://static.exercisedb.dev/media/hC6oYY5.gif',NULL),
('hCjGsRQ','power point plank',NULL,'core','abs','{"shoulders","triceps","glutes"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.","Step:2 Engage your core and squeeze your glutes to maintain a stable position.","Step:3 Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe.","Step:4 Hold this position for the desired amount of time, keeping your core and glutes engaged.","Step:5 To return to the starting position, push through your forearms and lift your body back up into a high plank position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hCjGsRQ.gif','https://static.exercisedb.dev/media/hCjGsRQ.gif',NULL),
('HDYiZcY','dumbbell cross body hammer curl v. 2',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your body.","Step:2 Keep your elbows close to your torso and your upper arms stationary.","Step:3 Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HDYiZcY.gif','https://static.exercisedb.dev/media/HDYiZcY.gif',NULL),
('HEJ6DIX','cable kickback',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Stand facing a cable machine with your feet shoulder-width apart.","Step:2 Hold the cable handle with your right hand and step back to create tension in the cable.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Keep your upper arm close to your body and your elbow bent at a 90-degree angle.","Step:5 Extend your forearm backward, straightening your arm fully.","Step:6 Pause for a moment, then slowly return to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/HEJ6DIX.gif','https://static.exercisedb.dev/media/HEJ6DIX.gif',NULL),
('hfmQ0Tz','smith standing back wrist curl',NULL,'arms','forearms','{"biceps","triceps"}','machine',NULL,'{"Step:1 Stand facing the smith machine with your feet shoulder-width apart.","Step:2 Grasp the barbell with an overhand grip, hands shoulder-width apart.","Step:3 Keep your back straight and your elbows close to your body.","Step:4 Slowly curl your wrists upwards, bringing the barbell towards your body.","Step:5 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hfmQ0Tz.gif','https://static.exercisedb.dev/media/hfmQ0Tz.gif',NULL),
('HfqciZF','straddle maltese',NULL,'core','abs','{"shoulders","chest"}','body weight',NULL,'{"Step:1 Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.","Step:2 Spread your legs wide apart, forming a straddle position.","Step:3 Engage your core and slowly lower your body until your arms are parallel to the ground.","Step:4 Hold this position for a few seconds, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HfqciZF.gif','https://static.exercisedb.dev/media/HfqciZF.gif',NULL),
('Hgs6Nl1','seated leg raise',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Sit on a flat bench with your back straight and your feet flat on the ground.","Step:2 Place your hands on the sides of the bench for support.","Step:3 Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Hgs6Nl1.gif','https://static.exercisedb.dev/media/Hgs6Nl1.gif',NULL),
('hHy8tQG','cable one arm fly on exercise ball',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a cable handle in one hand and extend your arm out to the side, parallel to the ground.","Step:3 Keep your elbow slightly bent and your palm facing forward.","Step:4 Slowly bring your arm across your body, squeezing your chest muscles.","Step:5 Pause for a moment at the end of the movement, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/hHy8tQG.gif','https://static.exercisedb.dev/media/hHy8tQG.gif',NULL),
('HIgYKAB','seated wide angle pose sequence',NULL,'legs','hamstrings','{"quadriceps","calves"}','body weight',NULL,'{"Step:1 Sit on the ground with your legs extended in a wide angle.","Step:2 Flex your feet and engage your quadriceps.","Step:3 Place your hands on the ground behind you for support.","Step:4 Keeping your back straight, lean forward from your hips.","Step:5 Continue leaning forward until you feel a stretch in your hamstrings.","Step:6 Hold this position for a few breaths.","Step:7 Slowly release the stretch and return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HIgYKAB.gif','https://static.exercisedb.dev/media/HIgYKAB.gif',NULL),
('Hj4FOCd','barbell decline wide-grip pullover',NULL,'back','lats','{"triceps","chest"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your head lower than your hips and your feet secured.","Step:2 Hold a barbell with a wide grip and extend your arms straight above your chest.","Step:3 Lower the barbell behind your head in a controlled manner, keeping your arms straight.","Step:4 Pause for a moment, then raise the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Hj4FOCd.gif','https://static.exercisedb.dev/media/Hj4FOCd.gif',NULL),
('HJ63mSO','barbell lying close-grip triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.","Step:3 Extend your arms fully, lifting the barbell above your chest.","Step:4 Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Step:5 Pause for a moment at the bottom, then extend your arms back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HJ63mSO.gif','https://static.exercisedb.dev/media/HJ63mSO.gif',NULL),
('HjdqmZa','one arm chin-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand facing a pull-up bar with your feet shoulder-width apart.","Step:2 Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support.","Step:3 Hang from the bar with your arm fully extended, keeping your body straight and your core engaged.","Step:4 Pull yourself up towards the bar by bending your elbow and squeezing your back muscles.","Step:5 Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms and repeat."}','https://static.exercisedb.dev/media/HjdqmZa.gif','https://static.exercisedb.dev/media/HjdqmZa.gif',NULL),
('hjWjJEm','exercise ball hip flexor stretch pointed',NULL,'legs','glutes','{"quadriceps","hamstrings"}','other',NULL,'{"Step:1 Place the stability ball on the ground and kneel in front of it.","Step:2 Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.","Step:3 Extend your left leg behind you, keeping it straight.","Step:4 Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.","Step:5 Hold the stretch for 20-30 seconds, then switch sides and repeat. Emphasize pointed control."}','https://static.exercisedb.dev/media/hjWjJEm.gif','https://static.exercisedb.dev/media/hjWjJEm.gif',NULL),
('hl8DUh8','barbell decline wide-grip press',NULL,'chest','pectorals','{"triceps","shoulders"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your feet secured and your head lower than your hips.","Step:2 Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Step:3 Lower the barbell to your chest, keeping your elbows out to the sides.","Step:4 Push the barbell back up to the starting position, fully extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hl8DUh8.gif','https://static.exercisedb.dev/media/hl8DUh8.gif',NULL),
('hMEptv0','barbell decline bent arm pullover',NULL,'back','lats','{"triceps","chest"}','barbell',NULL,'{"Step:1 Lie down on a decline bench with your head lower than your hips and your feet secured.","Step:2 Hold a barbell with a pronated grip (palms facing away from you) and extend your arms straight above your chest.","Step:3 Lower the barbell behind your head in a controlled manner, keeping your arms slightly bent.","Step:4 Pause for a moment, then raise the barbell back to the starting position by contracting your lats.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hMEptv0.gif','https://static.exercisedb.dev/media/hMEptv0.gif',NULL),
('HMzLjXx','weighted pull-up',NULL,'back','lats','{"biceps","forearms"}','other',NULL,'{"Step:1 Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:2 Hang from the bar with your arms fully extended and your body straight.","Step:3 Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HMzLjXx.gif','https://static.exercisedb.dev/media/HMzLjXx.gif',NULL),
('hnOYgH3','ez barbell jm bench press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lower the barbell to your chest, keeping your elbows tucked in close to your body.","Step:4 Push the barbell back up to the starting position, fully extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hnOYgH3.gif','https://static.exercisedb.dev/media/hnOYgH3.gif',NULL),
('hoXt6wv','left hook. boxing',NULL,'shoulders','delts','{"biceps","triceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Keep your left hand up to protect your face and your right hand by your chin.","Step:3 Rotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.","Step:4 Twist your torso and engage your core muscles to generate power in the punch.","Step:5 Snap your arm back to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hoXt6wv.gif','https://static.exercisedb.dev/media/hoXt6wv.gif',NULL),
('HPlPoQA','cable hammer curl (with rope)',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Stand upright with your feet shoulder-width apart and a slight bend in your knees.","Step:2 Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the cable rope attachment back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HPlPoQA.gif','https://static.exercisedb.dev/media/HPlPoQA.gif',NULL),
('hq2hyDH','dumbbell standing preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Step:2 Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hq2hyDH.gif','https://static.exercisedb.dev/media/hq2hyDH.gif',NULL),
('hrrS0Ed','dumbbell seated lateral raise v. 2',NULL,'shoulders','delts','{"traps","triceps"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Step:2 Keep your back straight and core engaged.","Step:3 Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hrrS0Ed.gif','https://static.exercisedb.dev/media/hrrS0Ed.gif',NULL),
('hrVQWvE','barbell straight leg deadlift',NULL,'legs','hamstrings','{"glutes","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your toes pointing forward.","Step:2 Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Step:4 Lower the barbell until you feel a stretch in your hamstrings.","Step:5 Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hrVQWvE.gif','https://static.exercisedb.dev/media/hrVQWvE.gif',NULL),
('HsjbB1z','smith sprint lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Set up the smith machine with the barbell at hip height.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.","Step:4 Bend your left knee and lower your body into a lunge position, keeping your back straight.","Step:5 Push through your left heel to return to the starting position.","Step:6 Repeat on the other side, stepping back with your left foot.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/HsjbB1z.gif','https://static.exercisedb.dev/media/HsjbB1z.gif',NULL),
('HsvHqgf','dumbbell squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Step:2 Keeping your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.","Step:3 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HsvHqgf.gif','https://static.exercisedb.dev/media/HsvHqgf.gif',NULL),
('ht8xDrP','smith standing behind head military press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height of the smith machine so that the bar is at shoulder level.","Step:2 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:3 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Lift the bar off the rack and step back, maintaining a stable stance.","Step:5 Position the bar behind your head, resting on your upper traps.","Step:6 Keep your core engaged and your chest lifted throughout the exercise.","Step:7 Press the bar overhead by extending your arms, fully straightening them.","Step:8 Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ht8xDrP.gif','https://static.exercisedb.dev/media/ht8xDrP.gif',NULL),
('HtfCpfi','star jump (male)',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms by your sides.","Step:2 Bend your knees slightly and jump up explosively.","Step:3 As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body.","Step:4 Land softly on the balls of your feet with your knees slightly bent.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HtfCpfi.gif','https://static.exercisedb.dev/media/HtfCpfi.gif',NULL),
('hTLtkXL','resistance band seated shoulder press with declined',NULL,'shoulders','delts','{"triceps","upper back"}','resistance band',NULL,'{"Step:1 Sit on a chair or bench with your back straight and feet flat on the ground.","Step:2 Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level.","Step:3 Press the band overhead, extending your arms fully.","Step:4 Pause for a moment at the top, then slowly lower the band back down to shoulder level. Emphasize declined control.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hTLtkXL.gif','https://static.exercisedb.dev/media/hTLtkXL.gif',NULL),
('HUEqZ1y','barbell side split squat v. 2',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointing slightly outwards.","Step:2 Hold a barbell across your upper back, resting it on your shoulders.","Step:3 Take a big step to the side with your right foot, keeping your left foot planted.","Step:4 Bend your right knee and lower your body down into a squat position, keeping your chest up and your back straight.","Step:5 Push through your right heel to return to the starting position.","Step:6 Repeat on the other side, stepping out with your left foot.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/HUEqZ1y.gif','https://static.exercisedb.dev/media/HUEqZ1y.gif',NULL),
('hvHhCv8','cable forward raise',NULL,'shoulders','delts','{"triceps","forearms"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Hold the cable handle with an overhand grip, palms facing down, and your arms fully extended in front of you.","Step:3 Keeping your arms straight, raise the cable handle up to shoulder level.","Step:4 Pause for a moment at the top, then slowly lower the cable handle back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hvHhCv8.gif','https://static.exercisedb.dev/media/hvHhCv8.gif',NULL),
('hvV79Si','cable low seated row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Step:2 Grasp the handles with an overhand grip, palms facing down.","Step:3 Keep your back straight and lean slightly forward, maintaining a slight bend in your elbows.","Step:4 Pull the handles towards your body, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hvV79Si.gif','https://static.exercisedb.dev/media/hvV79Si.gif',NULL),
('hVzPY5j','athletic style battling ropes',NULL,'shoulders','delts','{"forearms","core"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold one end of the rope in each hand, with your palms facing each other.","Step:3 Raise your arms to shoulder height, keeping your elbows slightly bent.","Step:4 (athletic variation) Begin making alternating waves with the ropes by rapidly raising and lowering each arm.","Step:5 Continue for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/hVzPY5j.gif','https://static.exercisedb.dev/media/hVzPY5j.gif',NULL),
('hwygydB','dumbbell preacher curl over exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Step:3 Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/hwygydB.gif','https://static.exercisedb.dev/media/hwygydB.gif',NULL),
('Hx1WC8I','cable incline triceps extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Adjust the cable machine to a low pulley position.","Step:2 Attach a straight bar to the cable.","Step:3 Stand facing away from the machine with your feet shoulder-width apart.","Step:4 Grasp the bar with an overhand grip and extend your arms straight overhead.","Step:5 Lean forward slightly, keeping your back straight and core engaged.","Step:6 Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.","Step:7 Pause for a moment, then extend your arms back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Hx1WC8I.gif','https://static.exercisedb.dev/media/Hx1WC8I.gif',NULL),
('hxyTtWj','dumbbell seated lateral raise',NULL,'shoulders','delts','{"traps","upper back"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and a dumbbell in each hand, resting on your thighs.","Step:2 Keep your back straight and core engaged.","Step:3 Raise the dumbbells to your sides with a slight bend in your elbows, until your arms are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/hxyTtWj.gif','https://static.exercisedb.dev/media/hxyTtWj.gif',NULL),
('Hy9D21L','45° side bend',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms extended straight down by your sides.","Step:2 Keeping your back straight and your core engaged, slowly bend your torso to one side, lowering your hand towards your knee.","Step:3 Pause for a moment at the bottom, then slowly return to the starting position.","Step:4 Repeat on the other side.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/Hy9D21L.gif','https://static.exercisedb.dev/media/Hy9D21L.gif',NULL),
('HYe1ZqR','dumbbell incline fly on exercise ball',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Step:3 Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Step:4 Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Step:5 Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HYe1ZqR.gif','https://static.exercisedb.dev/media/HYe1ZqR.gif',NULL),
('HZgQPxh','suspended abdominal fallout - inclined variation',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Attach a suspension trainer to a high anchor point and adjust the straps to waist height.","Step:2 Stand facing away from the anchor point and hold the handles with your arms extended in front of you. Maintain inclined form throughout.","Step:3 Lean forward at the waist, keeping your body straight and your core engaged.","Step:4 Lower your body as far as you can while maintaining control and tension in your abs.","Step:5 Pause for a moment at the bottom, then slowly raise your body back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/HZgQPxh.gif','https://static.exercisedb.dev/media/HZgQPxh.gif',NULL),
('i11JWU7','cable standing reverse grip one arm overhead tricep extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Stand facing away from the cable machine with your feet shoulder-width apart.","Step:2 Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Step:3 Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Step:4 Pause for a moment at the bottom, then extend your arm back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/i11JWU7.gif','https://static.exercisedb.dev/media/i11JWU7.gif',NULL),
('I1OBLnn','weighted svend press',NULL,'chest','pectorals','{"shoulders","triceps"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands.","Step:2 Keep your elbows slightly bent and your palms facing each other.","Step:3 Press the weight plate straight out in front of you, fully extending your arms.","Step:4 Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/I1OBLnn.gif','https://static.exercisedb.dev/media/I1OBLnn.gif',NULL),
('I3tsCnC','hanging leg raise',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up in front of you, keeping them straight.","Step:3 Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/I3tsCnC.gif','https://static.exercisedb.dev/media/I3tsCnC.gif',NULL),
('I4hDWkc','push-up',NULL,'chest','pectorals','{"triceps","deltoids","core"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Step:2 Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line.","Step:3 Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/I4hDWkc.gif','https://static.exercisedb.dev/media/I4hDWkc.gif',NULL),
('i4JkUaL','barbell side bent v. 2',NULL,'core','abs','{"obliques","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with both hands, palms facing down.","Step:2 Keep your back straight and core engaged throughout the exercise.","Step:3 Slowly bend your torso to the right side, lowering the barbell towards your right knee.","Step:4 Pause for a moment, then return to the starting position.","Step:5 Repeat the movement on the left side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/i4JkUaL.gif','https://static.exercisedb.dev/media/i4JkUaL.gif',NULL),
('I4KkPdl','kettlebell double push press',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.","Step:2 Bend your knees slightly and engage your core.","Step:3 Initiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.","Step:4 As the kettlebells reach the top, press them fully overhead, locking out your arms.","Step:5 Lower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/I4KkPdl.gif','https://static.exercisedb.dev/media/I4KkPdl.gif',NULL),
('I4tibZG','kettlebell alternating hang clean',NULL,'arms','forearms','{"shoulders","traps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Step:3 Allow the kettlebells to hang in front of your body with your arms fully extended.","Step:4 In one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.","Step:5 As the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.","Step:6 Lower the kettlebells back down to the starting position and repeat the movement with the opposite arm.","Step:7 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/I4tibZG.gif','https://static.exercisedb.dev/media/I4tibZG.gif',NULL),
('i5cEhka','decline push-up',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Step:2 Keep your body in a straight line from head to toe, engaging your core muscles.","Step:3 Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Step:4 Push through your palms to extend your arms and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/i5cEhka.gif','https://static.exercisedb.dev/media/i5cEhka.gif',NULL),
('I6Ca0a7','complete style ez bar lying close grip triceps extension behind head',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position. Maintain complete form throughout.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/I6Ca0a7.gif','https://static.exercisedb.dev/media/I6Ca0a7.gif',NULL),
('i6LWjok','barbell pullover',NULL,'back','lats','{"chest","triceps"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet on the floor.","Step:2 Hold a barbell with a shoulder-width grip and extend your arms straight above your chest.","Step:3 Keeping your arms straight, lower the barbell behind your head in a controlled manner until you feel a stretch in your lats.","Step:4 Pause for a moment, then raise the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/i6LWjok.gif','https://static.exercisedb.dev/media/i6LWjok.gif',NULL),
('i8BdLTK','dumbbell straight arm pullover',NULL,'chest','pectorals','{"latissimus dorsi","triceps"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet planted firmly on the ground.","Step:2 Hold a dumbbell with both hands and extend your arms straight above your chest.","Step:3 Keeping your arms straight, slowly lower the dumbbell behind your head in an arc-like motion.","Step:4 Pause for a moment, then raise the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/i8BdLTK.gif','https://static.exercisedb.dev/media/i8BdLTK.gif',NULL),
('ia6kIIl','half knee bends (male)',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Bend your knees and lower your body down as if you were sitting back into a chair.","Step:3 Keep your chest up and your weight in your heels.","Step:4 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ia6kIIl.gif','https://static.exercisedb.dev/media/ia6kIIl.gif',NULL),
('Ia7tumC','dumbbell seated one leg calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground and a dumbbell resting on your right thigh.","Step:2 Extend your left leg straight out in front of you, keeping your foot flexed.","Step:3 Place the ball of your right foot on an elevated surface, such as a step or weight plate.","Step:4 Using your calf muscles, raise your right heel as high as possible.","Step:5 Pause for a moment at the top, then slowly lower your heel back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/Ia7tumC.gif','https://static.exercisedb.dev/media/Ia7tumC.gif',NULL),
('iaapw0g','ez barbell seated triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold the ez barbell with an overhand grip, hands shoulder-width apart.","Step:3 Raise the barbell overhead, fully extending your arms.","Step:4 Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.","Step:5 Pause for a moment, then raise the barbell back to the starting position by extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/iaapw0g.gif','https://static.exercisedb.dev/media/iaapw0g.gif',NULL),
('IaGQCrC','suspended push-up',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Find a suspension trainer and adjust it to an appropriate height.","Step:2 Stand facing away from the anchor point and hold the handles with an overhand grip.","Step:3 Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.","Step:4 Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.","Step:5 Push through your chest and arms to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IaGQCrC.gif','https://static.exercisedb.dev/media/IaGQCrC.gif',NULL),
('IBj3nsn','quick feet v. 2 with bent',NULL,'legs','quads','{"calves","hamstrings"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms by your sides.","Step:2 Begin by rapidly moving your feet up and down, as if you were running in place.","Step:3 Keep your movements quick and light, focusing on staying on the balls of your feet.","Step:4 Continue for the desired duration or number of repetitions. Emphasize bent control."}','https://static.exercisedb.dev/media/IBj3nsn.gif','https://static.exercisedb.dev/media/IBj3nsn.gif',NULL),
('iCPqbki','lever narrow grip seated row - strength variation',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footrests to ensure proper form.","Step:2 Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Step:3 Grasp the handles with a narrow grip, palms facing each other.","Step:4 Keep your back straight and lean slightly forward.","Step:5 Pull the handles towards your torso, squeezing your shoulder blades together.","Step:6 Pause for a moment at the peak of the movement. Maintain strength form throughout.","Step:7 Slowly release the handles and return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/iCPqbki.gif','https://static.exercisedb.dev/media/iCPqbki.gif',NULL),
('iDGtjyi','chest and front of shoulder stretch micro',NULL,'chest','pectorals','{"deltoids"}','body weight',NULL,'{"Step:1 Stand tall with your feet shoulder-width apart.","Step:2 Extend your arms straight out in front of you at shoulder height.","Step:3 Cross your arms in front of your body, with your right arm on top of your left arm.","Step:4 Interlace your fingers and press your palms together.","Step:5 Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Step:6 (micro variation) Hold the stretch for 20-30 seconds, then release.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/iDGtjyi.gif','https://static.exercisedb.dev/media/iDGtjyi.gif',NULL),
('Ie9UGty','lever seated calf press',NULL,'legs','calves','{"soleus","hamstrings"}','machine',NULL,'{"Step:1 Adjust the seat of the machine so that your shoulders are aligned with the lever pad.","Step:2 Place your toes on the lower portion of the platform and position your knees under the lever pad.","Step:3 Grasp the handles on the sides of the seat for stability.","Step:4 Press the lever pad down by extending your ankles, lifting your heels as high as possible.","Step:5 Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ie9UGty.gif','https://static.exercisedb.dev/media/Ie9UGty.gif',NULL),
('IeDEXTe','lever seated squat calf raise on leg press machine',NULL,'legs','calves','{"quadriceps","hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.","Step:2 Sit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.","Step:3 Place your toes and the balls of your feet on the footplate, keeping your heels off the edge.","Step:4 Release the safety handles and push the footplate away from you by extending your knees.","Step:5 Once your knees are fully extended, slowly lower your heels by flexing your calves.","Step:6 Pause for a moment at the bottom, then push the footplate back up by extending your calves.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IeDEXTe.gif','https://static.exercisedb.dev/media/IeDEXTe.gif',NULL),
('IENzBdA','barbell drag curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Step:2 Let the barbell hang at arm's length in front of your thighs.","Step:3 Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.","Step:4 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IENzBdA.gif','https://static.exercisedb.dev/media/IENzBdA.gif',NULL),
('IeTIEqg','barbell front chest squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the barbell in front of your chest with your hands shoulder-width apart, elbows pointing forward.","Step:3 Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.","Step:4 Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IeTIEqg.gif','https://static.exercisedb.dev/media/IeTIEqg.gif',NULL),
('iFsqlCD','prone medicine ball close grip push up',NULL,'arms','triceps','{"chest","shoulders"}','medicine ball',NULL,'{"Step:1 Start in a high plank position with your hands on the medicine ball, shoulder-width apart.","Step:2 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 Push back up to the starting position, fully extending your arms.","Step:4 Repeat for the desired number of repetitions. Maintain prone form throughout."}','https://static.exercisedb.dev/media/iFsqlCD.gif','https://static.exercisedb.dev/media/iFsqlCD.gif',NULL),
('IGjKj1v','lever narrow grip seated row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and footrests to ensure proper form.","Step:2 Sit on the machine with your feet flat on the footrests and your knees slightly bent.","Step:3 Grasp the handles with a narrow grip, palms facing each other.","Step:4 Keep your back straight and lean slightly forward.","Step:5 Pull the handles towards your torso, squeezing your shoulder blades together.","Step:6 Pause for a moment at the peak of the movement.","Step:7 Slowly release the handles and return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IGjKj1v.gif','https://static.exercisedb.dev/media/IGjKj1v.gif',NULL),
('IGtBdNT','dumbbell seated hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IGtBdNT.gif','https://static.exercisedb.dev/media/IGtBdNT.gif',NULL),
('IH2kr7n','dumbbell decline shrug - rigid variation',NULL,'back','traps','{"shoulders","rhomboids"}','dumbbell',NULL,'{"Step:1 Set up a decline bench at a 45-degree angle.","Step:2 Lie face down on the bench with your chest and stomach resting against it.","Step:3 (rigid variation) Hold a dumbbell in each hand with your arms fully extended towards the floor.","Step:4 Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Step:5 Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IH2kr7n.gif','https://static.exercisedb.dev/media/IH2kr7n.gif',NULL),
('iK59oEA','dumbbell lying pullover on exercise ball',NULL,'chest','pectorals','{"triceps","shoulders","back"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Step:2 Hold a dumbbell with both hands and extend your arms straight up over your chest.","Step:3 Slowly lower the dumbbell behind your head while keeping your arms straight.","Step:4 Pause for a moment, then raise the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/iK59oEA.gif','https://static.exercisedb.dev/media/iK59oEA.gif',NULL),
('IL0JUxR','gironda sternum chin',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','body weight',NULL,'{"Step:1 Stand facing a high bar with your feet shoulder-width apart.","Step:2 Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang from the bar with your arms fully extended and your body straight.","Step:4 Engage your lats and biceps to pull your chest up towards the bar, leading with your sternum.","Step:5 Pause for a moment at the top, then slowly lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IL0JUxR.gif','https://static.exercisedb.dev/media/IL0JUxR.gif',NULL),
('ila4NZS','barbell deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and the barbell on the ground in front of you.","Step:2 Bend your knees and hinge at the hips to lower your torso and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Keep your back straight and chest lifted as you drive through your heels to lift the barbell off the ground, extending your hips and knees.","Step:4 As you stand up straight, squeeze your glutes and keep your core engaged.","Step:5 Lower the barbell back down to the ground by bending at the hips and knees, keeping your back straight.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ila4NZS.gif','https://static.exercisedb.dev/media/ila4NZS.gif',NULL),
('IMRsOCn','squat jerk',NULL,'legs','quads','{"glutes","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Start with the barbell resting on your shoulders, with your feet shoulder-width apart.","Step:2 Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.","Step:3 As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.","Step:4 As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.","Step:5 Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.","Step:6 Stand up from the split position, bringing your feet back together.","Step:7 Lower the barbell back to your shoulders and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IMRsOCn.gif','https://static.exercisedb.dev/media/IMRsOCn.gif',NULL),
('iny3m5y','dead bug',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your arms extended towards the ceiling.","Step:2 Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Step:3 Engage your core and lower back to press your lower back into the ground.","Step:4 Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Step:5 Pause for a moment, then return to the starting position.","Step:6 Repeat the movement with your left arm and right leg.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/iny3m5y.gif','https://static.exercisedb.dev/media/iny3m5y.gif',NULL),
('Ion0XWz','dumbbell lying on floor rear delt raise',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Step:3 Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ion0XWz.gif','https://static.exercisedb.dev/media/Ion0XWz.gif',NULL),
('ioTf098','cable overhead curl on exercise ball',NULL,'arms','biceps','{"forearms","shoulders"}','cable',NULL,'{"Step:1 Sit on an exercise ball and hold the cable handle with an underhand grip.","Step:2 Extend your arms fully overhead, keeping your elbows close to your ears.","Step:3 Slowly curl the cable down towards your forehead, keeping your upper arms stationary.","Step:4 Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ioTf098.gif','https://static.exercisedb.dev/media/ioTf098.gif',NULL),
('iPm26QU','box jump down with one leg stabilization',NULL,'legs','calves','{"quadriceps","hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand in front of a box or platform with your feet shoulder-width apart.","Step:2 Bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.","Step:3 Stabilize yourself on the box with the foot that is on it, while keeping the other foot off the ground.","Step:4 Hold this position for a few seconds, engaging your calf muscles to maintain balance.","Step:5 Slowly step down with the foot that is on the box, returning to the starting position.","Step:6 Repeat the exercise with the other leg."}','https://static.exercisedb.dev/media/iPm26QU.gif','https://static.exercisedb.dev/media/iPm26QU.gif',NULL),
('IpONWYv','dumbbell side bend',NULL,'core','abs','{"obliques"}','dumbbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand, letting it hang down by your side.","Step:2 Keeping your back straight and your core engaged, slowly bend sideways at the waist towards the opposite side of the dumbbell, lowering the weight as far as you comfortably can.","Step:3 Pause for a moment, then slowly return to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch sides and repeat."}','https://static.exercisedb.dev/media/IpONWYv.gif','https://static.exercisedb.dev/media/IpONWYv.gif',NULL),
('Iptlv6x','dumbbell upright row (back pov)',NULL,'shoulders','delts','{"traps","biceps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Let the dumbbells hang in front of your thighs, with your arms fully extended and your palms facing your body.","Step:3 Keeping your back straight and your core engaged, exhale and lift the dumbbells straight up towards your chin, leading with your elbows.","Step:4 Continue lifting until the dumbbells are at shoulder height, with your elbows pointing out to the sides.","Step:5 Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Iptlv6x.gif','https://static.exercisedb.dev/media/Iptlv6x.gif',NULL),
('ipvgBnC','barbell seated calf raise',NULL,'legs','calves','{"hamstrings"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Step:2 Place the balls of your feet on a raised platform, such as a block or step.","Step:3 Lower your heels as far as possible, feeling a stretch in your calves.","Step:4 Raise your heels as high as possible, contracting your calves.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ipvgBnC.gif','https://static.exercisedb.dev/media/ipvgBnC.gif',NULL),
('iQ241UP','half sit-up (male)',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/iQ241UP.gif','https://static.exercisedb.dev/media/iQ241UP.gif',NULL),
('iqH55N8','fierce style forward lunge (male)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet hip-width apart and hands on your hips.","Step:2 Take a big step forward with your right foot, lowering your body into a lunge position.","Step:3 Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Step:4 Push off with your right foot and return to the starting position.","Step:5 (fierce variation) Repeat with your left leg, alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/iqH55N8.gif','https://static.exercisedb.dev/media/iqH55N8.gif',NULL),
('isAAZWA','side-to-side chin',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Hang from the bar with your arms fully extended and your body relaxed.","Step:4 Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Step:5 Once your chin is above the bar, lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/isAAZWA.gif','https://static.exercisedb.dev/media/isAAZWA.gif',NULL),
('isofgzg','roller back stretch',NULL,'back','spine','{"hamstrings","glutes"}','other',NULL,'{"Step:1 Start by sitting on the ground with your legs extended in front of you.","Step:2 Place the roller perpendicular to your body, just below your glutes.","Step:3 Slowly roll your body backwards, allowing the roller to move up your back.","Step:4 Continue rolling until the roller reaches your upper back.","Step:5 Pause for a moment, then slowly roll back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/isofgzg.gif','https://static.exercisedb.dev/media/isofgzg.gif',NULL),
('IU4QNJ6','pure chin-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Step:2 Engage your core and pull your body up towards the bar, leading with your chest. Emphasize pure control.","Step:3 Continue pulling until your chin is above the bar.","Step:4 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IU4QNJ6.gif','https://static.exercisedb.dev/media/IU4QNJ6.gif',NULL),
('IvV6C9M','dumbbell over bench one arm neutral wrist curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Step:2 Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/IvV6C9M.gif','https://static.exercisedb.dev/media/IvV6C9M.gif',NULL),
('IwX5NqK','cable reverse preacher curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the preacher curl pad is at chest height.","Step:2 Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.","Step:3 Grab the cable handles with an underhand grip, shoulder-width apart.","Step:4 Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.","Step:5 Pause for a moment at the top of the movement, squeezing your biceps.","Step:6 Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IwX5NqK.gif','https://static.exercisedb.dev/media/IwX5NqK.gif',NULL),
('IxsFgRT','cable judo flip with static',NULL,'core','abs','{"obliques","shoulders"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Hold the cable handle with both hands at chest level, palms facing down.","Step:3 Engage your core and rotate your torso to the right, pulling the cable across your body.","Step:4 As you rotate, pivot your back foot and allow your hips to rotate naturally. Emphasize static control.","Step:5 Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Step:6 Return to the starting position by reversing the movement, rotating your torso back to the center.","Step:7 Repeat the movement on the opposite side.","Step:8 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/IxsFgRT.gif','https://static.exercisedb.dev/media/IxsFgRT.gif',NULL),
('iYzB0Cz','barbell full squat (side pov)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the barbell across your upper back, resting it on your traps or rear delts.","Step:3 Engage your core and keep your chest up as you begin to lower your body down.","Step:4 Bend at the knees and hips, pushing your hips back and down as if sitting into a chair.","Step:5 Lower your body until your thighs are parallel to the ground or slightly below.","Step:6 Keep your knees in line with your toes and your weight in your heels.","Step:7 Drive through your heels to stand back up, extending your hips and knees.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/iYzB0Cz.gif','https://static.exercisedb.dev/media/iYzB0Cz.gif',NULL),
('izMnLqz','dumbbell alternate side press',NULL,'shoulders','delts','{"triceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Step:2 Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Step:3 Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Step:4 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/izMnLqz.gif','https://static.exercisedb.dev/media/izMnLqz.gif',NULL),
('iZop9xO','barbell lying triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.","Step:4 Pause for a moment at the bottom, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/iZop9xO.gif','https://static.exercisedb.dev/media/iZop9xO.gif',NULL),
('IZVHb27','walking lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Take a step forward with your right leg, lowering your body into a lunge position.","Step:3 Keep your torso upright and your front knee aligned with your ankle.","Step:4 Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.","Step:5 Continue alternating legs and walking forward, maintaining a controlled and steady pace.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/IZVHb27.gif','https://static.exercisedb.dev/media/IZVHb27.gif',NULL),
('J1vH2X0','weighted one hand pull up fast',NULL,'back','lats','{"biceps","forearms"}','other',NULL,'{"Step:1 Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.","Step:2 Hang from the bar with your arm fully extended and your body straight.","Step:3 Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.","Step:4 Continue pulling until your chin is above the bar.","Step:5 (fast variation) Lower your body back down to the starting position with control.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/J1vH2X0.gif','https://static.exercisedb.dev/media/J1vH2X0.gif',NULL),
('J60bN17','assisted triceps dip (kneeling)',NULL,'arms','triceps','{"chest","shoulders"}','machine',NULL,'{"Step:1 Adjust the machine to your desired weight and height.","Step:2 Kneel down on the pad facing the machine, with your hands gripping the handles.","Step:3 Lower your body by bending your elbows, keeping your back straight and close to the machine.","Step:4 Pause for a moment at the bottom, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/J60bN17.gif','https://static.exercisedb.dev/media/J60bN17.gif',NULL),
('J6Dx1Mu','barbell close-grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.","Step:3 Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.","Step:4 Pause for a moment when the barbell touches your chest.","Step:5 Push the barbell back up to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/J6Dx1Mu.gif','https://static.exercisedb.dev/media/J6Dx1Mu.gif',NULL),
('j6uIfep','contracted kettlebell extended range one arm press on floor',NULL,'chest','pectorals','{"triceps","shoulders"}','kettlebell',NULL,'{"Step:1 Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Step:2 Hold a kettlebell in one hand, with your palm facing towards your feet.","Step:3 Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Step:4 Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm. Emphasize contracted control."}','https://static.exercisedb.dev/media/j6uIfep.gif','https://static.exercisedb.dev/media/j6uIfep.gif',NULL),
('j74M6Zn','exercise ball on the wall calf raise (tennis ball between knees)',NULL,'legs','calves','{"quadriceps","hamstrings"}','dumbbell',NULL,'{"Step:1 Stand with your back against a wall and place an exercise ball between your lower back and the wall.","Step:2 Position your feet shoulder-width apart and slightly in front of you.","Step:3 Hold a dumbbell in each hand, with your arms extended by your sides.","Step:4 Place a tennis ball between your knees.","Step:5 Raise your heels off the ground, lifting your body up onto your toes.","Step:6 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/j74M6Zn.gif','https://static.exercisedb.dev/media/j74M6Zn.gif',NULL),
('J74XlNf','dumbbell alternating seated bicep curl on exercise ball',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Step:4 Inhale and slowly lower the dumbbell back to the starting position.","Step:5 Repeat the curl with the other arm.","Step:6 Continue alternating curls for the desired number of repetitions."}','https://static.exercisedb.dev/media/J74XlNf.gif','https://static.exercisedb.dev/media/J74XlNf.gif',NULL),
('j7XMAyn','cable upper chest crossovers',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Attach the handles to the cables at chest height.","Step:2 Stand in the center of the cable machine with one foot slightly in front of the other.","Step:3 Grasp the handles with your palms facing down and your arms extended out to the sides.","Step:4 Keep a slight bend in your elbows and engage your core.","Step:5 Pull the cables together in front of your chest, crossing them over each other.","Step:6 Squeeze your chest muscles at the peak of the movement.","Step:7 Slowly release the cables back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/j7XMAyn.gif','https://static.exercisedb.dev/media/j7XMAyn.gif',NULL),
('j9Q5crt','walking on stepmill',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','stepmill machine',NULL,'{"Step:1 Adjust the stepmill machine to a comfortable level.","Step:2 Step onto the machine and place your hands on the handrails for support.","Step:3 Start walking by placing one foot on a step and then the other, alternating between legs.","Step:4 Maintain an upright posture and engage your core muscles.","Step:5 Continue walking for the desired duration or distance.","Step:6 Gradually increase the intensity or speed as you become more comfortable with the exercise.","Step:7 Remember to cool down and stretch after completing the exercise."}','https://static.exercisedb.dev/media/j9Q5crt.gif','https://static.exercisedb.dev/media/j9Q5crt.gif',NULL),
('J9zIWig','walking high knees lunge',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','body weight',NULL,'{"Step:1 Stand with your feet hip-width apart.","Step:2 Lift your right knee up towards your chest as high as you can while balancing on your left leg.","Step:3 Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle.","Step:4 Push off with your right foot and bring your left knee up towards your chest.","Step:5 Step forward with your left foot and lower your body into a lunge position.","Step:6 Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/J9zIWig.gif','https://static.exercisedb.dev/media/J9zIWig.gif',NULL),
('JbC2iaV','spine stretch',NULL,'back','spine','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you.","Step:2 Place your hands on the ground behind you, fingers pointing towards your body.","Step:3 Engage your core and slowly lean back, keeping your back straight.","Step:4 Continue leaning back until you feel a stretch in your spine.","Step:5 Hold the stretch for a few seconds, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JbC2iaV.gif','https://static.exercisedb.dev/media/JbC2iaV.gif',NULL),
('jCBOdh0','rough cable decline fly',NULL,'chest','pectorals','{"shoulders","triceps"}','cable',NULL,'{"Step:1 Adjust the cable machine to a decline position.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Hold the handles with your palms facing forward and your arms extended straight out in front of you.","Step:4 Keeping a slight bend in your elbows, open your arms out to the sides in a controlled motion. Perform with rough intensity.","Step:5 Pause for a moment at the fully extended position, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jCBOdh0.gif','https://static.exercisedb.dev/media/jCBOdh0.gif',NULL),
('jCrtE9b','one arm slam (with medicine ball)',NULL,'core','abs','{"shoulders","back"}','medicine ball',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist.","Step:2 Bend your knees slightly and engage your core.","Step:3 Raise the medicine ball above your head, fully extending your arm.","Step:4 Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power.","Step:5 Catch the medicine ball on the bounce and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jCrtE9b.gif','https://static.exercisedb.dev/media/jCrtE9b.gif',NULL),
('jdiExfW','inverted row with straps',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Set up a suspension trainer or straps at chest height.","Step:2 Stand facing the anchor point and grab the handles with an overhand grip.","Step:3 Walk your feet forward, leaning back until your body is at an angle.","Step:4 Keep your body straight and engage your core.","Step:5 Pull your chest towards the handles, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower yourself back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jdiExfW.gif','https://static.exercisedb.dev/media/jdiExfW.gif',NULL),
('jDnrkar','dumbbell incline one arm hammer press on exercise ball',NULL,'arms','triceps','{"shoulders","chest"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand.","Step:2 Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Step:4 Press the dumbbell up towards the ceiling, straightening your arm.","Step:5 Lower the dumbbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/jDnrkar.gif','https://static.exercisedb.dev/media/jDnrkar.gif',NULL),
('jDOKRM5','side lying floor stretch',NULL,'back','lats','{"obliques","glutes"}','body weight',NULL,'{"Step:1 Lie on your side with your legs straight and your bottom arm extended straight overhead.","Step:2 Bend your top knee and place your foot on the ground in front of your bottom leg.","Step:3 Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.","Step:4 Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.","Step:5 Hold the stretch for 20-30 seconds, then slowly lower your leg back down.","Step:6 Repeat on the other side."}','https://static.exercisedb.dev/media/jDOKRM5.gif','https://static.exercisedb.dev/media/jDOKRM5.gif',NULL),
('jeHtrlO','medicine ball chest push single response',NULL,'chest','pectorals','{"triceps","shoulders"}','medicine ball',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding the medicine ball at chest level.","Step:2 Extend your arms forward, pushing the medicine ball away from your chest.","Step:3 Pause for a moment, then slowly bring the medicine ball back to your chest.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jeHtrlO.gif','https://static.exercisedb.dev/media/jeHtrlO.gif',NULL),
('JF8AkMX','standing archer',NULL,'back','upper back','{"shoulders","biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Extend your arms straight out in front of you at shoulder height, parallel to the ground.","Step:3 Rotate your torso to the right, keeping your arms extended and your back straight.","Step:4 As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.","Step:5 Hold the position for a moment, then return to the starting position.","Step:6 Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/JF8AkMX.gif','https://static.exercisedb.dev/media/JF8AkMX.gif',NULL),
('jFtipLl','smith squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Set up the smith machine with the barbell at an appropriate height for your squat.","Step:2 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:3 Position yourself under the barbell, resting it on your upper traps and shoulders.","Step:4 Grip the barbell with a wide grip, slightly wider than shoulder-width apart.","Step:5 Engage your core and unrack the barbell, stepping back to clear the rack.","Step:6 Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.","Step:7 Lower your body until your thighs are parallel to the ground or slightly below.","Step:8 Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jFtipLl.gif','https://static.exercisedb.dev/media/jFtipLl.gif',NULL),
('jgbvVJ0','dumbbell incline t-raise',NULL,'shoulders','delts','{"traps","rhomboids"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Step:2 Lean forward and let your arms hang straight down, perpendicular to the floor.","Step:3 Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a 'T' shape with your body.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jgbvVJ0.gif','https://static.exercisedb.dev/media/jgbvVJ0.gif',NULL),
('JGKowMS','smith narrow row',NULL,'back','upper back','{"biceps","rear deltoids"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your feet flat on the floor.","Step:2 Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.","Step:3 Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.","Step:4 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JGKowMS.gif','https://static.exercisedb.dev/media/JGKowMS.gif',NULL),
('jHAnWmT','lever incline chest press',NULL,'chest','pectorals','{"shoulders","triceps"}','machine',NULL,'{"Step:1 Adjust the seat and backrest of the leverage machine to a comfortable position.","Step:2 Sit on the machine with your back against the backrest and your feet flat on the floor.","Step:3 Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Step:4 Push the handles forward and away from your body until your arms are fully extended.","Step:5 Pause for a moment, then slowly bend your elbows and lower the handles back towards your chest.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jHAnWmT.gif','https://static.exercisedb.dev/media/jHAnWmT.gif',NULL),
('JhYSVwT','dumbbell seated bench extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell with both hands and extend your arms straight up above your head.","Step:3 Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.","Step:4 Pause for a moment, then raise the dumbbell back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JhYSVwT.gif','https://static.exercisedb.dev/media/JhYSVwT.gif',NULL),
('jivWf8n','dumbbell preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Step:2 Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jivWf8n.gif','https://static.exercisedb.dev/media/jivWf8n.gif',NULL),
('jjUPrze','smith standing military press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.","Step:4 Press the barbell upward until your arms are fully extended overhead.","Step:5 Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jjUPrze.gif','https://static.exercisedb.dev/media/jjUPrze.gif',NULL),
('jK2hZ6n','dumbbell one arm seated hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Step:3 Rest your elbow on the inside of your thigh, just above the knee.","Step:4 Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Step:5 Pause for a moment at the top, squeezing your biceps.","Step:6 Inhale and slowly lower the dumbbell back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/jK2hZ6n.gif','https://static.exercisedb.dev/media/jK2hZ6n.gif',NULL),
('jl6uxZV','band two legs calf raise - (band under both legs) v. 2',NULL,'legs','calves','{"ankles","feet"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place a resistance band under both feet.","Step:2 Hold the ends of the band with your hands for stability.","Step:3 Raise your heels off the ground as high as possible, using your calves.","Step:4 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jl6uxZV.gif','https://static.exercisedb.dev/media/jl6uxZV.gif',NULL),
('JmMVpR3','wide hand push up',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands wider than shoulder-width apart.","Step:2 Keep your body in a straight line from head to toe.","Step:3 Lower your chest towards the ground by bending your elbows, keeping them close to your sides.","Step:4 Push through your palms to extend your arms and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JmMVpR3.gif','https://static.exercisedb.dev/media/JmMVpR3.gif',NULL),
('jNU1gFQ','outside leg kick push-up',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Step:2 Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged.","Step:3 As you push back up, kick one leg out to the side, extending it fully and engaging your glutes.","Step:4 Return your leg to the starting position and repeat the push-up, alternating legs with each repetition.","Step:5 Continue alternating leg kicks and push-ups for the desired number of repetitions."}','https://static.exercisedb.dev/media/jNU1gFQ.gif','https://static.exercisedb.dev/media/jNU1gFQ.gif',NULL),
('JOZhu2h','cable standing twist row (v-bar)',NULL,'back','upper back','{"biceps","shoulders"}','cable',NULL,'{"Step:1 Attach a v-bar attachment to a cable machine at chest height.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Grasp the v-bar with an overhand grip, palms facing down.","Step:4 Take a step back to create tension in the cable.","Step:5 Keep your back straight and core engaged throughout the exercise.","Step:6 Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","Step:7 As you pull, twist your torso to one side, squeezing your shoulder blades together.","Step:8 Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Step:9 Slowly release the tension and return to the starting position, untwisting your torso.","Step:10 Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."}','https://static.exercisedb.dev/media/JOZhu2h.gif','https://static.exercisedb.dev/media/JOZhu2h.gif',NULL),
('jpgqxiS','cable standing crunch',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Attach a cable handle to a high pulley and stand facing away from the machine.","Step:2 Hold the handle with both hands and place it behind your head, keeping your elbows bent.","Step:3 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:4 Keeping your abs engaged, exhale and crunch your torso down towards your knees, bringing your elbows towards your thighs.","Step:5 Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jpgqxiS.gif','https://static.exercisedb.dev/media/jpgqxiS.gif',NULL),
('jQGwmxN','trap bar deadlift',NULL,'legs','glutes','{"hamstrings","quadriceps","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.","Step:2 Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.","Step:3 Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.","Step:4 As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.","Step:5 Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jQGwmxN.gif','https://static.exercisedb.dev/media/jQGwmxN.gif',NULL),
('JrOHAZc','barbell stiff leg good morning',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Hold the barbell across your upper back, resting it on your traps.","Step:3 Keeping your back straight, hinge forward at the hips, pushing your glutes back.","Step:4 Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.","Step:5 Engage your glutes and hamstrings to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JrOHAZc.gif','https://static.exercisedb.dev/media/JrOHAZc.gif',NULL),
('Jsgsc27','barbell one arm bent over row',NULL,'back','upper back','{"biceps","forearms"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a barbell with one hand using an overhand grip.","Step:2 Bend forward at the hips, keeping your back straight and your head in a neutral position.","Step:3 Pull the barbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Step:4 Lower the barbell back down to the starting position in a controlled manner.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/Jsgsc27.gif','https://static.exercisedb.dev/media/Jsgsc27.gif',NULL),
('JsKq9so','barbell wide bench press',NULL,'chest','pectorals','{"shoulders","triceps"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.","Step:3 Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.","Step:4 Lower the barbell slowly towards your chest, keeping your elbows slightly flared out.","Step:5 Pause for a moment when the barbell touches your chest, then push it back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JsKq9so.gif','https://static.exercisedb.dev/media/JsKq9so.gif',NULL),
('JsOV1SU','weighted muscle up',NULL,'back','lats','{"biceps","triceps","shoulders","chest"}','other',NULL,'{"Step:1 Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Step:2 Engage your core and pull your body up towards the bar, leading with your chest.","Step:3 As you reach the top of the movement, transition your grip so that your palms are facing towards you.","Step:4 Continue pulling yourself up until your chest reaches the bar, then pause for a moment.","Step:5 Slowly lower yourself back down to the starting position, maintaining control throughout the movement.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JsOV1SU.gif','https://static.exercisedb.dev/media/JsOV1SU.gif',NULL),
('jtFKbt5','ez barbell seated curls',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and your back straight.","Step:2 Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.","Step:3 Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.","Step:4 Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.","Step:5 Pause for a moment at the top, squeezing your biceps.","Step:6 Inhale and slowly lower the ez barbell back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jtFKbt5.gif','https://static.exercisedb.dev/media/jtFKbt5.gif',NULL),
('jTkSc6o','side hip (on parallel bars)',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Stand between two parallel bars with your feet shoulder-width apart.","Step:2 Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.","Step:3 Engage your abs and slowly lift your legs to the side, keeping them straight.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jTkSc6o.gif','https://static.exercisedb.dev/media/jTkSc6o.gif',NULL),
('jV65tKx','scapula push-up',NULL,'chest','serratus anterior','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Step:2 Lower your chest towards the ground, keeping your elbows close to your body.","Step:3 As you lower, squeeze your shoulder blades together and push your chest forward.","Step:4 Pause for a moment at the bottom, then push back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/jV65tKx.gif','https://static.exercisedb.dev/media/jV65tKx.gif',NULL),
('jvEXp4N','endurance style one arm dip',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Stand facing away from a bench or chair, with your feet shoulder-width apart.","Step:2 Place one hand on the bench or chair behind you, fingers pointing towards your body. Maintain endurance form throughout.","Step:3 Extend your legs out in front of you, keeping your heels on the ground.","Step:4 Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.","Step:5 Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."}','https://static.exercisedb.dev/media/jvEXp4N.gif','https://static.exercisedb.dev/media/jvEXp4N.gif',NULL),
('jvp6DiD','elbow-to-knee',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Start by lying flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee.","Step:4 At the same time, bring your left knee towards your right elbow, creating a twisting motion.","Step:5 Pause for a moment at the top, then slowly lower your upper body and extend your legs back to the starting position.","Step:6 Repeat the movement, this time bringing your left elbow towards your right knee and your right knee towards your left elbow.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/jvp6DiD.gif','https://static.exercisedb.dev/media/jvp6DiD.gif',NULL),
('JWjujiY','dumbbell one arm prone curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Step:2 Extend your arm fully, letting it hang straight down towards the floor.","Step:3 Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/JWjujiY.gif','https://static.exercisedb.dev/media/JWjujiY.gif',NULL),
('JxrY9mC','stability style band kneeling one arm pulldown',NULL,'back','lats','{"biceps","rhomboids"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point above your head.","Step:2 Kneel down and hold the band with one hand, palm facing down.","Step:3 Extend your arm fully overhead, keeping your elbow slightly bent.","Step:4 Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Step:5 Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides. Perform with stability intensity."}','https://static.exercisedb.dev/media/JxrY9mC.gif','https://static.exercisedb.dev/media/JxrY9mC.gif',NULL),
('JymLInS','dumbbell incline shrug',NULL,'back','traps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Step:2 Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Step:3 Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Step:4 Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JymLInS.gif','https://static.exercisedb.dev/media/JymLInS.gif',NULL),
('JzQbv7J','dumbbell seated bent arm lateral raise',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.","Step:3 Keeping your elbows bent, raise your arms out to the sides until they are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JzQbv7J.gif','https://static.exercisedb.dev/media/JzQbv7J.gif',NULL),
('JZuApnB','weighted squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing slightly outward.","Step:2 Hold a weight in front of your chest or on your shoulders.","Step:3 Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair.","Step:4 Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Push through your heels to stand back up, squeezing your glutes at the top.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/JZuApnB.gif','https://static.exercisedb.dev/media/JZuApnB.gif',NULL),
('K1vlode','weighted triceps dip on high parallel bars',NULL,'arms','triceps','{"chest","shoulders"}','other',NULL,'{"Step:1 Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.","Step:2 Bend your elbows and lower your body until your upper arms are parallel to the ground.","Step:3 Pause for a moment, then push through your palms to straighten your arms and return to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/K1vlode.gif','https://static.exercisedb.dev/media/K1vlode.gif',NULL),
('K3dIO25','dumbbell lying one arm press v. 2',NULL,'chest','pectorals','{"triceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your back supported and feet flat on the ground.","Step:2 Hold a dumbbell in one hand with your palm facing towards your feet.","Step:3 Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Step:4 Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Step:5 Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/K3dIO25.gif','https://static.exercisedb.dev/media/K3dIO25.gif',NULL),
('k5IpyHg','dumbbell one arm concentration curl (on stability ball)',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Step:3 Rest your elbow on the inside of your thigh, just above the knee.","Step:4 Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Step:5 Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms and repeat."}','https://static.exercisedb.dev/media/k5IpyHg.gif','https://static.exercisedb.dev/media/k5IpyHg.gif',NULL),
('K5xgdvI','reclining big toe pose with rope',NULL,'legs','hamstrings','{"calves","glutes"}','other',NULL,'{"Step:1 Lie on your back with your legs extended and your arms by your sides.","Step:2 Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.","Step:3 Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.","Step:4 Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.","Step:5 Repeat with your left leg.","Step:6 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/K5xgdvI.gif','https://static.exercisedb.dev/media/K5xgdvI.gif',NULL),
('k6tUeqS','band underhand pulldown',NULL,'back','lats','{"biceps","forearms"}','resistance band',NULL,'{"Step:1 Attach the band to a high anchor point, such as a pull-up bar or sturdy beam.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Grasp the band with an underhand grip, hands slightly wider than shoulder-width apart.","Step:4 Extend your arms fully overhead, keeping your elbows slightly bent.","Step:5 Engage your lats and pull the band down towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement, then slowly release the tension and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/k6tUeqS.gif','https://static.exercisedb.dev/media/k6tUeqS.gif',NULL),
('K9VL0Jq','lunge with twist',NULL,'core','abs','{"quadriceps","glutes","hamstrings"}','body weight',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 As you lunge, twist your torso to the right, bringing your left elbow towards your right knee.","Step:4 Pause for a moment, then return to the starting position.","Step:5 Repeat on the other side, stepping forward with your left foot and twisting your torso to the left.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/K9VL0Jq.gif','https://static.exercisedb.dev/media/K9VL0Jq.gif',NULL),
('Kal9cQQ','kettlebell advanced windmill',NULL,'core','abs','{"obliques","shoulders"}','kettlebell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.","Step:2 Hold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.","Step:3 Rotate your left foot slightly to the right, and shift your weight onto your left leg.","Step:4 Bend your left knee and hinge at the hip, lowering your torso towards the left side.","Step:5 Keep your right arm extended overhead and your eyes on the kettlebell.","Step:6 As you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.","Step:7 Lower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.","Step:8 Pause for a moment, then engage your core and push through your left heel to return to the starting position.","Step:9 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/Kal9cQQ.gif','https://static.exercisedb.dev/media/Kal9cQQ.gif',NULL),
('KCBKjma','band jack knife sit-up',NULL,'core','abs','{"hip flexors"}','resistance band',NULL,'{"Step:1 Lie flat on your back with your legs straight and your arms extended overhead, holding the band.","Step:2 Engage your abs and lift your legs and upper body simultaneously, bringing your hands towards your feet.","Step:3 Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KCBKjma.gif','https://static.exercisedb.dev/media/KCBKjma.gif',NULL),
('KenZJQV','barbell high bar squat core',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Place the barbell on your upper back, resting it on your traps.","Step:3 Engage your core and keep your chest up as you begin to squat down, pushing your hips back and bending your knees. Perform with core intensity.","Step:4 Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Drive through your heels to stand back up, extending your hips and knees.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KenZJQV.gif','https://static.exercisedb.dev/media/KenZJQV.gif',NULL),
('kesXOpB','cable decline seated wide-grip row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the decline bench facing the cable machine with your feet securely placed on the footrests.","Step:2 Grasp the cable attachment with a wide overhand grip, palms facing down.","Step:3 Lean back slightly, keeping your back straight and your core engaged.","Step:4 Pull the cable towards your lower chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kesXOpB.gif','https://static.exercisedb.dev/media/kesXOpB.gif',NULL),
('KgI0tqW','barbell sumo deadlift',NULL,'legs','glutes','{"hamstrings","quadriceps","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointing outwards.","Step:2 Place a barbell on the ground in front of you, centered between your feet.","Step:3 Bend your knees and lower your hips, keeping your back straight and chest up, to grip the barbell with an overhand grip.","Step:4 Engage your core and drive through your heels to lift the barbell off the ground, extending your hips and knees simultaneously.","Step:5 As you lift, keep your chest up and back straight, and push your hips forward to fully engage your glutes.","Step:6 Pause for a moment at the top, then slowly lower the barbell back down to the starting position, maintaining control throughout the movement.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KgI0tqW.gif','https://static.exercisedb.dev/media/KgI0tqW.gif',NULL),
('KHGNa16','cable decline one arm press',NULL,'chest','pectorals','{"triceps","shoulders"}','cable',NULL,'{"Step:1 Adjust the cable machine to a decline position.","Step:2 Stand facing away from the machine and grab the handle with one hand.","Step:3 Position yourself with your back against the decline bench and your arm extended straight in front of you.","Step:4 Bend your elbow and lower the handle towards your chest while keeping your upper arm stationary.","Step:5 Pause for a moment at the bottom, then push the handle back up to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/KHGNa16.gif','https://static.exercisedb.dev/media/KHGNa16.gif',NULL),
('KhHJ338','push-up to side plank',NULL,'core','abs','{"shoulders","chest","triceps"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Step:2 Lower your body towards the ground by bending your elbows, keeping your core engaged.","Step:3 Push back up to the starting position.","Step:4 Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Step:5 Hold the side plank position for a few seconds, then return to the starting position.","Step:6 Repeat the push-up and side plank on the opposite side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/KhHJ338.gif','https://static.exercisedb.dev/media/KhHJ338.gif',NULL),
('khlHMqs','band bench press',NULL,'chest','pectorals','{"triceps","shoulders"}','resistance band',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Grasp the band handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Extend your arms fully, pushing the bands away from your chest.","Step:4 Slowly lower the bands back down to your chest, keeping your elbows at a 90-degree angle.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/khlHMqs.gif','https://static.exercisedb.dev/media/khlHMqs.gif',NULL),
('KHPZL0b','cable alternate shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and grasp the handles of the cable machine with an overhand grip.","Step:2 Position your hands at shoulder height, with your palms facing forward.","Step:3 Keep your core engaged and your back straight.","Step:4 Press one handle up and forward until your arm is fully extended.","Step:5 Pause for a moment at the top, then slowly lower the handle back to the starting position.","Step:6 Repeat with the other arm.","Step:7 Alternate between arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/KHPZL0b.gif','https://static.exercisedb.dev/media/KHPZL0b.gif',NULL),
('KI1DjNN','dumbbell over bench one arm wrist curl',NULL,'arms','forearms','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Step:2 Rest your forearm on the bench with your wrist hanging off the edge.","Step:3 Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/KI1DjNN.gif','https://static.exercisedb.dev/media/KI1DjNN.gif',NULL),
('kiJ4Z2K','assisted pull-up',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the machine to your desired weight and height settings.","Step:2 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang with your arms fully extended and your feet off the ground.","Step:4 Engage your back muscles and pull your body up towards the handles, keeping your elbows close to your body.","Step:5 Continue pulling until your chin is above the handles.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kiJ4Z2K.gif','https://static.exercisedb.dev/media/kiJ4Z2K.gif',NULL),
('kj3hy6W','lever reverse grip preacher curl',NULL,'arms','biceps','{"forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the leverage machine.","Step:2 Grasp the handles with an underhand grip, palms facing up.","Step:3 Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.","Step:4 Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Step:5 Pause for a moment at the top of the movement, squeezing your biceps.","Step:6 Inhale and slowly lower the handles back to the starting position, fully extending your elbows.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kj3hy6W.gif','https://static.exercisedb.dev/media/kj3hy6W.gif',NULL),
('kjE55n5','kettlebell bent press',NULL,'core','abs','{"shoulders","triceps","obliques"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Step:2 Bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.","Step:3 Rotate your torso to the left, shifting your weight onto your left foot.","Step:4 Bend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.","Step:5 As you lower, keep your eyes on the kettlebell and your chest lifted.","Step:6 Once your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.","Step:7 As you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.","Step:8 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/kjE55n5.gif','https://static.exercisedb.dev/media/kjE55n5.gif',NULL),
('kjJ3VoQ','crunch (hands overhead)',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Extend your arms straight above your head.","Step:3 Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kjJ3VoQ.gif','https://static.exercisedb.dev/media/kjJ3VoQ.gif',NULL),
('kk39rUy','push-up to side plank - athletic variation',NULL,'core','abs','{"shoulders","chest","triceps"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Step:2 Lower your body towards the ground by bending your elbows, keeping your core engaged.","Step:3 Push back up to the starting position. Emphasize athletic control.","Step:4 Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling.","Step:5 Hold the side plank position for a few seconds, then return to the starting position.","Step:6 Repeat the push-up and side plank on the opposite side.","Step:7 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/kk39rUy.gif','https://static.exercisedb.dev/media/kk39rUy.gif',NULL),
('kKYTkjJ','exercise ball one leg prone lower body rotation fierce',NULL,'legs','glutes','{"hamstrings","quadriceps","core"}','other',NULL,'{"Step:1 Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Step:2 Place your hands on the ground in front of you for support.","Step:3 Engage your glutes and core muscles to stabilize your body.","Step:4 Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Step:5 Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Step:6 Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Step:7 Repeat the rotation with the other leg. Focus on fierce movement.","Step:8 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/kKYTkjJ.gif','https://static.exercisedb.dev/media/kKYTkjJ.gif',NULL),
('kLiIFdB','band vertical pallof press - seated variation',NULL,'core','abs','{"obliques","glutes"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and wrap the band around a sturdy object at chest height.","Step:2 Hold the band with both hands and step away from the anchor point, creating tension in the band.","Step:3 Position yourself perpendicular to the anchor point, with your side facing the band.","Step:4 Extend your arms straight out in front of you, keeping your hands at chest height.","Step:5 Engage your core and press the band away from your chest, fully extending your arms.","Step:6 Hold the position for a few seconds, then slowly bring the band back towards your chest.","Step:7 Repeat for the desired number of repetitions, then switch sides. Perform with seated intensity."}','https://static.exercisedb.dev/media/kLiIFdB.gif','https://static.exercisedb.dev/media/kLiIFdB.gif',NULL),
('km0sQC0','band one arm standing low row',NULL,'back','upper back','{"biceps","shoulders"}','resistance band',NULL,'{"Step:1 Attach the band to a stable anchor point at waist height.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Step:4 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:5 Pull the band towards your waist, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/km0sQC0.gif','https://static.exercisedb.dev/media/km0sQC0.gif',NULL),
('km2Ljzj','wheel run',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Start in a plank position with your hands on the wheel and your body straight.","Step:2 Engage your core and start rolling the wheel forward by extending your arms.","Step:3 Continue rolling until your body is fully extended and your arms are overhead.","Step:4 Reverse the movement by pulling the wheel back towards your body, using your core and arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/km2Ljzj.gif','https://static.exercisedb.dev/media/km2Ljzj.gif',NULL),
('kmVVAfu','band concentration curl',NULL,'arms','biceps','{"forearms"}','resistance band',NULL,'{"Step:1 Sit on a bench or chair with your legs spread apart and your feet flat on the ground.","Step:2 Hold one end of the band in your hand and step on the other end with your foot on the same side.","Step:3 Lean forward slightly and rest your elbow on the inside of your thigh, just above the knee.","Step:4 With your palm facing up, slowly curl your hand towards your shoulder, keeping your upper arm stationary.","Step:5 Pause for a moment at the top, then slowly lower your hand back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/kmVVAfu.gif','https://static.exercisedb.dev/media/kmVVAfu.gif',NULL),
('kMzUs9Y','forward lunge (male)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet hip-width apart and hands on your hips.","Step:2 Take a big step forward with your right foot, lowering your body into a lunge position.","Step:3 Bend your right knee to about 90 degrees, keeping your knee aligned with your ankle.","Step:4 Push off with your right foot and return to the starting position.","Step:5 Repeat with your left leg, alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/kMzUs9Y.gif','https://static.exercisedb.dev/media/kMzUs9Y.gif',NULL),
('kont8Ut','dumbbell seated triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell with both hands and extend your arms straight up overhead.","Step:3 Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.","Step:4 Pause for a moment, then straighten your arms and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kont8Ut.gif','https://static.exercisedb.dev/media/kont8Ut.gif',NULL),
('KOpzGBL','dumbbell waiter biceps curl',NULL,'arms','biceps','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing forward.","Step:2 Keep your upper arms close to your body and your elbows tucked in.","Step:3 Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KOpzGBL.gif','https://static.exercisedb.dev/media/KOpzGBL.gif',NULL),
('Kpajagk','cable standing hip extension',NULL,'legs','glutes','{"hamstrings","quadriceps"}','cable',NULL,'{"Step:1 Attach a cable to a low pulley and stand facing away from the machine.","Step:2 Place the cable around your ankle and stand with your feet shoulder-width apart.","Step:3 Keep your core engaged and your back straight throughout the exercise.","Step:4 Slowly extend your leg straight back, squeezing your glutes at the top of the movement.","Step:5 Pause for a moment, then return to the starting position.","Step:6 Repeat for the desired number of repetitions.","Step:7 Switch sides and repeat with the other leg."}','https://static.exercisedb.dev/media/Kpajagk.gif','https://static.exercisedb.dev/media/Kpajagk.gif',NULL),
('kprile3','exercise ball dip',NULL,'arms','triceps','{"chest","shoulders"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Place your hands on the ball beside your hips, fingers pointing forward.","Step:3 Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.","Step:4 Lower your body back down by bending your elbows, keeping them close to your sides.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kprile3.gif','https://static.exercisedb.dev/media/kprile3.gif',NULL),
('KQfySvS','dumbbell reverse grip row (female) hold',NULL,'back','upper back','{"biceps","forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold a dumbbell in each hand with an overhand grip, palms facing your body. Perform with hold intensity.","Step:3 Bend forward at the waist, keeping your back straight and your core engaged.","Step:4 Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Step:5 Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KQfySvS.gif','https://static.exercisedb.dev/media/KQfySvS.gif',NULL),
('Krmb3cB','lever reverse hyperextension',NULL,'legs','glutes','{"hamstrings","lower back"}','machine',NULL,'{"Step:1 Adjust the leverage machine to fit your body and secure your feet in the foot pads.","Step:2 Lie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.","Step:3 Cross your arms over your chest or place them behind your head.","Step:4 Engage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.","Step:5 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Krmb3cB.gif','https://static.exercisedb.dev/media/Krmb3cB.gif',NULL),
('kTbSH9h','barbell seated overhead press',NULL,'shoulders','delts','{"triceps","upper back"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lift the barbell off the rack and bring it to shoulder level, with your elbows bent and palms facing forward.","Step:4 Press the barbell overhead by extending your arms fully.","Step:5 Pause for a moment at the top, then slowly lower the barbell back to shoulder level.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kTbSH9h.gif','https://static.exercisedb.dev/media/kTbSH9h.gif',NULL),
('ktf3nvW','kettlebell plyo push-up',NULL,'chest','pectorals','{"triceps","shoulders","core"}','kettlebell',NULL,'{"Step:1 Start in a high plank position with your hands on the kettlebells, shoulder-width apart.","Step:2 Lower your chest towards the ground, keeping your elbows close to your body.","Step:3 Push through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.","Step:4 Land softly back on the kettlebells and immediately lower your chest back down for the next repetition.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ktf3nvW.gif','https://static.exercisedb.dev/media/ktf3nvW.gif',NULL),
('KtRomty','standing wheel rollerout',NULL,'core','abs','{"lower back","shoulders"}','wheel roller',NULL,'{"Step:1 Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.","Step:2 Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.","Step:3 Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.","Step:4 Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KtRomty.gif','https://static.exercisedb.dev/media/KtRomty.gif',NULL),
('ktsFQAZ','barbell seated calf raise',NULL,'legs','calves','{"hamstrings","quadriceps"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the floor and a barbell resting on your thighs.","Step:2 Place the balls of your feet on a raised platform, such as a block or step.","Step:3 Position the barbell across your thighs and hold it securely with your hands.","Step:4 Keeping your back straight and your core engaged, lift your heels off the ground by extending your ankles.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ktsFQAZ.gif','https://static.exercisedb.dev/media/ktsFQAZ.gif',NULL),
('KUaoUV8','band straight leg deadlift',NULL,'back','spine','{"hamstrings","glutes"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band around your feet.","Step:2 Hold the band with both hands, palms facing your body, and keep your arms straight.","Step:3 Engage your core and maintain a slight bend in your knees.","Step:4 Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Step:5 Lower the band towards the ground while keeping your legs straight.","Step:6 Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KUaoUV8.gif','https://static.exercisedb.dev/media/KUaoUV8.gif',NULL),
('KUaZst7','dumbbell lying supine curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KUaZst7.gif','https://static.exercisedb.dev/media/KUaZst7.gif',NULL),
('kuMiR2T','band stiff leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band around your ankles.","Step:2 Hold the band with both hands in front of your thighs, palms facing your body.","Step:3 Keeping your back straight and your core engaged, hinge at the hips and slowly lower your upper body towards the ground.","Step:4 As you lower, push your hips back and allow your knees to bend slightly.","Step:5 Lower the band towards the ground, feeling a stretch in your hamstrings.","Step:6 Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your upper body back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kuMiR2T.gif','https://static.exercisedb.dev/media/kuMiR2T.gif',NULL),
('kuXhl0o','kettlebell pirate supper legs',NULL,'shoulders','delts','{"triceps","forearms"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Raise the kettlebell up to shoulder height, keeping your elbow close to your body.","Step:4 Extend your arm fully overhead, straightening your elbow.","Step:5 Lower the kettlebell back down to shoulder height, then return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/kuXhl0o.gif','https://static.exercisedb.dev/media/kuXhl0o.gif',NULL),
('KWdF2JI','cable kneeling triceps extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope handle to a high pulley and kneel down facing the cable machine.","Step:2 Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.","Step:3 Keep your elbows close to your head and your upper arms stationary throughout the exercise.","Step:4 Extend your forearms by contracting your triceps until your arms are fully extended.","Step:5 Pause for a moment, then slowly return to the starting position by bending your elbows.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KWdF2JI.gif','https://static.exercisedb.dev/media/KWdF2JI.gif',NULL),
('KwFGiEP','dumbbell lying one arm rear lateral raise',NULL,'shoulders','delts','{"traps","rhomboids"}','dumbbell',NULL,'{"Step:1 Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.","Step:2 Keep your arm straight and lift the dumbbell out to the side, away from your body.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/KwFGiEP.gif','https://static.exercisedb.dev/media/KwFGiEP.gif',NULL),
('KWyEjtI','precision style lever bent-over row with v-bar',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself facing the machine.","Step:2 Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Step:3 Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top of the movement, then slowly release the weight back to the starting position. Emphasize precision control.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KWyEjtI.gif','https://static.exercisedb.dev/media/KWyEjtI.gif',NULL),
('kXaIn5A','dumbbell zottman curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your body.","Step:2 Keep your elbows close to your torso and rotate your palms to face forward.","Step:3 Curl the dumbbells up to your shoulders while keeping your upper arms stationary.","Step:4 At the top of the movement, rotate your wrists so that your palms are facing away from your body.","Step:5 Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/kXaIn5A.gif','https://static.exercisedb.dev/media/kXaIn5A.gif',NULL),
('Kxquu2E','barbell step-up',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand in front of a bench or step with a barbell resting on your upper back.","Step:2 Place one foot on the bench or step, ensuring your entire foot is in contact with the surface.","Step:3 Push through your heel and step up onto the bench or step, fully extending your hip and knee.","Step:4 Pause briefly at the top, then lower yourself back down to the starting position.","Step:5 Repeat with the opposite leg.","Step:6 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/Kxquu2E.gif','https://static.exercisedb.dev/media/Kxquu2E.gif',NULL),
('KXyoEtA','dumbbell seated inner biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Step:2 Rest your upper arms on your thighs, allowing the dumbbells to hang down.","Step:3 Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KXyoEtA.gif','https://static.exercisedb.dev/media/KXyoEtA.gif',NULL),
('ky8FLU8','lever reverse grip lateral pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground.","Step:2 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back.","Step:4 Pull the handles down towards your chest, leading with your elbows and squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ky8FLU8.gif','https://static.exercisedb.dev/media/ky8FLU8.gif',NULL),
('Kyd9Rz5','barbell standing wide military press',NULL,'shoulders','delts','{"triceps","upper back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the barbell with an overhand grip, slightly wider than shoulder-width.","Step:2 Lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.","Step:3 Press the barbell overhead, extending your arms fully.","Step:4 Lower the barbell back to shoulder height and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Kyd9Rz5.gif','https://static.exercisedb.dev/media/Kyd9Rz5.gif',NULL),
('KyLtiLT','ez barbell incline triceps extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with your back against the pad and hold the ez barbell with an overhand grip.","Step:3 Extend your arms fully overhead, keeping your elbows close to your head.","Step:4 Lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.","Step:5 Pause for a moment, then extend your arms back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KyLtiLT.gif','https://static.exercisedb.dev/media/KyLtiLT.gif',NULL),
('Kzg30R7','band standing crunch',NULL,'core','abs','{"obliques"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point at waist height.","Step:2 Stand facing away from the anchor point with your feet shoulder-width apart.","Step:3 Hold the band with both hands and bring it up to your chest, keeping your elbows bent and close to your body.","Step:4 Engage your abs and slowly crunch forward, bringing your chest towards your knees.","Step:5 Pause for a moment at the top of the crunch, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Kzg30R7.gif','https://static.exercisedb.dev/media/Kzg30R7.gif',NULL),
('KZn52RC','flexion leg sit up (straight arm)',NULL,'core','abs','{"hip flexors","quadriceps"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and arms straight above your head.","Step:2 Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs towards your chest.","Step:3 Reach your hands towards your toes as you lift your upper body and legs.","Step:4 Pause for a moment at the top, then slowly lower your upper body and legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KZn52RC.gif','https://static.exercisedb.dev/media/KZn52RC.gif',NULL),
('KZXAtKQ','push-up close-grip off dumbbell',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Start in a push-up position with your hands placed close together, directly under your shoulders.","Step:2 Hold a dumbbell in each hand, resting them on the ground.","Step:3 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:4 Push through your palms to extend your arms and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/KZXAtKQ.gif','https://static.exercisedb.dev/media/KZXAtKQ.gif',NULL),
('L2V5Nan','dumbbell lying extension (across face)',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Step:3 Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Step:4 Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/L2V5Nan.gif','https://static.exercisedb.dev/media/L2V5Nan.gif',NULL),
('L4ay0PW','kettlebell figure 8',NULL,'core','abs','{"shoulders","forearms"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Pass the kettlebell between your legs, switching hands as it reaches the back of your legs.","Step:4 As the kettlebell comes forward, pass it to the other hand between your legs.","Step:5 Continue passing the kettlebell between your legs in a figure 8 motion.","Step:6 Maintain a steady pace and engage your core throughout the exercise.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/L4ay0PW.gif','https://static.exercisedb.dev/media/L4ay0PW.gif',NULL),
('L68dTQj','band seated twist pure',NULL,'core','abs','{"obliques"}','resistance band',NULL,'{"Step:1 Sit on the ground with your legs extended in front of you and your back straight.","Step:2 Wrap the band around your waist and hold the ends with both hands.","Step:3 Engage your abs and slowly twist your torso to one side, keeping your back straight and your feet on the ground.","Step:4 Pause for a moment at the end of the twist, then slowly return to the starting position.","Step:5 (pure variation) Repeat the twist to the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/L68dTQj.gif','https://static.exercisedb.dev/media/L68dTQj.gif',NULL),
('laVRfDf','dumbbell standing front raise above head',NULL,'shoulders','delts','{"trapezius","biceps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Keep your arms straight and lift the dumbbells in front of you, raising them above your head.","Step:3 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/laVRfDf.gif','https://static.exercisedb.dev/media/laVRfDf.gif',NULL),
('lBDjFxJ','pull-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your palms facing away from you and your arms fully extended.","Step:2 Engage your core and squeeze your shoulder blades together.","Step:3 Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar.","Step:4 Pause at the top of the movement, then slowly lower your body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/lBDjFxJ.gif','https://static.exercisedb.dev/media/lBDjFxJ.gif',NULL),
('lCKm4Rs','exercise ball prone leg raise',NULL,'back','spine','{"abdominals","glutes"}','other',NULL,'{"Step:1 Lie face down on a mat with your legs extended and your toes resting on top of the stability ball.","Step:2 Place your hands on the ground, shoulder-width apart, and engage your core muscles.","Step:3 Keeping your legs straight, slowly lift them off the ground, using your lower back and glutes to raise them as high as possible.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/lCKm4Rs.gif','https://static.exercisedb.dev/media/lCKm4Rs.gif',NULL),
('LCtQPn8','dumbbell incline inner biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, palms facing each other.","Step:2 Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LCtQPn8.gif','https://static.exercisedb.dev/media/LCtQPn8.gif',NULL),
('LeaZOIz','dumbbell standing alternate hammer curl and press',NULL,'arms','biceps','{"forearms","shoulders"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing your body.","Step:2 Keep your elbows close to your torso and your back straight.","Step:3 Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Step:4 Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Inhale and slowly lower the dumbbell back to the starting position.","Step:6 Repeat the curl with your left hand.","Step:7 After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.","Step:8 Extend your arm fully and hold for a moment at the top.","Step:9 Inhale and slowly lower the dumbbell back to the starting position.","Step:10 Repeat the press with your left hand.","Step:11 Continue alternating between curls and presses for the desired number of repetitions."}','https://static.exercisedb.dev/media/LeaZOIz.gif','https://static.exercisedb.dev/media/LeaZOIz.gif',NULL),
('LEH9jxP','push-up (wall)',NULL,'chest','pectorals','{"triceps","deltoids"}','body weight',NULL,'{"Step:1 Stand facing a wall, about arm's length away.","Step:2 Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step:3 Step back a few feet, keeping your body straight and your feet hip-width apart.","Step:4 Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Step:5 Push back up to the starting position, straightening your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LEH9jxP.gif','https://static.exercisedb.dev/media/LEH9jxP.gif',NULL),
('LEprlgG','cable lat pulldown full range of motion',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Sit on the lat pulldown machine with your knees positioned under the pads.","Step:2 Grasp the cable bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lean back slightly and keep your chest up, maintaining a slight arch in your lower back.","Step:4 Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the bar back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LEprlgG.gif','https://static.exercisedb.dev/media/LEprlgG.gif',NULL),
('lFBTISi','firm style hanging oblique knee raise',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your knees towards your chest, twisting your torso to the side as you do so.","Step:3 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:4 Repeat on the other side, twisting your torso in the opposite direction.","Step:5 Continue alternating sides for the desired number of repetitions. Emphasize firm control."}','https://static.exercisedb.dev/media/lFBTISi.gif','https://static.exercisedb.dev/media/lFBTISi.gif',NULL),
('lFhb2Rw','smith front squat (clean grip)',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','machine',NULL,'{"Step:1 Set up the smith machine with the barbell at shoulder height.","Step:2 Stand facing the barbell with your feet shoulder-width apart.","Step:3 Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.","Step:5 Keep your chest up, back straight, and core engaged.","Step:6 Lower your body by bending at the knees and hips, as if sitting back into a chair.","Step:7 Continue lowering until your thighs are parallel to the ground or slightly below.","Step:8 Pause for a moment, then push through your heels to return to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/lFhb2Rw.gif','https://static.exercisedb.dev/media/lFhb2Rw.gif',NULL),
('LFIOery','sharp style dumbbell sumo pull through',NULL,'legs','glutes','{"hamstrings","quadriceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet wider than shoulder-width apart, toes pointed outwards.","Step:2 Hold a dumbbell with both hands in front of your body, arms extended.","Step:3 Bend your knees and lower your hips down into a squat position, keeping your back straight. Focus on sharp movement.","Step:4 Lower the dumbbell down between your legs, keeping your arms straight.","Step:5 Drive through your heels and extend your hips forward, pulling the dumbbell up and in front of your body.","Step:6 Squeeze your glutes at the top of the movement, then lower the dumbbell back down between your legs.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LFIOery.gif','https://static.exercisedb.dev/media/LFIOery.gif',NULL),
('lHeUULr','band straight back stiff leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band around your upper legs.","Step:2 Hold the band with both hands in front of your thighs, palms facing your body.","Step:3 Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground.","Step:4 Feel the stretch in your hamstrings as you lower the band.","Step:5 Engage your glutes and hamstrings to lift your body back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/lHeUULr.gif','https://static.exercisedb.dev/media/lHeUULr.gif',NULL),
('LHWF7us','kettlebell hang clean',NULL,'legs','hamstrings','{"glutes","quadriceps","calves"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Lower the kettlebell towards the ground, allowing it to swing between your legs.","Step:4 Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.","Step:5 As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.","Step:6 Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LHWF7us.gif','https://static.exercisedb.dev/media/LHWF7us.gif',NULL),
('lI7easp','dumbbell pullover hip extension on exercise ball',NULL,'chest','pectorals','{"triceps","shoulders","core"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Step:2 Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Step:4 Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Step:5 Pause for a moment, then raise the dumbbell back to the starting position.","Step:6 While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Step:7 Lower your hips back down to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/lI7easp.gif','https://static.exercisedb.dev/media/lI7easp.gif',NULL),
('LIGZSTA','dumbbell one arm prone hammer curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Step:2 Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Step:3 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:4 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/LIGZSTA.gif','https://static.exercisedb.dev/media/LIGZSTA.gif',NULL),
('LIlE5Tn','jump squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Lower your body into a squat position by bending your knees and pushing your hips back.","Step:3 Jump explosively off the ground, extending your hips, knees, and ankles.","Step:4 While in mid-air, quickly bring your arms forward for balance.","Step:5 Land softly on the balls of your feet and immediately go into the next repetition.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LIlE5Tn.gif','https://static.exercisedb.dev/media/LIlE5Tn.gif',NULL),
('lJJ7Yq8','cable lying fly',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Attach the handles to the cables and lie flat on a bench with your feet flat on the ground.","Step:2 Hold the handles with your palms facing each other and your arms extended straight above your chest.","Step:3 Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Step:4 Pause for a moment, then squeeze your chest muscles to bring your arms back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/lJJ7Yq8.gif','https://static.exercisedb.dev/media/lJJ7Yq8.gif',NULL),
('LkoAWAE','elbow dips',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.","Step:2 Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.","Step:3 Bend your elbows and lower your body towards the ground, keeping your back close to the bench.","Step:4 Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LkoAWAE.gif','https://static.exercisedb.dev/media/LkoAWAE.gif',NULL),
('LL1UiTX','dumbbell incline one arm hammer press',NULL,'arms','triceps','{"shoulders","chest"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Step:2 Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.","Step:3 Rotate your wrist so that your palm is facing inward, towards your body.","Step:4 Press the dumbbell up and away from your body, extending your arm fully.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/LL1UiTX.gif','https://static.exercisedb.dev/media/LL1UiTX.gif',NULL),
('LLNh6q5','dumbbell incline one arm fly on exercise ball',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in one hand.","Step:2 Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Step:4 Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Step:5 Pause for a moment when your arm is parallel to the ground.","Step:6 Engage your chest muscles to bring the dumbbell back up to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/LLNh6q5.gif','https://static.exercisedb.dev/media/LLNh6q5.gif',NULL),
('LlSe9IK','assisted standing chin-up with focused',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the machine to your desired assistance level.","Step:2 (focused variation) Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Keep your chest up and shoulders back, engage your core, and slightly bend your knees.","Step:4 Pull your body up by flexing your elbows and driving your elbows down towards your sides.","Step:5 Continue pulling until your chin is above the bar.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LlSe9IK.gif','https://static.exercisedb.dev/media/LlSe9IK.gif',NULL),
('LmaFNZS','weighted donkey calf raise',NULL,'legs','calves','{"hamstrings","glutes"}','other',NULL,'{"Step:1 Stand on a raised platform with your toes on the edge and your heels hanging off.","Step:2 Hold onto a stable object for support.","Step:3 Raise your heels as high as possible by extending your ankles.","Step:4 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LmaFNZS.gif','https://static.exercisedb.dev/media/LmaFNZS.gif',NULL),
('LMGXZn8','barbell decline close grip to skull press',NULL,'arms','triceps','{"chest","shoulders"}','barbell',NULL,'{"Step:1 Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.","Step:2 Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.","Step:3 Pause for a moment, then extend your arms to press the barbell back up to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LMGXZn8.gif','https://static.exercisedb.dev/media/LMGXZn8.gif',NULL),
('Ln9iTbU','barbell rear delt raise',NULL,'shoulders','delts','{"traps","rhomboids"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a barbell with an overhand grip, palms facing down.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Raise the barbell out to the sides, keeping your arms straight, until they are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Ln9iTbU.gif','https://static.exercisedb.dev/media/Ln9iTbU.gif',NULL),
('LNE3wfo','single leg platform slide',NULL,'legs','hamstrings','{"glutes","quadriceps"}','body weight',NULL,'{"Step:1 Start by standing with one foot on a platform or slide board.","Step:2 Bend your knee slightly and slide the foot on the platform backward, extending your leg.","Step:3 Keep your core engaged and maintain a straight posture throughout the movement.","Step:4 Slowly return to the starting position by sliding your foot back to the initial position.","Step:5 Repeat the movement for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/LNE3wfo.gif','https://static.exercisedb.dev/media/LNE3wfo.gif',NULL),
('LQFOrMn','chest dip on straight bar',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Grab the parallel bars with your palms facing down and your arms fully extended.","Step:2 Bend your knees and cross your ankles.","Step:3 Lower your body by bending your arms until your shoulders are below your elbows.","Step:4 Push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LQFOrMn.gif','https://static.exercisedb.dev/media/LQFOrMn.gif',NULL),
('lRcrlH8','fast band straight leg deadlift',NULL,'back','spine','{"hamstrings","glutes"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band around your feet.","Step:2 Hold the band with both hands, palms facing your body, and keep your arms straight.","Step:3 Engage your core and maintain a slight bend in your knees.","Step:4 Slowly hinge forward at your hips, keeping your back straight and chest lifted.","Step:5 Lower the band towards the ground while keeping your legs straight.","Step:6 Pause for a moment at the bottom, then squeeze your glutes and hamstrings to return to the starting position.","Step:7 Repeat for the desired number of repetitions. Perform with fast intensity."}','https://static.exercisedb.dev/media/lRcrlH8.gif','https://static.exercisedb.dev/media/lRcrlH8.gif',NULL),
('LrV4s90','cable wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','cable',NULL,'{"Step:1 Attach a straight bar to a low pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Step:4 Rest your forearms on a bench or pad, with your wrists hanging off the edge.","Step:5 Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Step:6 Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LrV4s90.gif','https://static.exercisedb.dev/media/LrV4s90.gif',NULL),
('Lsqrgh4','smith reverse calf raises',NULL,'legs','calves','{"hamstrings"}','machine',NULL,'{"Step:1 Adjust the smith machine bar to a height just below your shoulders.","Step:2 Stand facing the bar with your feet hip-width apart and toes pointing forward.","Step:3 Place the balls of your feet on the edge of a step or platform, with your heels hanging off.","Step:4 Hold onto the bar for support.","Step:5 Raise your heels as high as possible, lifting your body up onto your toes.","Step:6 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Lsqrgh4.gif','https://static.exercisedb.dev/media/Lsqrgh4.gif',NULL),
('LSTChY9','barbell zercher squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and toes slightly turned out.","Step:2 Hold the barbell in the crooks of your elbows, with your hands gripping the bar for stability.","Step:3 Engage your core and keep your chest lifted as you lower your hips back and down into a squat position.","Step:4 Keep your knees in line with your toes and your weight in your heels.","Step:5 Pause for a moment at the bottom of the squat, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LSTChY9.gif','https://static.exercisedb.dev/media/LSTChY9.gif',NULL),
('LsZkfU6','barbell reverse wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a barbell with an overhand grip, palms facing down.","Step:2 Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Step:3 Slowly curl your wrists upward, bringing the barbell towards your body.","Step:4 Pause for a moment at the top, then slowly lower the barbell back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LsZkfU6.gif','https://static.exercisedb.dev/media/LsZkfU6.gif',NULL),
('Lt3iWnf','dumbbell fly on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball and hold a dumbbell in each hand.","Step:2 Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Step:3 Extend your arms straight up above your chest, palms facing each other.","Step:4 Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Step:5 Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Lt3iWnf.gif','https://static.exercisedb.dev/media/Lt3iWnf.gif',NULL),
('LuBEORI','lever bent-over row with v-bar',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself facing the machine.","Step:2 Grasp the v-bar with an overhand grip, keeping your back straight and your knees slightly bent.","Step:3 Pull the v-bar towards your abdomen, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top of the movement, then slowly release the weight back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LuBEORI.gif','https://static.exercisedb.dev/media/LuBEORI.gif',NULL),
('LWuA3aZ','barbell standing reverse grip curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.","Step:2 Keep your elbows close to your torso and your upper arms stationary.","Step:3 Exhale and curl the weights while contracting your biceps, bringing the barbell as close to your shoulders as possible.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LWuA3aZ.gif','https://static.exercisedb.dev/media/LWuA3aZ.gif',NULL),
('LYJodFS','lean planche',NULL,'core','abs','{"shoulders","chest","triceps"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and your body straight.","Step:2 Engage your core and slowly shift your weight forward, bringing your shoulders past your hands.","Step:3 Keep your elbows slightly bent and your body straight as you lean forward.","Step:4 Hold this position for a few seconds, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/LYJodFS.gif','https://static.exercisedb.dev/media/LYJodFS.gif',NULL),
('lyKCLmK','dumbbell seated revers grip concentration curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Step:2 Rest your elbow on the inside of your thigh, just above the knee.","Step:3 Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Inhale and slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/lyKCLmK.gif','https://static.exercisedb.dev/media/lyKCLmK.gif',NULL),
('LzX8YEz','all fours squad stretch - elevated variation',NULL,'legs','quads','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Step:2 Extend one leg straight back, keeping your knee bent and your foot flexed. Maintain elevated form throughout.","Step:3 Slowly lower your hips towards the ground, feeling a stretch in your quads.","Step:4 Hold this position for 20-30 seconds.","Step:5 Switch legs and repeat the stretch on the other side."}','https://static.exercisedb.dev/media/LzX8YEz.gif','https://static.exercisedb.dev/media/LzX8YEz.gif',NULL),
('m0tCHqc','calf stretch with hands against wall',NULL,'legs','calves','{"hamstrings"}','body weight',NULL,'{"Step:1 Stand facing a wall with your feet hip-width apart.","Step:2 Place your hands against the wall at shoulder height.","Step:3 Step your right foot back, keeping your heel on the ground and your leg straight.","Step:4 Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Step:5 Hold the stretch for 20-30 seconds.","Step:6 Switch legs and repeat the stretch."}','https://static.exercisedb.dev/media/m0tCHqc.gif','https://static.exercisedb.dev/media/m0tCHqc.gif',NULL),
('M2Pm3zj','dumbbell lying supination',NULL,'arms','forearms','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground.","Step:2 Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Step:3 Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/M2Pm3zj.gif','https://static.exercisedb.dev/media/M2Pm3zj.gif',NULL),
('M5Y7GPg','weighted standing curl',NULL,'arms','biceps','{"forearms"}','other',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Step:2 Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.","Step:3 Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/M5Y7GPg.gif','https://static.exercisedb.dev/media/M5Y7GPg.gif',NULL),
('M72BExt','exercise ball one leg prone lower body rotation',NULL,'legs','glutes','{"hamstrings","quadriceps","core"}','other',NULL,'{"Step:1 Lie face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.","Step:2 Place your hands on the ground in front of you for support.","Step:3 Engage your glutes and core muscles to stabilize your body.","Step:4 Slowly lift one leg off the ground, keeping it straight and parallel to the floor.","Step:5 Rotate your leg outward, away from your body, while keeping your hips and upper body stable.","Step:6 Pause for a moment at the end of the rotation, then slowly return your leg to the starting position.","Step:7 Repeat the rotation with the other leg.","Step:8 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/M72BExt.gif','https://static.exercisedb.dev/media/M72BExt.gif',NULL),
('M74kdvm','kettlebell double snatch',NULL,'shoulders','delts','{"trapezius","forearms","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm's length in front of your thighs.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.","Step:3 In one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.","Step:4 As the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.","Step:5 Lower the kettlebells back down to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/M74kdvm.gif','https://static.exercisedb.dev/media/M74kdvm.gif',NULL),
('M8IolhQ','ez barbell close grip preacher curl - precision variation',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.","Step:2 Rest your triceps on the pad and fully extend your arms, keeping your back straight.","Step:3 Slowly curl the barbell towards your shoulders, contracting your biceps.","Step:4 Pause for a moment at the top, squeezing your biceps.","Step:5 Lower the barbell back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions. Emphasize precision control."}','https://static.exercisedb.dev/media/M8IolhQ.gif','https://static.exercisedb.dev/media/M8IolhQ.gif',NULL),
('MaMuGH6','lever assisted chin-up',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the leverage machine to your desired resistance level.","Step:2 Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang with your arms fully extended, keeping your body straight.","Step:4 Engage your back muscles and pull your body up towards the handles, leading with your chest.","Step:5 Continue pulling until your chin is above the handles.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MaMuGH6.gif','https://static.exercisedb.dev/media/MaMuGH6.gif',NULL),
('mAYqY4M','stretched full planche push-up',NULL,'chest','pectorals','{"shoulders","triceps","core"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands placed slightly wider than shoulder-width apart.","Step:2 Engage your core and lower your body down towards the ground, keeping your elbows close to your sides.","Step:3 As you lower yourself, lean your body forward and lift your feet off the ground, balancing on your hands. Perform with stretched intensity.","Step:4 Continue to lower your body until your chest is just above the ground.","Step:5 Push through your hands and extend your arms to lift your body back up to the starting position.","Step:6 Maintain a straight line from your head to your heels throughout the movement.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mAYqY4M.gif','https://static.exercisedb.dev/media/mAYqY4M.gif',NULL),
('mbkgB44','jackknife sit-up',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms overhead.","Step:2 Engage your core and lift your legs and upper body simultaneously, reaching your hands towards your toes.","Step:3 Pause for a moment at the top, then slowly lower your legs and upper body back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mbkgB44.gif','https://static.exercisedb.dev/media/mbkgB44.gif',NULL),
('MCkqdKE','weighted muscle up (on bar)',NULL,'back','lats','{"biceps","triceps","shoulders","forearms"}','other',NULL,'{"Step:1 Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.","Step:2 Engage your core and pull your shoulder blades down and back.","Step:3 Bend your elbows and pull your chest towards the bar, keeping your body straight.","Step:4 Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.","Step:5 Pause at the top of the movement, then slowly lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MCkqdKE.gif','https://static.exercisedb.dev/media/MCkqdKE.gif',NULL),
('MCUhf1F','crunch (on stability ball)',NULL,'core','abs','{"hip flexors"}','other',NULL,'{"Step:1 Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Step:2 Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Step:3 Place your hands behind your head or across your chest.","Step:4 Engage your abs and lift your upper body towards your knees, curling your torso forward.","Step:5 Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MCUhf1F.gif','https://static.exercisedb.dev/media/MCUhf1F.gif',NULL),
('MDFxU4b','quads complex',NULL,'legs','quads','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart.","Step:2 Lower your body by bending your knees and pushing your hips back as if sitting on a chair.","Step:3 Keep your chest up and your back straight.","Step:4 Lower yourself until your thighs are parallel to the ground.","Step:5 Push through your heels to return to the starting position. Emphasize complex control.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MDFxU4b.gif','https://static.exercisedb.dev/media/MDFxU4b.gif',NULL),
('mExgrF9','bench pull-ups',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Position yourself under a bar or a sturdy horizontal surface that is at chest height.","Step:2 Grab the bar or surface with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang with your arms fully extended and your body straight.","Step:4 Pull your chest towards the bar or surface by squeezing your shoulder blades together and bending your elbows.","Step:5 Continue pulling until your chin is above the bar or surface.","Step:6 Lower yourself back down to the starting position with control.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mExgrF9.gif','https://static.exercisedb.dev/media/mExgrF9.gif',NULL),
('mgejmGP','prisoner half sit-up (male)',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mgejmGP.gif','https://static.exercisedb.dev/media/mgejmGP.gif',NULL),
('MgKwAAo','cable rope extension incline bench row',NULL,'back','upper back','{"biceps","shoulders"}','cable',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle and attach a cable machine to the low pulley.","Step:2 Attach a rope handle to the cable machine and sit on the incline bench facing the machine.","Step:3 Grab the rope handle with an overhand grip and lean forward, keeping your back straight.","Step:4 Extend your arms fully, pulling the rope towards your upper chest while keeping your elbows close to your body.","Step:5 Squeeze your shoulder blades together at the end of the movement.","Step:6 Slowly release the tension and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MgKwAAo.gif','https://static.exercisedb.dev/media/MgKwAAo.gif',NULL),
('MKIelrR','cable one arm press on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','cable',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back straight.","Step:2 Hold a cable handle in one hand and position your arm at chest height, elbow bent.","Step:3 Place your other hand on your hip for stability.","Step:4 Press the cable handle forward, extending your arm fully.","Step:5 Pause for a moment, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/MKIelrR.gif','https://static.exercisedb.dev/media/MKIelrR.gif',NULL),
('mKwcrHn','lever gripper hands',NULL,'arms','forearms','{"biceps","triceps"}','machine',NULL,'{"Step:1 Adjust the seat height and grip the handles of the leverage machine.","Step:2 Keep your back straight and your feet flat on the ground.","Step:3 Exhale and squeeze the handles, contracting your forearms.","Step:4 Hold the contraction for a second, then slowly release and return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mKwcrHn.gif','https://static.exercisedb.dev/media/mKwcrHn.gif',NULL),
('mnzcrIB','dumbbell bench squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','dumbbell',NULL,'{"Step:1 Place a dumbbell on the ground in front of a bench.","Step:2 Stand facing away from the bench with your feet shoulder-width apart.","Step:3 Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Step:4 Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mnzcrIB.gif','https://static.exercisedb.dev/media/mnzcrIB.gif',NULL),
('mpKZGWz','dumbbell lying triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms straight up over your chest, keeping your elbows close to your body.","Step:3 Lower the dumbbells down towards your forehead, bending your elbows.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mpKZGWz.gif','https://static.exercisedb.dev/media/mpKZGWz.gif',NULL),
('mpYUPkA','lying leg-hip raise - contracted variation',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your legs extended and your arms by your sides.","Step:2 Place your hands under your glutes for support.","Step:3 Engage your core and lift your legs off the ground, raising them towards the ceiling.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position. Emphasize contracted control.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mpYUPkA.gif','https://static.exercisedb.dev/media/mpYUPkA.gif',NULL),
('mQ1tBXn','straight leg outer hip abductor',NULL,'legs','abductors','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Lie on your side with your legs straight and stacked on top of each other.","Step:2 Place your bottom arm under your head for support.","Step:3 Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.","Step:4 Pause for a moment at the top, then slowly lower your leg back down to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/mQ1tBXn.gif','https://static.exercisedb.dev/media/mQ1tBXn.gif',NULL),
('MqNdIbe','controlled wrist rollerer',NULL,'arms','forearms','{"biceps","triceps"}','other',NULL,'{"Step:1 Attach a weight to one end of a rope or bar.","Step:2 Hold the other end of the rope or bar with both hands, palms facing down.","Step:3 Stand with your feet shoulder-width apart and your arms fully extended in front of you.","Step:4 Slowly roll the weight up towards your hands by flexing your wrists.","Step:5 Pause for a moment at the top, then slowly lower the weight back down to the starting position. Perform with controlled intensity.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MqNdIbe.gif','https://static.exercisedb.dev/media/MqNdIbe.gif',NULL),
('mr7pkqP','jack burpee',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves","shoulders","triceps","core"}','body weight',NULL,'{"Step:1 Start in a standing position with your feet shoulder-width apart.","Step:2 Lower your body into a squat position, placing your hands on the ground in front of you.","Step:3 Kick your feet back, landing in a push-up position.","Step:4 Perform a push-up, lowering your chest to the ground and then pushing back up.","Step:5 Jump your feet forward, landing in a squat position.","Step:6 Jump up explosively, reaching your arms overhead.","Step:7 Land softly and immediately lower back into the squat position to begin the next repetition."}','https://static.exercisedb.dev/media/mr7pkqP.gif','https://static.exercisedb.dev/media/mr7pkqP.gif',NULL),
('Mr8d4KA','kettlebell arnold press - beginner variation',NULL,'shoulders','delts','{"triceps","upper back"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.","Step:2 Engage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms. Emphasize beginner control.","Step:3 Pause at the top of the movement, then slowly lower the kettlebells back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Mr8d4KA.gif','https://static.exercisedb.dev/media/Mr8d4KA.gif',NULL),
('MRaFiZP','inverted style smith seated shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','machine',NULL,'{"Step:1 Adjust the seat height so that the handles are at shoulder level.","Step:2 Sit on the machine with your back against the pad and your feet flat on the floor.","Step:3 Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.","Step:4 Lower the handles down to shoulder level, keeping your elbows slightly bent.","Step:5 Press the handles up overhead until your arms are fully extended.","Step:6 Pause for a moment at the top, then slowly lower the handles back down to shoulder level. Maintain inverted form throughout.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MRaFiZP.gif','https://static.exercisedb.dev/media/MRaFiZP.gif',NULL),
('MrgP9L6','lever rotary calf',NULL,'legs','calves','{"soleus","ankle stabilizers"}','machine',NULL,'{"Step:1 Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.","Step:2 Place your toes on the footplate, with your heels hanging off the edge.","Step:3 Grasp the handles or the sides of the machine for stability.","Step:4 Push through the balls of your feet, raising your heels as high as possible.","Step:5 Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MrgP9L6.gif','https://static.exercisedb.dev/media/MrgP9L6.gif',NULL),
('ms7tjSG','inverse leg curl (bench support)',NULL,'legs','hamstrings','{"glutes","calves"}','body weight',NULL,'{"Step:1 Lie face down on a bench with your hips at the edge and your legs extended straight behind you.","Step:2 Hold onto the bench for support.","Step:3 Keeping your upper body still, bend your knees and curl your legs towards your glutes.","Step:4 Pause for a moment at the top, then slowly extend your legs back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ms7tjSG.gif','https://static.exercisedb.dev/media/ms7tjSG.gif',NULL),
('MSfvriJ','skin the cat',NULL,'back','upper back','{"shoulders","core"}','body weight',NULL,'{"Step:1 Start by hanging from a bar with your arms fully extended and your body relaxed.","Step:2 Engage your core and lift your legs up, bringing your knees towards your chest.","Step:3 Continue to lift your legs up and over your head, allowing your body to pass through the arms.","Step:4 Once your legs are fully extended over your head, begin to lower them back down towards the starting position.","Step:5 As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MSfvriJ.gif','https://static.exercisedb.dev/media/MSfvriJ.gif',NULL),
('mTT3KLn','cable front shoulder raise',NULL,'shoulders','delts','{"trapezius","biceps"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart and grasp the cable handle with an overhand grip.","Step:2 Keep your back straight and your core engaged.","Step:3 Raise the cable handle in front of you, keeping your arms straight and your palms facing down.","Step:4 Continue lifting until your arms are parallel to the floor.","Step:5 Pause for a moment at the top, then slowly lower the cable handle back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mTT3KLn.gif','https://static.exercisedb.dev/media/mTT3KLn.gif',NULL),
('mtXengz','dumbbell finger curls',NULL,'arms','forearms','{"wrist flexors","wrist extensors"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Step:3 Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Step:4 Repeat for the desired number of repetitions, then switch to the other hand."}','https://static.exercisedb.dev/media/mtXengz.gif','https://static.exercisedb.dev/media/mtXengz.gif',NULL),
('mu5Guxt','dumbbell rear delt raise',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:3 Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mu5Guxt.gif','https://static.exercisedb.dev/media/mu5Guxt.gif',NULL),
('MU9HnE7','weighted bench dip',NULL,'arms','triceps','{"chest","shoulders"}','other',NULL,'{"Step:1 Sit on a bench with your hands gripping the edge, fingers pointing forward.","Step:2 Slide your butt off the bench, supporting your weight with your hands.","Step:3 Lower your body by bending your elbows until your upper arms are parallel to the floor.","Step:4 Push yourself back up to the starting position by straightening your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MU9HnE7.gif','https://static.exercisedb.dev/media/MU9HnE7.gif',NULL),
('MUic5zN','single arm push-up',NULL,'chest','pectorals','{"triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.","Step:2 Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.","Step:3 As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.","Step:4 Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.","Step:5 Repeat the movement, alternating the arm you extend with each repetition."}','https://static.exercisedb.dev/media/MUic5zN.gif','https://static.exercisedb.dev/media/MUic5zN.gif',NULL),
('MvQPqVW','cable judo flip',NULL,'core','abs','{"obliques","shoulders"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Hold the cable handle with both hands at chest level, palms facing down.","Step:3 Engage your core and rotate your torso to the right, pulling the cable across your body.","Step:4 As you rotate, pivot your back foot and allow your hips to rotate naturally.","Step:5 Extend your arms fully and finish the movement by flipping the cable handle over your shoulder.","Step:6 Return to the starting position by reversing the movement, rotating your torso back to the center.","Step:7 Repeat the movement on the opposite side.","Step:8 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/MvQPqVW.gif','https://static.exercisedb.dev/media/MvQPqVW.gif',NULL),
('mWBtgmb','dumbbell single arm overhead carry',NULL,'shoulders','delts','{"traps","core"}','dumbbell',NULL,'{"Step:1 Stand tall with your feet shoulder-width apart, holding a dumbbell in one hand.","Step:2 Raise the dumbbell overhead, fully extending your arm.","Step:3 Engage your core and keep your back straight as you walk forward, maintaining the dumbbell overhead.","Step:4 Continue walking for the desired distance or time.","Step:5 Switch hands and repeat the exercise."}','https://static.exercisedb.dev/media/mWBtgmb.gif','https://static.exercisedb.dev/media/mWBtgmb.gif',NULL),
('mweqJin','quick feet v. 2',NULL,'legs','quads','{"calves","hamstrings"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms by your sides.","Step:2 Begin by rapidly moving your feet up and down, as if you were running in place.","Step:3 Keep your movements quick and light, focusing on staying on the balls of your feet.","Step:4 Continue for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/mweqJin.gif','https://static.exercisedb.dev/media/mweqJin.gif',NULL),
('mWppALS','groin crunch',NULL,'core','abs','{"hip flexors","inner thighs"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands behind your head with your elbows pointing outwards.","Step:3 Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mWppALS.gif','https://static.exercisedb.dev/media/mWppALS.gif',NULL),
('mwpPcr1','dumbbell prone incline curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Adjust the bench to a 45-degree incline.","Step:2 Lie face down on the bench with your chest and stomach resting against it.","Step:3 Hold a dumbbell in each hand with your palms facing down and your arms fully extended.","Step:4 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:5 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mwpPcr1.gif','https://static.exercisedb.dev/media/mwpPcr1.gif',NULL),
('Mxa7Cr8','inverted row on bench',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Set up a bench at a height that allows your body to hang freely underneath it.","Step:2 Lie face up on the ground with your head towards the bench.","Step:3 Reach up and grab the bench with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Position your body so that your heels are on the ground and your arms are fully extended.","Step:5 Engage your core and squeeze your shoulder blades together as you pull your chest up towards the bench.","Step:6 Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Mxa7Cr8.gif','https://static.exercisedb.dev/media/Mxa7Cr8.gif',NULL),
('my33uHU','lever leg extension',NULL,'legs','quads','{"hamstrings"}','machine',NULL,'{"Step:1 Adjust the seat height and backrest of the machine to fit your body.","Step:2 Sit on the machine with your back against the backrest and your feet on the footpad.","Step:3 Grasp the handles or sidebars for stability.","Step:4 Extend your legs forward by straightening your knees, lifting the weight.","Step:5 Pause for a moment at the top, then slowly lower the weight back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/my33uHU.gif','https://static.exercisedb.dev/media/my33uHU.gif',NULL),
('MY9P1WA','smith decline reverse-grip press',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the smith machine to a decline position.","Step:2 Lie down on the bench with your feet secured under the foot pads.","Step:3 Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.","Step:4 Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.","Step:5 Pause for a moment at the bottom, then push the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MY9P1WA.gif','https://static.exercisedb.dev/media/MY9P1WA.gif',NULL),
('myfUsKf','lever seated reverse fly',NULL,'shoulders','delts','{"trapezius","rhomboids"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor.","Step:2 Grasp the handles with an overhand grip and keep your arms slightly bent.","Step:3 Exhale and squeeze your shoulder blades together as you pull the handles back and outward, away from your body.","Step:4 Pause for a moment at the peak contraction, then inhale and slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/myfUsKf.gif','https://static.exercisedb.dev/media/myfUsKf.gif',NULL),
('myJeTAe','tough cable one arm lateral raise',NULL,'shoulders','delts','{"traps","triceps"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the cable machine.","Step:2 Hold the cable handle with one hand, palm facing down, and stand far enough away from the machine so that there is tension on the cable.","Step:3 Keep your arm straight and slowly raise it out to the side until it is parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower your arm back down to the starting position. Focus on tough movement.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/myJeTAe.gif','https://static.exercisedb.dev/media/myJeTAe.gif',NULL),
('mym4hJo','dumbbell lying pronation',NULL,'arms','forearms','{"biceps","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Step:2 Rotate your palms so they are facing up.","Step:3 Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.","Step:4 Inhale and slowly lower the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/mym4hJo.gif','https://static.exercisedb.dev/media/mym4hJo.gif',NULL),
('Mz6lLcW','dumbbell lunge with bicep curl',NULL,'arms','biceps','{"quadriceps","hamstrings"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","Step:3 As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Step:4 Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Step:5 Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/Mz6lLcW.gif','https://static.exercisedb.dev/media/Mz6lLcW.gif',NULL),
('MzNnwx9','smith back shrug',NULL,'back','traps','{"shoulders"}','machine',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Keep your arms straight and allow the barbell to hang in front of your thighs.","Step:4 Lift your shoulders straight up towards your ears, squeezing your traps at the top.","Step:5 Hold for a moment, then lower your shoulders back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/MzNnwx9.gif','https://static.exercisedb.dev/media/MzNnwx9.gif',NULL),
('N3EirIW','lever assisted chin-up with twisted',NULL,'back','lats','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the leverage machine to your desired resistance level.","Step:2 Stand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Hang with your arms fully extended, keeping your body straight.","Step:4 (twisted variation) Engage your back muscles and pull your body up towards the handles, leading with your chest.","Step:5 Continue pulling until your chin is above the handles.","Step:6 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/N3EirIW.gif','https://static.exercisedb.dev/media/N3EirIW.gif',NULL),
('n5cWCsI','dumbbell one arm lateral raise',NULL,'shoulders','delts','{"trapezius","triceps"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Step:2 Keep your back straight and your core engaged throughout the exercise.","Step:3 Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Step:4 Continue lifting until your arm is parallel to the ground.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/n5cWCsI.gif','https://static.exercisedb.dev/media/n5cWCsI.gif',NULL),
('N6dZN2I','side cable high row (kneeling)',NULL,'back','upper back','{"biceps","shoulders"}','cable',NULL,'{"Step:1 Attach a straight bar to a cable machine at chest height.","Step:2 Kneel down in front of the cable machine and grab the bar with an overhand grip, hands shoulder-width apart.","Step:3 Sit back on your heels, keeping your back straight and your core engaged.","Step:4 Pull the bar towards your upper abdomen, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top of the movement, then slowly release the bar back to the starting position.","Step:6 Repeat for the desired number of repetitions. Maintain side form throughout."}','https://static.exercisedb.dev/media/N6dZN2I.gif','https://static.exercisedb.dev/media/N6dZN2I.gif',NULL),
('NAgVB3t','wheel rollerout',NULL,'core','abs','{"lower back"}','wheel roller',NULL,'{"Step:1 Kneel on the floor and place the wheel roller in front of you.","Step:2 Place your hands on the handles of the wheel roller and extend your arms straight out in front of you.","Step:3 Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight.","Step:4 Continue rolling forward until your body is fully extended and your arms are overhead.","Step:5 Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NAgVB3t.gif','https://static.exercisedb.dev/media/NAgVB3t.gif',NULL),
('NAkmgdx','arms overhead full sit-up (male)',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Extend your arms overhead, keeping them straight.","Step:3 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is upright.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NAkmgdx.gif','https://static.exercisedb.dev/media/NAkmgdx.gif',NULL),
('nAuHPcD','dumbbell one arm triceps extension (on bench)',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell in one hand and place your other hand on the bench for support.","Step:3 Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Step:4 Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Step:5 Extend your arm back up to the starting position, fully straightening your elbow.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/nAuHPcD.gif','https://static.exercisedb.dev/media/nAuHPcD.gif',NULL),
('NbVPDMW','dumbbell biceps curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NbVPDMW.gif','https://static.exercisedb.dev/media/NbVPDMW.gif',NULL),
('NCmbLCw','push-up (wall) v. 2',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Stand facing a wall, about arm's length away.","Step:2 Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step:3 Step back with your feet, keeping them hip-width apart.","Step:4 Engage your core and keep your body in a straight line from head to heels.","Step:5 Bend your elbows and lower your chest towards the wall, keeping your body straight.","Step:6 Pause for a moment, then push yourself back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NCmbLCw.gif','https://static.exercisedb.dev/media/NCmbLCw.gif',NULL),
('nCU1Ekp','reverse crunch',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Lie flat on your back with your arms extended along your sides.","Step:2 Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor.","Step:3 Contract your abs and curl your hips off the floor, bringing your knees towards your chest.","Step:4 Pause for a moment at the top, then slowly lower your hips back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nCU1Ekp.gif','https://static.exercisedb.dev/media/nCU1Ekp.gif',NULL),
('NdIb5Z1','barbell standing wide-grip curl',NULL,'arms','biceps','{"forearms","shoulders"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold a barbell with an overhand grip, hands wider than shoulder-width apart.","Step:2 Let the barbell hang at arm's length in front of your thighs, with your palms facing away from your body.","Step:3 Keeping your upper arms stationary, exhale and curl the barbell upward by contracting your biceps.","Step:4 Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the barbell back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NdIb5Z1.gif','https://static.exercisedb.dev/media/NdIb5Z1.gif',NULL),
('nDK1HJ0','ez bar lying bent arms pullover',NULL,'back','lats','{"triceps","chest"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your head at one end and your feet on the floor.","Step:2 Hold the EZ barbell with a pronated grip (palms facing away from you) and your hands shoulder-width apart.","Step:3 Extend your arms straight above your chest, keeping a slight bend in your elbows.","Step:4 Lower the barbell in an arc motion behind your head, maintaining the slight bend in your elbows.","Step:5 Pause for a moment, then return the barbell to the starting position by reversing the arc motion.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nDK1HJ0.gif','https://static.exercisedb.dev/media/nDK1HJ0.gif',NULL),
('neonEDL','floor fly (with barbell)',NULL,'chest','pectorals','{"deltoids","triceps"}','barbell',NULL,'{"Step:1 Lie flat on your back on the floor with your knees bent and feet flat on the ground.","Step:2 Hold a barbell with an overhand grip, arms extended straight up over your chest.","Step:3 Slowly lower the barbell out to the sides, keeping a slight bend in your elbows.","Step:4 Lower the barbell until your arms are parallel to the floor, feeling a stretch in your chest.","Step:5 Pause for a moment, then squeeze your chest muscles to bring the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/neonEDL.gif','https://static.exercisedb.dev/media/neonEDL.gif',NULL),
('nFc4FyV','dumbbell biceps curl reverse',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Step:2 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:3 Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:4 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:5 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nFc4FyV.gif','https://static.exercisedb.dev/media/nFc4FyV.gif',NULL),
('nFHk9fU','cable lateral pulldown (with rope attachment) core',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Attach a rope attachment to the cable machine at a high position.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the rope with an overhand grip, palms facing each other.","Step:4 Keep your back straight and lean slightly back.","Step:5 Pull the rope down towards your sides, squeezing your shoulder blades together. Emphasize core control.","Step:6 Pause for a moment at the bottom of the movement.","Step:7 Slowly release the tension and allow the rope to return to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nFHk9fU.gif','https://static.exercisedb.dev/media/nFHk9fU.gif',NULL),
('NfP83rA','dumbbell lying alternate extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Step:3 Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Step:4 Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Step:5 Repeat with the other arm, alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/NfP83rA.gif','https://static.exercisedb.dev/media/NfP83rA.gif',NULL),
('nFUwqG6','smith rear delt row',NULL,'shoulders','delts','{"trapezius","rhomboids","biceps"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.","Step:2 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nFUwqG6.gif','https://static.exercisedb.dev/media/nFUwqG6.gif',NULL),
('ngPpyRS','barbell seated behind head military press',NULL,'shoulders','delts','{"triceps","upper back"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold the barbell with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Lift the barbell off the rack and bring it down to shoulder level, behind your head.","Step:4 Press the barbell upward until your arms are fully extended.","Step:5 Lower the barbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ngPpyRS.gif','https://static.exercisedb.dev/media/ngPpyRS.gif',NULL),
('Nh3mvOO','dumbbell reverse grip row (female)',NULL,'back','upper back','{"biceps","forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and knees slightly bent.","Step:2 Hold a dumbbell in each hand with an overhand grip, palms facing your body.","Step:3 Bend forward at the waist, keeping your back straight and your core engaged.","Step:4 Let your arms hang straight down, fully extended, with a slight bend in your elbows.","Step:5 Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Nh3mvOO.gif','https://static.exercisedb.dev/media/Nh3mvOO.gif',NULL),
('ninBEOY','twisted side-to-side chin',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Hang from the bar with your arms fully extended and your body relaxed.","Step:4 Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.","Step:5 Once your chin is above the bar, lower yourself back down to the starting position.","Step:6 Repeat for the desired number of repetitions. Perform with twisted intensity."}','https://static.exercisedb.dev/media/ninBEOY.gif','https://static.exercisedb.dev/media/ninBEOY.gif',NULL),
('nIR4Rwl','cable seated chest press',NULL,'chest','pectorals','{"shoulders","triceps"}','cable',NULL,'{"Step:1 Adjust the seat height and cable handles to a comfortable position.","Step:2 Sit on the bench with your back straight and feet flat on the floor.","Step:3 Grasp the cable handles with an overhand grip at shoulder height.","Step:4 Push the handles forward and away from your body, extending your arms fully.","Step:5 Pause for a moment, then slowly bring the handles back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nIR4Rwl.gif','https://static.exercisedb.dev/media/nIR4Rwl.gif',NULL),
('niXESDw','dumbbell biceps curl squat',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Step:2 Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Step:3 Pause for a moment at the top, squeezing your biceps.","Step:4 Inhale and slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/niXESDw.gif','https://static.exercisedb.dev/media/niXESDw.gif',NULL),
('NJzBsGJ','dumbbell shrug',NULL,'back','traps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand with your palms facing your body.","Step:2 Keep your arms straight and let the dumbbells hang by your sides.","Step:3 Raise your shoulders as high as possible, as if you are trying to touch your ears with your shoulders.","Step:4 Hold the contraction for a second, then slowly lower your shoulders back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NJzBsGJ.gif','https://static.exercisedb.dev/media/NJzBsGJ.gif',NULL),
('NKJ8o6x','pelvic tilt',NULL,'core','abs','{"lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands by your sides.","Step:3 Engage your abs and tilt your pelvis upward, pressing your lower back into the ground.","Step:4 Hold this position for a few seconds, focusing on contracting your abs.","Step:5 Release the tilt and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NKJ8o6x.gif','https://static.exercisedb.dev/media/NKJ8o6x.gif',NULL),
('NL6YBwN','dumbbell decline one arm fly',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Step:2 Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Step:3 Rotate your wrist so that the palm of your hand is facing forward.","Step:4 As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Step:5 Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/NL6YBwN.gif','https://static.exercisedb.dev/media/NL6YBwN.gif',NULL),
('NlfIbzq','dumbbell alternate preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Step:2 Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Step:3 Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Step:4 Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Step:5 Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Step:6 Repeat the movement with your left arm.","Step:7 Continue alternating arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/NlfIbzq.gif','https://static.exercisedb.dev/media/NlfIbzq.gif',NULL),
('nlJsbkW','dumbbell biceps curl (with arm blaster)',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing forward.","Step:2 Keep your elbows close to your torso and your upper arms stationary.","Step:3 Exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nlJsbkW.gif','https://static.exercisedb.dev/media/nlJsbkW.gif',NULL),
('NN8nSNT','cable rope high pulley overhead tricep extension',NULL,'arms','triceps','{"shoulders"}','cable',NULL,'{"Step:1 Attach a rope to a high pulley and adjust the weight accordingly.","Step:2 Stand facing away from the pulley machine with your feet shoulder-width apart.","Step:3 Grasp the rope with both hands, palms facing down, and bring your hands above your head.","Step:4 Keep your upper arms close to your head and perpendicular to the floor.","Step:5 Slowly lower the rope behind your head by bending your elbows.","Step:6 Pause for a moment, then extend your arms back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NN8nSNT.gif','https://static.exercisedb.dev/media/NN8nSNT.gif',NULL),
('nnmCTLN','lever kneeling leg curl',NULL,'legs','hamstrings','{"glutes"}','machine',NULL,'{"Step:1 Adjust the machine to fit your body and select the desired weight.","Step:2 Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.","Step:3 Grasp the handles or the sides of the machine for stability.","Step:4 Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.","Step:5 Pause for a moment at the top of the movement, squeezing your hamstrings.","Step:6 Inhale and slowly lower your legs back to the starting position, fully extending your knees.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nnmCTLN.gif','https://static.exercisedb.dev/media/nnmCTLN.gif',NULL),
('NNoHCEA','smith full squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Set up the smith machine with the barbell at shoulder height.","Step:2 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:3 Step under the bar and position it across your upper back, resting on your traps.","Step:4 Grip the bar with your hands slightly wider than shoulder-width apart.","Step:5 Unrack the bar and take a step back, maintaining a stable stance.","Step:6 Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.","Step:7 Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.","Step:8 Pause for a moment at the bottom, then drive through your heels to return to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NNoHCEA.gif','https://static.exercisedb.dev/media/NNoHCEA.gif',NULL),
('nqs5HGV','single leg squat (pistol) male',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and arms extended in front of you.","Step:2 Lift your right foot off the ground and extend it forward.","Step:3 Slowly lower your body down by bending your left knee and pushing your hips back.","Step:4 Keep your chest up and your back straight as you lower yourself down.","Step:5 Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.","Step:6 Pause for a moment at the bottom, then push through your left heel to return to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch legs."}','https://static.exercisedb.dev/media/nqs5HGV.gif','https://static.exercisedb.dev/media/nqs5HGV.gif',NULL),
('ns0SIbU','dumbbell incline bench press',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.","Step:3 Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.","Step:4 Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Step:5 Push the dumbbells back up to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ns0SIbU.gif','https://static.exercisedb.dev/media/ns0SIbU.gif',NULL),
('ntjtCfu','barbell sitted alternate leg raise (female) with intermediate',NULL,'core','abs','{"hip flexors","quadriceps"}','barbell',NULL,'{"Step:1 Sit on a bench with your back straight and hold a barbell across your thighs.","Step:2 (intermediate variation) Place your hands on the sides of the bench for support.","Step:3 Keeping your legs straight, lift one leg up as high as possible while keeping it parallel to the ground.","Step:4 Lower the leg back down and repeat with the other leg.","Step:5 Continue alternating legs for the desired number of repetitions."}','https://static.exercisedb.dev/media/ntjtCfu.gif','https://static.exercisedb.dev/media/ntjtCfu.gif',NULL),
('Nu7jqFE','resistance band seated straight back row',NULL,'back','upper back','{"biceps","shoulders"}','resistance band',NULL,'{"Step:1 Sit on the floor with your legs extended and loop the resistance band around your feet.","Step:2 Hold the ends of the resistance band with your hands, palms facing each other.","Step:3 Keep your back straight and lean slightly back, engaging your core.","Step:4 Pull the resistance band towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the top, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Nu7jqFE.gif','https://static.exercisedb.dev/media/Nu7jqFE.gif',NULL),
('nuBF9MO','hanging pike',NULL,'core','abs','{"hip flexors","shoulders"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up towards the bar, keeping them straight.","Step:3 Continue lifting until your body forms a 'V' shape, with your legs parallel to the ground.","Step:4 Hold the position for a moment, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nuBF9MO.gif','https://static.exercisedb.dev/media/nuBF9MO.gif',NULL),
('numr601','light lever standing chest press',NULL,'chest','pectorals','{"shoulders","triceps"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your feet flat on the ground.","Step:2 Grasp the handles with an overhand grip and position your hands at chest level. Maintain light form throughout.","Step:3 Push the handles forward until your arms are fully extended, keeping your elbows slightly bent.","Step:4 Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/numr601.gif','https://static.exercisedb.dev/media/numr601.gif',NULL),
('nUwVh7b','dumbbell deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes pointing forward.","Step:2 Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Step:3 Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Step:4 Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nUwVh7b.gif','https://static.exercisedb.dev/media/nUwVh7b.gif',NULL),
('NvfE43H','cable concentration curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.","Step:2 Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.","Step:3 Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.","Step:4 Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/NvfE43H.gif','https://static.exercisedb.dev/media/NvfE43H.gif',NULL),
('nxW6BkN','dumbbell incline raise',NULL,'shoulders','delts','{"trapezius","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Step:2 Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Step:3 Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Step:4 Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nxW6BkN.gif','https://static.exercisedb.dev/media/nxW6BkN.gif',NULL),
('NZ5Qqkz','reverse dip',NULL,'arms','triceps','{"chest","shoulders"}','body weight',NULL,'{"Step:1 Position yourself between two parallel bars with your arms fully extended and your body straight.","Step:2 Lower your body by bending your elbows until your upper arms are parallel to the ground.","Step:3 Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/NZ5Qqkz.gif','https://static.exercisedb.dev/media/NZ5Qqkz.gif',NULL),
('nZZZy9m','lever high row',NULL,'back','upper back','{"biceps","rear deltoids"}','machine',NULL,'{"Step:1 Adjust the seat height and foot platform to a comfortable position.","Step:2 Sit on the machine with your chest against the pad and your feet flat on the foot platform.","Step:3 Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Keep your back straight and engage your core.","Step:5 Pull the handles towards your body, squeezing your shoulder blades together.","Step:6 Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/nZZZy9m.gif','https://static.exercisedb.dev/media/nZZZy9m.gif',NULL),
('o17Jfkt','lever incline chest press v. 2',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and backrest angle on the leverage machine to a comfortable position.","Step:2 Sit on the machine with your back against the backrest and your feet flat on the floor.","Step:3 Grasp the handles with an overhand grip and position your hands slightly wider than shoulder-width apart.","Step:4 Push the handles forward and away from your body until your arms are fully extended, but without locking your elbows.","Step:5 Pause for a moment at the fully extended position, then slowly bend your elbows and lower the handles back towards your chest.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/o17Jfkt.gif','https://static.exercisedb.dev/media/o17Jfkt.gif',NULL),
('o1HGDSq','exercise ball back extension with hands behind head',NULL,'back','spine','{"glutes","hamstrings"}','other',NULL,'{"Step:1 Place the stability ball on the ground and lie face down on top of it with your hips resting on the ball.","Step:2 Position your feet against a wall or other stable surface for support.","Step:3 Cross your arms behind your head, with your hands touching the back of your head.","Step:4 Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line from your head to your hips.","Step:5 Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/o1HGDSq.gif','https://static.exercisedb.dev/media/o1HGDSq.gif',NULL),
('o1ntciW','olympic barbell hammer curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.","Step:2 Let the barbell hang at arm's length in front of your thighs, with your palms facing your body.","Step:3 Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Step:4 Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly begin to lower the barbell back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/o1ntciW.gif','https://static.exercisedb.dev/media/o1ntciW.gif',NULL),
('O2K9Vb5','wide-grip chest dip on high parallel bars',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Position yourself on the parallel bars with your arms fully extended and your body suspended in the air.","Step:2 Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars.","Step:3 Pause for a moment, then push yourself back up to the starting position by straightening your arms.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/O2K9Vb5.gif','https://static.exercisedb.dev/media/O2K9Vb5.gif',NULL),
('O3INw8V','improved sphinx',NULL,'back','spine','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.","Step:2 Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.","Step:3 Hold this position for a few seconds, making sure to keep your neck in a neutral position.","Step:4 Slowly lower your chest back down to the starting position. Emphasize improved control.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/O3INw8V.gif','https://static.exercisedb.dev/media/O3INw8V.gif',NULL),
('O4oIqQD','bodyweight standing one arm row (with towel)',NULL,'back','upper back','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand.","Step:2 Bend forward at the hips, keeping your back straight and your core engaged.","Step:3 Pull the towel towards your chest, squeezing your shoulder blades together.","Step:4 Pause for a moment at the top, then slowly lower the towel back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/O4oIqQD.gif','https://static.exercisedb.dev/media/O4oIqQD.gif',NULL),
('o5Jsk92','dumbbell one arm bench fly',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Step:2 Lie back on the bench, keeping the dumbbell pressed against your thigh.","Step:3 Using your free hand, help lift the dumbbell up to the starting position.","Step:4 Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Step:5 Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Step:6 Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch arms and repeat."}','https://static.exercisedb.dev/media/o5Jsk92.gif','https://static.exercisedb.dev/media/o5Jsk92.gif',NULL),
('o6LqKKP','traditional barbell romanian deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your toes pointing forward.","Step:2 Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Bend at the hips, keeping your back straight and your knees slightly bent.","Step:4 Lower the barbell towards the ground, keeping it close to your body.","Step:5 Feel the stretch in your hamstrings as you lower the barbell.","Step:6 Once you feel a stretch in your hamstrings, push your hips forward and stand up straight.","Step:7 Squeeze your glutes at the top of the movement.","Step:8 Lower the barbell back down to the starting position and repeat for the desired number of repetitions. Focus on traditional movement."}','https://static.exercisedb.dev/media/o6LqKKP.gif','https://static.exercisedb.dev/media/o6LqKKP.gif',NULL),
('o80Xu9C','intensified style kettlebell extended range one arm press on floor',NULL,'chest','pectorals','{"triceps","shoulders"}','kettlebell',NULL,'{"Step:1 Start by lying on your back on the floor with your knees bent and feet flat on the ground.","Step:2 Hold a kettlebell in one hand, with your palm facing towards your feet.","Step:3 Extend your arm straight up towards the ceiling, keeping your elbow locked and your wrist straight.","Step:4 Slowly lower the kettlebell back down to the starting position, maintaining control throughout the movement.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm. Perform with intensified intensity."}','https://static.exercisedb.dev/media/o80Xu9C.gif','https://static.exercisedb.dev/media/o80Xu9C.gif',NULL),
('o8aOcrz','smith machine incline tricep extension',NULL,'arms','triceps','{"shoulders"}','machine',NULL,'{"Step:1 Adjust the seat of the smith machine so that the bar is at shoulder height.","Step:2 Sit on the bench with your back against the pad and your feet flat on the ground.","Step:3 Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.","Step:4 Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.","Step:5 Lower the bar slowly towards your forehead, keeping your elbows close to your head.","Step:6 Pause for a moment at the bottom, then push the bar back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/o8aOcrz.gif','https://static.exercisedb.dev/media/o8aOcrz.gif',NULL),
('O8Aq69u','dumbbell reverse preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.","Step:2 Hold a dumbbell in each hand with an underhand grip, palms facing up.","Step:3 Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.","Step:4 Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Step:5 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:6 Inhale and slowly lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/O8Aq69u.gif','https://static.exercisedb.dev/media/O8Aq69u.gif',NULL),
('O8o7q4d','dumbbell press on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Step:2 Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Step:3 Raise the dumbbells to shoulder height, palms facing forward.","Step:4 Press the dumbbells upward until your arms are fully extended.","Step:5 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/O8o7q4d.gif','https://static.exercisedb.dev/media/O8o7q4d.gif',NULL),
('O95afRA','monster walk',NULL,'legs','glutes','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Place a resistance band around your ankles.","Step:2 Stand with your feet shoulder-width apart and slightly bend your knees.","Step:3 Take a step to the side with your right foot, maintaining tension on the resistance band.","Step:4 Follow with your left foot, stepping to the side to return to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/O95afRA.gif','https://static.exercisedb.dev/media/O95afRA.gif',NULL),
('OaE7CpD','kettlebell double windmill',NULL,'core','abs','{"shoulders","hamstrings"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.","Step:2 Extend your right arm overhead, keeping your eyes on the kettlebell.","Step:3 Rotate your left foot 45 degrees to the left and your right foot 90 degrees to the right.","Step:4 Bend at the waist to the left, keeping your right arm extended overhead.","Step:5 Lower the kettlebell towards the ground, reaching towards your left foot.","Step:6 Pause for a moment, then engage your core and push through your right foot to return to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/OaE7CpD.gif','https://static.exercisedb.dev/media/OaE7CpD.gif',NULL),
('OAguZoG','lever hammer grip preacher curl',NULL,'arms','biceps','{"forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the leverage machine.","Step:2 Place your upper arms on the preacher pad, ensuring your chest is pressed against it.","Step:3 Grasp the handles with a hammer grip (palms facing each other).","Step:4 Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.","Step:5 Pause for a moment at the top, squeezing your biceps.","Step:6 Inhale and slowly lower the handles back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OAguZoG.gif','https://static.exercisedb.dev/media/OAguZoG.gif',NULL),
('obe5LMq','band side triceps extension',NULL,'arms','triceps','{"shoulders"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Step:2 Extend your arms straight out to the sides, keeping them parallel to the ground.","Step:3 Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Step:4 Pause for a moment, then slowly extend your arms back out to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/obe5LMq.gif','https://static.exercisedb.dev/media/obe5LMq.gif',NULL),
('ocYc6Db','dumbbell standing one arm palm in press',NULL,'shoulders','delts','{"triceps","core"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in one hand at shoulder height with your palm facing inwards.","Step:2 Engage your core and keep your back straight.","Step:3 Press the dumbbell upwards until your arm is fully extended.","Step:4 Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/ocYc6Db.gif','https://static.exercisedb.dev/media/ocYc6Db.gif',NULL),
('OeL23VY','dumbbell seated biceps curl to shoulder press',NULL,'arms','biceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell in each hand with your palms facing forward and arms fully extended.","Step:3 Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.","Step:4 Once your forearms are vertical, rotate your wrists so that your palms are facing forward.","Step:5 Press the dumbbells overhead until your arms are fully extended.","Step:6 Lower the dumbbells back down to the starting position by reversing the movement.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OeL23VY.gif','https://static.exercisedb.dev/media/OeL23VY.gif',NULL),
('oHg8eop','medicine ball overhead slam',NULL,'back','upper back','{"shoulders","core"}','medicine ball',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head.","Step:2 Engage your core and keep your back straight.","Step:3 Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you.","Step:4 As you slam the ball down, use your entire body to generate power, including your shoulders and core.","Step:5 Catch the ball on the bounce and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oHg8eop.gif','https://static.exercisedb.dev/media/oHg8eop.gif',NULL),
('oHsrypV','lever seated hip adduction',NULL,'legs','adductors','{"hamstrings","glutes"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the backrest.","Step:2 Place your feet on the footrests and grasp the handles for stability.","Step:3 Engage your adductor muscles and slowly bring your legs together, squeezing your inner thighs.","Step:4 Pause for a moment at the peak contraction, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oHsrypV.gif','https://static.exercisedb.dev/media/oHsrypV.gif',NULL),
('OIFMAp1','lever one arm lateral high row',NULL,'back','upper back','{"biceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself facing the machine.","Step:2 Grasp the handle with one hand and keep your back straight.","Step:3 Pull the handle towards your body, keeping your elbow close to your side.","Step:4 Squeeze your back muscles at the top of the movement.","Step:5 Slowly release the handle back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OIFMAp1.gif','https://static.exercisedb.dev/media/OIFMAp1.gif',NULL),
('OJFgZJ0','dynamic style barbell lying back of the head tricep extension',NULL,'arms','triceps','{"shoulders"}','barbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Step:2 Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.","Step:3 Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows. Maintain dynamic form throughout.","Step:4 Pause for a moment, then extend your arms back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OJFgZJ0.gif','https://static.exercisedb.dev/media/OJFgZJ0.gif',NULL),
('oLrKqDH','run',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Start by standing upright with your feet hip-width apart.","Step:2 Engage your core and keep your upper body relaxed.","Step:3 Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet.","Step:4 Maintain a steady pace and continue jogging for the desired duration or distance.","Step:5 Remember to breathe deeply and maintain good posture throughout the exercise."}','https://static.exercisedb.dev/media/oLrKqDH.gif','https://static.exercisedb.dev/media/oLrKqDH.gif',NULL),
('OM46QHm','cable pull through (with rope)',NULL,'legs','glutes','{"hamstrings","lower back"}','cable',NULL,'{"Step:1 Stand facing away from the cable machine with your feet shoulder-width apart.","Step:2 Grab the rope attachment with both hands and step forward, creating tension in the cable.","Step:3 Bend at the hips and lower your upper body until it is parallel to the ground, keeping your back straight.","Step:4 Engage your glutes and hamstrings to pull your body back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OM46QHm.gif','https://static.exercisedb.dev/media/OM46QHm.gif',NULL),
('OmQ8w0p','cable palm rotational row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Attach a handle to a cable machine at waist height.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the handle with an overhand grip, palms facing down.","Step:4 Step back to create tension on the cable, keeping your back straight and knees slightly bent.","Step:5 Pull the handle towards your body, rotating your palms to face upwards as you do so.","Step:6 Squeeze your shoulder blades together at the end of the movement.","Step:7 Slowly release the handle back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OmQ8w0p.gif','https://static.exercisedb.dev/media/OmQ8w0p.gif',NULL),
('omsF3RN','dynamic style band side triceps extension',NULL,'arms','triceps','{"shoulders"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold the band with both hands, palms facing down.","Step:2 Extend your arms straight out to the sides, keeping them parallel to the ground.","Step:3 Slowly bend your elbows and bring your hands towards your shoulders, keeping your upper arms still.","Step:4 Pause for a moment, then slowly extend your arms back out to the starting position.","Step:5 (dynamic variation) Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/omsF3RN.gif','https://static.exercisedb.dev/media/omsF3RN.gif',NULL),
('oMwyl17','intense barbell straight leg deadlift',NULL,'legs','hamstrings','{"glutes","lower back"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your toes pointing forward.","Step:2 Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Bend at your hips and lower the barbell towards the ground, keeping your back straight and your knees slightly bent.","Step:4 Lower the barbell until you feel a stretch in your hamstrings. Maintain intense form throughout.","Step:5 Engage your hamstrings and glutes to lift the barbell back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oMwyl17.gif','https://static.exercisedb.dev/media/oMwyl17.gif',NULL),
('oMypNrz','roller hip stretch',NULL,'legs','glutes','{"hamstrings","quadriceps"}','other',NULL,'{"Step:1 Start by sitting on the ground with your legs extended in front of you.","Step:2 Place the roller under your glutes, just above your knees.","Step:3 Lean back and place your hands on the ground behind you for support.","Step:4 Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.","Step:5 Pause for a moment at the end of the movement, feeling a stretch in your glutes.","Step:6 Slowly roll the roller back to the starting position, extending your legs.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oMypNrz.gif','https://static.exercisedb.dev/media/oMypNrz.gif',NULL),
('ookVu2D','wall style dumbbell pullover hip extension on exercise ball',NULL,'chest','pectorals','{"triceps","shoulders","core"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Step:2 Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Step:3 Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Step:4 Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Step:5 Pause for a moment, then raise the dumbbell back to the starting position.","Step:6 While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Step:7 (wall variation) Lower your hips back down to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/ookVu2D.gif','https://static.exercisedb.dev/media/ookVu2D.gif',NULL),
('oom75KC','dumbbell straight leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Step:2 Keeping your back straight and your core engaged, hinge at the hips and lower the dumbbells towards the ground, allowing your torso to lean forward.","Step:3 Continue lowering the dumbbells until you feel a stretch in your hamstrings, keeping your knees slightly bent.","Step:4 Pause for a moment at the bottom, then engage your glutes and hamstrings to lift your torso back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oom75KC.gif','https://static.exercisedb.dev/media/oom75KC.gif',NULL),
('OPqShYN','lever hip extension v. 2',NULL,'legs','glutes','{"hamstrings"}','machine',NULL,'{"Step:1 Adjust the machine to fit your body and sit on it with your back against the backrest.","Step:2 Place your feet on the footrests and grip the handles for stability.","Step:3 Engage your glutes and hamstrings, then push against the footrests to extend your hips and raise your legs backward.","Step:4 Pause for a moment at the top, then slowly lower your legs back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OPqShYN.gif','https://static.exercisedb.dev/media/OPqShYN.gif',NULL),
('OQ1otBN','cable cross-over lateral pulldown',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Attach a cable handle to each side of a cable machine at shoulder height.","Step:2 Stand in the middle of the machine with your feet shoulder-width apart.","Step:3 Grasp the handles with an overhand grip and step back to create tension in the cables.","Step:4 Lean forward slightly from the hips, keeping your back straight and your chest up.","Step:5 Pull the handles down and across your body, squeezing your shoulder blades together.","Step:6 Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OQ1otBN.gif','https://static.exercisedb.dev/media/OQ1otBN.gif',NULL),
('oQRJYkC','side push neck stretch',NULL,'other','levator scapulae','{"trapezius","sternocleidomastoid"}','body weight',NULL,'{"Step:1 Stand or sit up straight with your shoulders relaxed.","Step:2 Tilt your head to the right, bringing your right ear towards your right shoulder.","Step:3 Place your right hand on the left side of your head and gently apply pressure to increase the stretch.","Step:4 Hold the stretch for 15-30 seconds.","Step:5 Repeat on the other side, tilting your head to the left and applying pressure with your left hand.","Step:6 Repeat the stretch 2-3 times on each side."}','https://static.exercisedb.dev/media/oQRJYkC.gif','https://static.exercisedb.dev/media/oQRJYkC.gif',NULL),
('oR7O9LW','barbell squat (on knees)',NULL,'legs','quads','{"glutes","hamstrings","calves"}','barbell',NULL,'{"Step:1 Start by kneeling on the ground with your knees hip-width apart and your toes pointing forward.","Step:2 Place a barbell across your shoulders, gripping it with an overhand grip and your hands slightly wider than shoulder-width apart.","Step:3 Engage your core and keep your chest lifted as you slowly lower your body down by bending your knees, keeping your back straight.","Step:4 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Pause for a moment at the bottom, then push through your heels to return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oR7O9LW.gif','https://static.exercisedb.dev/media/oR7O9LW.gif',NULL),
('OrETs32','reverse hyper on flat bench',NULL,'legs','glutes','{"hamstrings","lower back"}','body weight',NULL,'{"Step:1 Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.","Step:2 Hold onto the bench for stability.","Step:3 Keeping your legs straight, raise them up towards the ceiling as high as you can.","Step:4 Squeeze your glutes at the top of the movement.","Step:5 Slowly lower your legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OrETs32.gif','https://static.exercisedb.dev/media/OrETs32.gif',NULL),
('oROuvrX','lever unilateral row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself facing the machine.","Step:2 Grasp the handles with an overhand grip and keep your back straight.","Step:3 Pull the handles towards your body, squeezing your shoulder blades together.","Step:4 Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oROuvrX.gif','https://static.exercisedb.dev/media/oROuvrX.gif',NULL),
('osdXT3K','kettlebell one arm push press',NULL,'shoulders','delts','{"triceps","core"}','kettlebell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a kettlebell in one hand at shoulder level.","Step:2 Bend your knees slightly and engage your core.","Step:3 Press the kettlebell overhead by extending your arm and fully extending your legs.","Step:4 Lower the kettlebell back to the starting position by bending your knees and bringing the kettlebell back to your shoulder.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/osdXT3K.gif','https://static.exercisedb.dev/media/osdXT3K.gif',NULL),
('OTgkHwR','dumbbell decline triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms fully, keeping your elbows close to your head.","Step:3 Lower the dumbbells slowly behind your head, bending your elbows.","Step:4 Pause for a moment, then raise the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OTgkHwR.gif','https://static.exercisedb.dev/media/OTgkHwR.gif',NULL),
('otqIxU4','cable lying bicep curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a straight bar to a low pulley cable machine.","Step:2 Lie face up on a flat bench with your feet flat on the ground.","Step:3 Grasp the bar with an underhand grip, hands shoulder-width apart.","Step:4 Extend your arms fully, keeping your elbows close to your sides.","Step:5 Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.","Step:6 Pause for a moment at the top, squeezing your biceps.","Step:7 Inhale and slowly lower the bar back to the starting position, fully extending your arms.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/otqIxU4.gif','https://static.exercisedb.dev/media/otqIxU4.gif',NULL),
('OUQ0ZyW','smith shrug',NULL,'back','traps','{"shoulders"}','machine',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your knees slightly bent.","Step:2 Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.","Step:3 Keep your arms straight and your shoulders relaxed.","Step:4 Lift your shoulders up towards your ears, squeezing your traps at the top.","Step:5 Hold for a moment, then slowly lower your shoulders back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OUQ0ZyW.gif','https://static.exercisedb.dev/media/OUQ0ZyW.gif',NULL),
('OVIKwsd','dumbbell incline triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Step:2 Extend your arms fully overhead, keeping your elbows close to your head.","Step:3 Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Step:4 Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OVIKwsd.gif','https://static.exercisedb.dev/media/OVIKwsd.gif',NULL),
('OVLmUuL','dumbbell incline palm-in press',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Set up an incline bench at a 45-degree angle.","Step:2 Sit on the bench with a dumbbell in each hand, palms facing each other.","Step:3 Plant your feet firmly on the ground and keep your back straight against the bench.","Step:4 Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Step:5 Press the dumbbells up and away from your body, extending your arms fully.","Step:6 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OVLmUuL.gif','https://static.exercisedb.dev/media/OVLmUuL.gif',NULL),
('OVTZ65k','ez-barbell standing wide grip biceps curl',NULL,'arms','biceps','{"forearms"}','barbell',NULL,'{"Step:1 Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.","Step:2 Keep your elbows close to your torso and your upper arms stationary throughout the movement.","Step:3 Curl the barbell up towards your shoulders by contracting your biceps.","Step:4 Pause for a moment at the top, then slowly lower the barbell back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OVTZ65k.gif','https://static.exercisedb.dev/media/OVTZ65k.gif',NULL),
('OxJk1fg','cable triceps pushdown (v-bar) (with arm blaster)',NULL,'arms','triceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a v-bar attachment to the cable machine at the highest setting.","Step:2 Stand facing the cable machine with your feet shoulder-width apart.","Step:3 Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Step:4 Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Step:5 Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Step:6 Pause for a moment at the bottom of the movement, squeezing your triceps.","Step:7 Inhale as you slowly return the v-bar to the starting position, maintaining control.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OxJk1fg.gif','https://static.exercisedb.dev/media/OxJk1fg.gif',NULL),
('OYFhXVD','wide grip rear pull-up',NULL,'back','lats','{"biceps","forearms"}','body weight',NULL,'{"Step:1 Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Hang from the bar with your arms fully extended and your body straight.","Step:3 Engage your back muscles and pull your body up towards the bar, leading with your chest.","Step:4 Continue pulling until your chin is above the bar.","Step:5 Pause for a moment at the top, then slowly lower your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OYFhXVD.gif','https://static.exercisedb.dev/media/OYFhXVD.gif',NULL),
('OyoZ3Pu','leg pull in flat bench',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Sit on a flat bench with your legs extended straight out in front of you.","Step:2 Place your hands on the bench beside your hips for support.","Step:3 Engage your abs and lift your legs off the ground, bringing your knees towards your chest.","Step:4 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/OyoZ3Pu.gif','https://static.exercisedb.dev/media/OyoZ3Pu.gif',NULL),
('oZjMu1t','tire flip',NULL,'legs','glutes','{"hamstrings","quadriceps","core"}','tire',NULL,'{"Step:1 Stand with your feet shoulder-width apart, facing the tire.","Step:2 Bend your knees and hinge at the hips, lowering into a squat position.","Step:3 Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.","Step:4 Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.","Step:5 As the tire flips over, use your upper body strength to guide it and maintain control.","Step:6 Once the tire is fully flipped, quickly step back and reset your stance.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/oZjMu1t.gif','https://static.exercisedb.dev/media/oZjMu1t.gif',NULL),
('p0OCXGb','sled 45в° leg wide press - blunt variation',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the sled machine to a 45-degree angle.","Step:2 Sit on the sled machine with your back against the pad and your feet on the foot platform.","Step:3 Position your feet wider than shoulder-width apart.","Step:4 Push against the foot platform to extend your legs and straighten your knees.","Step:5 Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position. Maintain blunt form throughout.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/p0OCXGb.gif','https://static.exercisedb.dev/media/p0OCXGb.gif',NULL),
('P14Dz9D','cable one arm incline fly on exercise ball',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Sit on an exercise ball with your feet flat on the ground and your back against an incline bench.","Step:2 Hold a cable handle in one hand with your arm extended and palm facing inward.","Step:3 Keeping a slight bend in your elbow, slowly lower your arm out to the side until your hand is in line with your shoulder.","Step:4 Pause for a moment, then squeeze your chest muscles to bring your arm back to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch arms."}','https://static.exercisedb.dev/media/P14Dz9D.gif','https://static.exercisedb.dev/media/P14Dz9D.gif',NULL),
('p195zsJ','two toe touch (male)',NULL,'back','spine','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and your arms extended out to the sides.","Step:2 Bend forward at the waist, keeping your back straight and your knees slightly bent.","Step:3 Reach down towards your toes with both hands, keeping your legs straight.","Step:4 Pause for a moment at the bottom, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/p195zsJ.gif','https://static.exercisedb.dev/media/p195zsJ.gif',NULL),
('P2lNrGL','cable preacher curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the preacher curl pad is at chest height.","Step:2 Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.","Step:3 Keep your back straight and your elbows tucked in at your sides.","Step:4 Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.","Step:5 Pause for a moment, then slowly lower the cable attachment back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/P2lNrGL.gif','https://static.exercisedb.dev/media/P2lNrGL.gif',NULL),
('P2nRiUa','dumbbell standing zottman preacher curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing forward.","Step:2 Place your upper arms against the preacher bench and keep your elbows slightly bent.","Step:3 Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.","Step:4 At the top of the movement, rotate your wrists so that your palms are facing downward.","Step:5 Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/P2nRiUa.gif','https://static.exercisedb.dev/media/P2nRiUa.gif',NULL),
('P5p0j8B','cable standing cross-over high reverse fly',NULL,'shoulders','delts','{"trapezius","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Attach a D-handle to each side of a cable machine at shoulder height.","Step:2 Stand in the middle of the cable machine with your feet shoulder-width apart.","Step:3 Grasp the handles with an overhand grip and extend your arms out to the sides, palms facing forward.","Step:4 Keep a slight bend in your elbows and maintain a straight back throughout the exercise.","Step:5 Engage your shoulder muscles and squeeze your shoulder blades together as you pull the handles towards the front of your body.","Step:6 Pause for a moment at the peak of the movement, then slowly return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/P5p0j8B.gif','https://static.exercisedb.dev/media/P5p0j8B.gif',NULL),
('p5v6rdT','iron cross stretch - deep variation',NULL,'legs','glutes','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Lie flat on your back with your arms extended out to the sides.","Step:2 Raise your legs up towards the ceiling, keeping them straight.","Step:3 Slowly lower your legs to one side, aiming to touch the floor with your feet.","Step:4 Hold the stretch for a few seconds, then return your legs to the starting position.","Step:5 Repeat the stretch on the other side. Maintain deep form throughout.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/p5v6rdT.gif','https://static.exercisedb.dev/media/p5v6rdT.gif',NULL),
('P7zSvul','push up on bosu ball with improved',NULL,'chest','pectorals','{"triceps","shoulders","core"}','other',NULL,'{"Step:1 Place the bosu ball on the ground with the flat side facing up.","Step:2 Position yourself in a push-up position with your hands on the outer edges of the bosu ball.","Step:3 Engage your core and lower your body down towards the bosu ball by bending your elbows. Focus on improved movement.","Step:4 Push yourself back up to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/P7zSvul.gif','https://static.exercisedb.dev/media/P7zSvul.gif',NULL),
('p9cCe2r','spell caster',NULL,'core','abs','{"obliques","lower back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Step:2 Bend your knees slightly and hinge forward at the waist, keeping your back straight.","Step:3 Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.","Step:4 Return to the starting position and repeat on the other side.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/p9cCe2r.gif','https://static.exercisedb.dev/media/p9cCe2r.gif',NULL),
('P9GFBME','spider crawl push up',NULL,'legs','glutes','{"core","chest","shoulders"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.","Step:2 Bring your right knee towards your right elbow, keeping it off the ground.","Step:3 As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.","Step:4 Push back up to the starting position and repeat with your left knee towards your left elbow.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/P9GFBME.gif','https://static.exercisedb.dev/media/P9GFBME.gif',NULL),
('P9ZRyLT','hyght dumbbell fly',NULL,'chest','pectorals','{"shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Step:2 Extend your arms straight up over your chest, with a slight bend in your elbows.","Step:3 Keeping a slight bend in your elbows, lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Step:4 Pause for a moment, then reverse the movement and bring the dumbbells back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/P9ZRyLT.gif','https://static.exercisedb.dev/media/P9ZRyLT.gif',NULL),
('PAgTVaK','assisted chest dip (kneeling)',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the machine to your desired height and secure your knees on the pad.","Step:2 Grasp the handles with your palms facing down and your arms fully extended.","Step:3 Lower your body by bending your elbows until your upper arms are parallel to the floor.","Step:4 Pause for a moment, then push yourself back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PAgTVaK.gif','https://static.exercisedb.dev/media/PAgTVaK.gif',NULL),
('pAIWRGu','hands bike',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the seat height and handlebar position to a comfortable level.","Step:2 Sit on the ergometer with your back straight and feet on the pedals.","Step:3 Grasp the handles with your hands and position your arms at a 90-degree angle.","Step:4 Start pedaling with your hands, pushing and pulling the handles in a controlled motion.","Step:5 Continue pedaling for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/pAIWRGu.gif','https://static.exercisedb.dev/media/pAIWRGu.gif',NULL),
('PbzNu7c','dumbbell incline y-raise',NULL,'back','upper back','{"shoulders","rear deltoids"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Step:2 Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Step:3 Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PbzNu7c.gif','https://static.exercisedb.dev/media/PbzNu7c.gif',NULL),
('PcPe0P5','cable rope hammer preacher curl',NULL,'arms','biceps','{"forearms"}','cable',NULL,'{"Step:1 Attach a rope attachment to a low pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the rope with a neutral grip (palms facing each other).","Step:4 Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.","Step:5 Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.","Step:6 Hold the contracted position for a brief pause as you squeeze your biceps.","Step:7 Inhale and slowly lower the rope back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PcPe0P5.gif','https://static.exercisedb.dev/media/PcPe0P5.gif',NULL),
('PCUYOMs','pulse style walk elliptical cross trainer',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','elliptical machine',NULL,'{"Step:1 Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step:2 Step onto the pedals of the machine and grip the handles lightly.","Step:3 Begin by pushing down with your feet and pulling the handles towards your body.","Step:4 Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion.","Step:5 Maintain a steady pace and keep your core engaged throughout the exercise. Emphasize pulse control.","Step:6 Continue for the desired duration of your cardio workout.","Step:7 Gradually decrease the intensity and speed of the machine before stepping off."}','https://static.exercisedb.dev/media/PCUYOMs.gif','https://static.exercisedb.dev/media/PCUYOMs.gif',NULL),
('PDaMuyV','dumbbell one arm incline chest press',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Adjust the incline bench to a 45-degree angle.","Step:2 Sit on the bench with your back against the pad and feet flat on the ground.","Step:3 Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Step:4 Push the dumbbell up and away from your body, extending your arm fully.","Step:5 Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/PDaMuyV.gif','https://static.exercisedb.dev/media/PDaMuyV.gif',NULL),
('PDHE73u','controlled band straight back stiff leg deadlift',NULL,'legs','glutes','{"hamstrings","lower back"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band around your upper legs.","Step:2 Hold the band with both hands in front of your thighs, palms facing your body.","Step:3 Keeping your back straight and your knees slightly bent, hinge at the hips and lower the band towards the ground. Focus on controlled movement.","Step:4 Feel the stretch in your hamstrings as you lower the band.","Step:5 Engage your glutes and hamstrings to lift your body back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PDHE73u.gif','https://static.exercisedb.dev/media/PDHE73u.gif',NULL),
('PdmaD0N','dumbbell standing triceps extension',NULL,'arms','triceps','{"shoulders"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in one hand.","Step:2 Raise the dumbbell overhead, keeping your arm straight.","Step:3 Bend your elbow and lower the dumbbell behind your head, keeping your upper arm stationary.","Step:4 Extend your arm back up to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PdmaD0N.gif','https://static.exercisedb.dev/media/PdmaD0N.gif',NULL),
('peAeMR3','band shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','resistance band',NULL,'{"Step:1 Stand with your feet shoulder-width apart and place the band under your feet.","Step:2 Hold the band with your palms facing forward and raise your hands to shoulder height, elbows bent.","Step:3 Press the band overhead, fully extending your arms.","Step:4 Pause for a moment at the top, then slowly lower the band back to shoulder height.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/peAeMR3.gif','https://static.exercisedb.dev/media/peAeMR3.gif',NULL),
('PERjVm8','exercise ball back extension with arms extended',NULL,'back','spine','{"glutes","hamstrings"}','other',NULL,'{"Step:1 Place the stability ball on the ground and lie face down on top of it, with your hips resting on the ball and your feet against a wall for stability.","Step:2 Extend your arms straight out in front of you, with your palms facing down.","Step:3 Engage your core and slowly lift your upper body off the ball, keeping your back straight and your neck in line with your spine.","Step:4 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PERjVm8.gif','https://static.exercisedb.dev/media/PERjVm8.gif',NULL),
('pFuK3by','walk elliptical cross trainer - expanded variation',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","glutes","calves"}','elliptical machine',NULL,'{"Step:1 Adjust the resistance level and incline of the elliptical machine to your desired settings.","Step:2 Step onto the pedals of the machine and grip the handles lightly.","Step:3 Begin by pushing down with your feet and pulling the handles towards your body.","Step:4 Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion. Emphasize expanded control.","Step:5 Maintain a steady pace and keep your core engaged throughout the exercise.","Step:6 Continue for the desired duration of your cardio workout.","Step:7 Gradually decrease the intensity and speed of the machine before stepping off."}','https://static.exercisedb.dev/media/pFuK3by.gif','https://static.exercisedb.dev/media/pFuK3by.gif',NULL),
('PG1kcIb','dumbbell incline hammer press',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Step:2 Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Step:3 Press the dumbbells up and away from your body until your arms are fully extended.","Step:4 Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PG1kcIb.gif','https://static.exercisedb.dev/media/PG1kcIb.gif',NULL),
('pgIdT6i','band one arm standing low row - lateral variation',NULL,'back','upper back','{"biceps","shoulders"}','resistance band',NULL,'{"Step:1 Attach the band to a stable anchor point at waist height.","Step:2 Stand facing the anchor point with your feet shoulder-width apart.","Step:3 Hold the band with one hand, palm facing inward, and step back to create tension in the band.","Step:4 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:5 Pull the band towards your waist, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly release the band back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch sides. Emphasize lateral control."}','https://static.exercisedb.dev/media/pgIdT6i.gif','https://static.exercisedb.dev/media/pgIdT6i.gif',NULL),
('pH2x2jj','dumbbell one leg fly on exercise ball',NULL,'chest','pectorals','{"shoulders","triceps"}','dumbbell',NULL,'{"Step:1 Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Step:2 Place one foot on the ground and extend the other leg straight out in front of you.","Step:3 Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Step:4 Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Step:5 Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch legs and repeat."}','https://static.exercisedb.dev/media/pH2x2jj.gif','https://static.exercisedb.dev/media/pH2x2jj.gif',NULL),
('pj0X0tF','hanging straight leg hip raise',NULL,'core','abs','{"hip flexors"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your palms facing away from you.","Step:2 Engage your core and lift your legs up in front of you until they are parallel to the ground.","Step:3 Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/pj0X0tF.gif','https://static.exercisedb.dev/media/pj0X0tF.gif',NULL),
('Pjbc0Kt','resistance band hip thrusts on knees (female)',NULL,'legs','glutes','{"hamstrings","quadriceps"}','resistance band',NULL,'{"Step:1 Start by kneeling on the ground with your knees hip-width apart and your feet flexed.","Step:2 Wrap the resistance band around your thighs, just above your knees.","Step:3 Place your hands on your hips or extend them out in front of you for balance.","Step:4 Engage your glutes and core muscles.","Step:5 Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground.","Step:6 Hold the position for a moment, then slowly lower your knees back down to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Pjbc0Kt.gif','https://static.exercisedb.dev/media/Pjbc0Kt.gif',NULL),
('PkCN2lv','front lever',NULL,'core','abs','{"lats","shoulders","forearms"}','body weight',NULL,'{"Step:1 Start by hanging from a pull-up bar with an overhand grip, hands shoulder-width apart.","Step:2 Engage your core and pull your shoulder blades down and back.","Step:3 Bend your knees and tuck them towards your chest.","Step:4 Simultaneously, lift your legs up and extend them straight out in front of you, keeping your body parallel to the ground.","Step:5 Hold this position for as long as you can, aiming for a full front lever position.","Step:6 To release, slowly lower your legs back down and return to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PkCN2lv.gif','https://static.exercisedb.dev/media/PkCN2lv.gif',NULL),
('PKlXuJW','rough band push sit-up',NULL,'core','abs','{"shoulders","chest"}','resistance band',NULL,'{"Step:1 Attach the band securely to a stable anchor point.","Step:2 Lie flat on your back with your knees bent and feet flat on the ground.","Step:3 Hold the band with both hands and extend your arms straight up towards the ceiling. Focus on rough movement.","Step:4 Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Step:5 Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PKlXuJW.gif','https://static.exercisedb.dev/media/PKlXuJW.gif',NULL),
('pkSoCW9','barbell jefferson squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and toes slightly turned out.","Step:2 Hold the barbell with an overhand grip, resting it on the front of your body, just below your waist.","Step:3 Step your left foot forward and your right foot back, keeping your feet shoulder-width apart.","Step:4 Bend your knees and lower your body down into a squat position, keeping your back straight and chest up.","Step:5 Push through your heels to stand back up to the starting position.","Step:6 Repeat the movement, alternating your forward and back foot with each repetition."}','https://static.exercisedb.dev/media/pkSoCW9.gif','https://static.exercisedb.dev/media/pkSoCW9.gif',NULL),
('pM07UxU','kipping muscle up',NULL,'back','lats','{"biceps","triceps","shoulders","core"}','body weight',NULL,'{"Step:1 Start by hanging from a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:2 Engage your core and use a swinging motion to generate momentum.","Step:3 As you swing forward, pull your chest towards the bar, using your lats and biceps to initiate the movement.","Step:4 Continue the upward motion until your chest reaches the bar, then transition into a dip position by pushing down on the bar and extending your arms.","Step:5 Lower yourself back down to the starting position by bending your arms and controlling the descent.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/pM07UxU.gif','https://static.exercisedb.dev/media/pM07UxU.gif',NULL),
('PM1PZjg','lunge with jump',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart.","Step:2 Take a step forward with your right foot, lowering your body into a lunge position.","Step:3 Push off with your right foot and jump into the air, switching the position of your feet mid-air.","Step:4 Land softly with your left foot forward and immediately lower your body into a lunge position.","Step:5 Continue alternating between lunges and jumps for the desired number of repetitions."}','https://static.exercisedb.dev/media/PM1PZjg.gif','https://static.exercisedb.dev/media/PM1PZjg.gif',NULL),
('pmnrOp0','band kneeling one arm pulldown',NULL,'back','lats','{"biceps","rhomboids"}','resistance band',NULL,'{"Step:1 Attach the band to a sturdy anchor point above your head.","Step:2 Kneel down and hold the band with one hand, palm facing down.","Step:3 Extend your arm fully overhead, keeping your elbow slightly bent.","Step:4 Engage your lat muscles and pull the band down towards your side, bringing your elbow towards your ribcage.","Step:5 Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/pmnrOp0.gif','https://static.exercisedb.dev/media/pmnrOp0.gif',NULL),
('pNIKolI','exercise ball seated triceps stretch wide',NULL,'arms','triceps','{"shoulders"}','other',NULL,'{"Step:1 Sit on a stability ball with your feet flat on the ground and your back straight.","Step:2 Hold a dumbbell in one hand and extend your arm straight up above your head.","Step:3 Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear. Maintain wide form throughout.","Step:4 Hold the stretch for a few seconds, then return to the starting position.","Step:5 Repeat with the other arm."}','https://static.exercisedb.dev/media/pNIKolI.gif','https://static.exercisedb.dev/media/pNIKolI.gif',NULL),
('PNtsX17','cable reverse-grip straight back seated high row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the seat facing the cable machine with your feet flat on the floor.","Step:2 Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.","Step:3 Keep your back straight and lean slightly forward from your hips.","Step:4 Pull the cable towards your torso by retracting your shoulder blades and squeezing your back muscles.","Step:5 Pause for a moment at the peak of the contraction, then slowly release the cable back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PNtsX17.gif','https://static.exercisedb.dev/media/PNtsX17.gif',NULL),
('PnZJIrk','assisted wide-grip chest dip (kneeling)',NULL,'chest','pectorals','{"triceps","shoulders"}','machine',NULL,'{"Step:1 Adjust the machine to your desired height and secure your knees on the pad.","Step:2 Grasp the handles with a wide grip and keep your elbows slightly bent.","Step:3 Lower your body by bending your elbows until your upper arms are parallel to the floor.","Step:4 Push yourself back up to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PnZJIrk.gif','https://static.exercisedb.dev/media/PnZJIrk.gif',NULL),
('pP8wP2P','dumbbell neutral grip bench press',NULL,'arms','triceps','{"chest","shoulders"}','dumbbell',NULL,'{"Step:1 Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Step:2 Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Step:3 Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Step:4 Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/pP8wP2P.gif','https://static.exercisedb.dev/media/pP8wP2P.gif',NULL),
('pQ0Mx1Z','flag',NULL,'core','abs','{"obliques","shoulders"}','body weight',NULL,'{"Step:1 Start by gripping a vertical pole with both hands, palms facing each other, and arms fully extended.","Step:2 Engage your core and lift your legs off the ground, keeping them straight.","Step:3 Using your core and upper body strength, raise your legs until they are parallel to the ground.","Step:4 Hold this position for as long as you can, maintaining a straight body line.","Step:5 Slowly lower your legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/pQ0Mx1Z.gif','https://static.exercisedb.dev/media/pQ0Mx1Z.gif',NULL),
('PQ2AtC3','lever seated leg raise crunch',NULL,'core','abs','{"hip flexors"}','machine',NULL,'{"Step:1 Sit on the leverage machine with your back against the backrest and your feet on the footrests.","Step:2 Grasp the handles or sidebars for stability.","Step:3 Engage your abs and slowly raise your legs up towards your chest, curling your torso forward at the same time.","Step:4 Pause for a moment at the top, then slowly lower your legs and torso back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PQ2AtC3.gif','https://static.exercisedb.dev/media/PQ2AtC3.gif',NULL),
('PQcUlDi','cable supine reverse fly',NULL,'shoulders','delts','{"trapezius","rhomboids"}','cable',NULL,'{"Step:1 Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Step:2 Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Step:3 Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Step:4 Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PQcUlDi.gif','https://static.exercisedb.dev/media/PQcUlDi.gif',NULL),
('PQStVXH','cable upper row',NULL,'back','upper back','{"biceps","shoulders"}','cable',NULL,'{"Step:1 Attach a straight bar to a cable machine at chest height.","Step:2 Stand facing the machine with your feet shoulder-width apart.","Step:3 Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Step:4 Keep your back straight and your core engaged.","Step:5 Pull the bar towards your upper chest, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement.","Step:7 Slowly release the bar back to the starting position.","Step:8 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PQStVXH.gif','https://static.exercisedb.dev/media/PQStVXH.gif',NULL),
('Pr9Rhf4','cable standing fly',NULL,'chest','pectorals','{"deltoids","triceps"}','cable',NULL,'{"Step:1 Attach the handles to the cables at chest height.","Step:2 Stand with your feet shoulder-width apart, facing away from the cable machine.","Step:3 Grasp the handles with an overhand grip, palms facing forward.","Step:4 Step forward slightly to create tension in the cables.","Step:5 Keep your core engaged and your back straight throughout the exercise.","Step:6 With a slight bend in your elbows, slowly bring your arms forward and together in front of your chest.","Step:7 Squeeze your chest muscles at the peak of the movement.","Step:8 Slowly reverse the movement, returning your arms to the starting position.","Step:9 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Pr9Rhf4.gif','https://static.exercisedb.dev/media/Pr9Rhf4.gif',NULL),
('prbWx1D','dumbbell rotation reverse fly',NULL,'shoulders','delts','{"trapezius","rhomboids"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing inwards.","Step:2 Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Step:3 Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Step:4 Rotate your arms so that your palms are facing downwards.","Step:5 Slowly lower your arms back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/prbWx1D.gif','https://static.exercisedb.dev/media/prbWx1D.gif',NULL),
('PrQbjvB','push to run',NULL,'cardio','cardiovascular system','{"quadriceps","hamstrings","calves"}','body weight',NULL,'{"Step:1 Start in a push-up position with your hands shoulder-width apart and your body in a straight line.","Step:2 Lower your chest towards the ground by bending your elbows, keeping your body straight.","Step:3 Push through your hands to extend your arms and return to the starting position.","Step:4 Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest.","Step:5 Continue alternating knees as fast as you can while maintaining good form.","Step:6 Continue for the desired duration or number of repetitions."}','https://static.exercisedb.dev/media/PrQbjvB.gif','https://static.exercisedb.dev/media/PrQbjvB.gif',NULL),
('PskORrA','cable pushdown (straight arm) v. 2',NULL,'back','lats','{"triceps","shoulders"}','cable',NULL,'{"Step:1 Attach a straight bar to a high pulley cable machine.","Step:2 Stand facing the machine with your feet shoulder-width apart and a slight bend in your knees.","Step:3 Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Step:4 Engage your core and keep your back straight as you exhale and push the bar down towards your thighs.","Step:5 Pause for a moment at the bottom, then slowly return the bar to the starting position while inhaling.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PskORrA.gif','https://static.exercisedb.dev/media/PskORrA.gif',NULL),
('PSlvNMs','weighted drop push up',NULL,'chest','pectorals','{"triceps","shoulders"}','other',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.","Step:2 Lower your chest towards the ground, keeping your elbows close to your body.","Step:3 Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.","Step:4 As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.","Step:5 Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.","Step:6 Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.","Step:7 Continue alternating between the wider and narrower hand positions for the desired number of repetitions."}','https://static.exercisedb.dev/media/PSlvNMs.gif','https://static.exercisedb.dev/media/PSlvNMs.gif',NULL),
('PsVS1QP','medicine ball catch and overhead throw',NULL,'back','lats','{"shoulders","core"}','medicine ball',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level.","Step:2 Bend your knees slightly and engage your core.","Step:3 Lower your body into a squat position, keeping your back straight and chest up.","Step:4 Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead.","Step:5 Release the ball at the top of the movement and catch it on the way down.","Step:6 Lower your body back into the squat position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PsVS1QP.gif','https://static.exercisedb.dev/media/PsVS1QP.gif',NULL),
('pvBMLHA','push-up plus',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Step:2 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up.","Step:4 At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling.","Step:5 Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/pvBMLHA.gif','https://static.exercisedb.dev/media/pvBMLHA.gif',NULL),
('pwt0pnM','cable seated high row (v-bar)',NULL,'back','lats','{"biceps","rhomboids","rear deltoids"}','cable',NULL,'{"Step:1 Sit on the cable machine with your feet flat on the floor and your knees slightly bent.","Step:2 Grasp the v-bar attachment with an overhand grip, palms facing each other, and your hands shoulder-width apart.","Step:3 Keep your back straight and lean slightly forward from the hips.","Step:4 Pull the v-bar towards your torso by retracting your shoulder blades and squeezing your back muscles.","Step:5 Pause for a moment at the peak of the contraction, then slowly release the tension and return to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/pwt0pnM.gif','https://static.exercisedb.dev/media/pwt0pnM.gif',NULL),
('pX9Elbe','medicine ball chest push with run release',NULL,'chest','pectorals','{"triceps","shoulders","core"}','medicine ball',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a medicine ball at chest level.","Step:2 Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully.","Step:3 As you push the ball forward, release it and let it roll forward.","Step:4 Quickly run forward and catch the ball before it hits the ground.","Step:5 Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward.","Step:6 Continue alternating legs and repeating the exercise for the desired number of repetitions."}','https://static.exercisedb.dev/media/pX9Elbe.gif','https://static.exercisedb.dev/media/pX9Elbe.gif',NULL),
('PXTIwgu','arm slingers hanging straight legs',NULL,'core','abs','{"shoulders","back"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your legs straight down.","Step:2 Engage your core and lift your legs up in front of you until they are parallel to the ground.","Step:3 Hold for a moment at the top, then slowly lower your legs back down to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PXTIwgu.gif','https://static.exercisedb.dev/media/PXTIwgu.gif',NULL),
('py1HSzx','barbell lateral lunge',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a barbell across your upper back.","Step:2 Take a big step to the side with your right foot, keeping your left foot planted.","Step:3 Bend your right knee and lower your body down into a lunge position, keeping your left leg straight.","Step:4 Push off with your right foot and return to the starting position.","Step:5 Repeat on the other side, stepping with your left foot."}','https://static.exercisedb.dev/media/py1HSzx.gif','https://static.exercisedb.dev/media/py1HSzx.gif',NULL),
('PzNxakt','calf push stretch with hands against wall',NULL,'legs','calves','{"hamstrings"}','body weight',NULL,'{"Step:1 Stand facing a wall with your feet hip-width apart.","Step:2 Place your hands against the wall at shoulder height.","Step:3 Step back with one foot, keeping your heel on the ground and your leg straight.","Step:4 Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Step:5 Hold the stretch for 20-30 seconds.","Step:6 Switch legs and repeat the stretch."}','https://static.exercisedb.dev/media/PzNxakt.gif','https://static.exercisedb.dev/media/PzNxakt.gif',NULL),
('PzQanLE','cable shoulder press',NULL,'shoulders','delts','{"triceps","upper back"}','cable',NULL,'{"Step:1 Adjust the cable machine so that the handles are at shoulder height.","Step:2 Stand facing away from the machine with your feet shoulder-width apart.","Step:3 Grasp the handles with an overhand grip and bring them up to shoulder level, with your elbows bent and pointing outwards.","Step:4 Press the handles upwards until your arms are fully extended overhead.","Step:5 Pause for a moment at the top, then slowly lower the handles back down to shoulder level.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/PzQanLE.gif','https://static.exercisedb.dev/media/PzQanLE.gif',NULL),
('pZwUsKB','iron cross stretch',NULL,'legs','glutes','{"hamstrings","quadriceps"}','body weight',NULL,'{"Step:1 Lie flat on your back with your arms extended out to the sides.","Step:2 Raise your legs up towards the ceiling, keeping them straight.","Step:3 Slowly lower your legs to one side, aiming to touch the floor with your feet.","Step:4 Hold the stretch for a few seconds, then return your legs to the starting position.","Step:5 Repeat the stretch on the other side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/pZwUsKB.gif','https://static.exercisedb.dev/media/pZwUsKB.gif',NULL),
('q2ADGqV','cable side crunch',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Attach a cable handle to a low pulley and stand sideways to the machine.","Step:2 Grasp the handle with the hand furthest from the machine and place your other hand on your hip.","Step:3 Keep your feet shoulder-width apart and your knees slightly bent.","Step:4 With your abs engaged, bend sideways at the waist, bringing your elbow down towards your hip.","Step:5 Pause for a moment at the bottom, then slowly return to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/q2ADGqV.gif','https://static.exercisedb.dev/media/q2ADGqV.gif',NULL),
('Q2Eu1Ax','cable lying extension pullover (with rope attachment)',NULL,'back','lats','{"triceps","shoulders"}','cable',NULL,'{"Step:1 Attach a rope to a cable machine and set the pulley at the highest position.","Step:2 Lie down on a bench with your head towards the cable machine.","Step:3 Hold the rope with both hands and extend your arms straight up above your chest.","Step:4 Keeping your arms straight, slowly lower the rope behind your head while maintaining control.","Step:5 Pause for a moment at the bottom, then slowly raise the rope back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Q2Eu1Ax.gif','https://static.exercisedb.dev/media/Q2Eu1Ax.gif',NULL),
('Q497lAE','drop push up',NULL,'chest','pectorals','{"triceps","shoulders"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart.","Step:2 Lower your chest towards the ground, keeping your elbows close to your body.","Step:3 Once your chest is just above the ground, quickly drop your knees to the ground.","Step:4 Push yourself back up to the starting position by extending your arms.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Q497lAE.gif','https://static.exercisedb.dev/media/Q497lAE.gif',NULL),
('Q4DSJPC','smith one arm row',NULL,'back','upper back','{"biceps","forearms"}','machine',NULL,'{"Step:1 Adjust the height of the smith machine bar to waist level.","Step:2 Stand facing the smith machine with your feet shoulder-width apart.","Step:3 Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Step:4 Grasp the bar with one hand using an overhand grip, with your palm facing down.","Step:5 Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.","Step:6 Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.","Step:7 Repeat for the desired number of repetitions, then switch to the other arm."}','https://static.exercisedb.dev/media/Q4DSJPC.gif','https://static.exercisedb.dev/media/Q4DSJPC.gif',NULL),
('Q6bvyen','hanging straight twisting leg hip raise',NULL,'core','abs','{"obliques","hip flexors"}','body weight',NULL,'{"Step:1 Hang from a pull-up bar with your arms fully extended and your legs straight.","Step:2 Engage your core and lift your legs up towards your chest, keeping them straight.","Step:3 Once your legs are parallel to the ground, twist your hips to one side, bringing your legs towards that side.","Step:4 Pause for a moment, then return to the starting position.","Step:5 Repeat the movement, but this time twist your hips to the opposite side.","Step:6 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/Q6bvyen.gif','https://static.exercisedb.dev/media/Q6bvyen.gif',NULL),
('q6y3OhV','lever bicep curl',NULL,'arms','biceps','{"forearms"}','machine',NULL,'{"Step:1 Adjust the seat height and position yourself on the machine with your back against the pad.","Step:2 Grasp the handles with an underhand grip, palms facing up, and keep your elbows close to your sides.","Step:3 Exhale and curl the handles upward, contracting your biceps.","Step:4 Pause for a moment at the top of the movement, squeezing your biceps.","Step:5 Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/q6y3OhV.gif','https://static.exercisedb.dev/media/q6y3OhV.gif',NULL),
('q7qkONO','dumbbell seated alternate shoulder',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Sit on a bench with your back straight and feet flat on the ground.","Step:2 Hold a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.","Step:3 Press one dumbbell up overhead while keeping the other dumbbell at shoulder height.","Step:4 Lower the raised dumbbell back to shoulder height while simultaneously pressing the other dumbbell up overhead.","Step:5 Continue alternating between arms for the desired number of repetitions."}','https://static.exercisedb.dev/media/q7qkONO.gif','https://static.exercisedb.dev/media/q7qkONO.gif',NULL),
('q8aHNoF','dumbbell one arm wrist curl',NULL,'arms','forearms','{"biceps","brachialis"}','dumbbell',NULL,'{"Step:1 Sit on a bench or chair with your feet flat on the ground.","Step:2 Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.","Step:3 Allow your wrist to extend, letting the dumbbell roll down towards your fingers.","Step:4 Slowly curl your wrist back up, bringing the dumbbell towards your forearm.","Step:5 Repeat for the desired number of repetitions, then switch to the other hand."}','https://static.exercisedb.dev/media/q8aHNoF.gif','https://static.exercisedb.dev/media/q8aHNoF.gif',NULL),
('Qa55kX1','sled hack squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','machine',NULL,'{"Step:1 Adjust the sled machine to a comfortable position for your height.","Step:2 Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.","Step:3 Hold onto the handles or bars for stability.","Step:4 Lower your body by bending your knees and hips, keeping your back straight and chest up.","Step:5 Continue lowering until your thighs are parallel to the ground or slightly below.","Step:6 Pause for a moment, then push through your heels to raise your body back up to the starting position.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Qa55kX1.gif','https://static.exercisedb.dev/media/Qa55kX1.gif',NULL),
('qAmNMJY','dumbbell high curl',NULL,'arms','biceps','{"forearms"}','dumbbell',NULL,'{"Step:1 Stand up straight with a dumbbell in each hand, palms facing forward.","Step:2 Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Step:3 Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Step:4 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qAmNMJY.gif','https://static.exercisedb.dev/media/qAmNMJY.gif',NULL),
('qatbkEd','cable side bend crunch (bosu ball)',NULL,'core','abs','{"obliques"}','cable',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a cable handle in one hand.","Step:2 Place the other hand on your hip.","Step:3 Engage your core and slowly bend sideways towards the hand holding the cable, keeping your back straight.","Step:4 Pause for a moment at the bottom of the movement, then slowly return to the starting position.","Step:5 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/qatbkEd.gif','https://static.exercisedb.dev/media/qatbkEd.gif',NULL),
('qaZVsGk','alternate heel touchers',NULL,'core','abs','{"obliques"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Extend your arms straight out to the sides, parallel to the ground.","Step:3 Engaging your abs, lift your shoulders off the ground and reach your right hand towards your right heel.","Step:4 Return to the starting position and repeat on the left side, reaching your left hand towards your left heel.","Step:5 Continue alternating sides for the desired number of repetitions."}','https://static.exercisedb.dev/media/qaZVsGk.gif','https://static.exercisedb.dev/media/qaZVsGk.gif',NULL),
('qBcKorM','all fours squad stretch',NULL,'legs','quads','{"hamstrings","glutes"}','body weight',NULL,'{"Step:1 Start on all fours with your hands directly under your shoulders and your knees directly under your hips.","Step:2 Extend one leg straight back, keeping your knee bent and your foot flexed.","Step:3 Slowly lower your hips towards the ground, feeling a stretch in your quads.","Step:4 Hold this position for 20-30 seconds.","Step:5 Switch legs and repeat the stretch on the other side."}','https://static.exercisedb.dev/media/qBcKorM.gif','https://static.exercisedb.dev/media/qBcKorM.gif',NULL),
('qBl14UC','push-up (wall) with static',NULL,'chest','pectorals','{"triceps","deltoids"}','body weight',NULL,'{"Step:1 Stand facing a wall, about arm's length away.","Step:2 Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart.","Step:3 Step back a few feet, keeping your body straight and your feet hip-width apart.","Step:4 (static variation) Bend your elbows and lower your chest towards the wall, keeping your body in a straight line.","Step:5 Push back up to the starting position, straightening your arms.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qBl14UC.gif','https://static.exercisedb.dev/media/qBl14UC.gif',NULL),
('QChZi3x','squat to overhead reach',NULL,'legs','quads','{"glutes","hamstrings","core"}','body weight',NULL,'{"Step:1 Stand with your feet shoulder-width apart and toes slightly turned out.","Step:2 Lower your body down into a squat position by bending your knees and pushing your hips back.","Step:3 As you come up from the squat, extend your arms overhead, reaching towards the ceiling.","Step:4 Return to the starting position by lowering your arms and bending your knees to squat down again.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/QChZi3x.gif','https://static.exercisedb.dev/media/QChZi3x.gif',NULL),
('qcNN2FN','butt-ups',NULL,'core','abs','{"hip flexors","lower back"}','body weight',NULL,'{"Step:1 Lie flat on your back with your knees bent and feet flat on the ground.","Step:2 Place your hands by your sides, palms facing down.","Step:3 Engaging your abs, lift your legs off the ground, bringing your knees towards your chest.","Step:4 At the top of the movement, squeeze your abs and pause for a moment.","Step:5 Slowly lower your legs back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qcNN2FN.gif','https://static.exercisedb.dev/media/qcNN2FN.gif',NULL),
('qCNVnaU','sled 45в° calf press',NULL,'legs','calves','{"hamstrings"}','machine',NULL,'{"Step:1 Adjust the sled machine to a 45-degree angle.","Step:2 Place your feet on the sled platform with your toes pointing forward.","Step:3 Push the sled platform away from you by extending your ankles and calves.","Step:4 Pause for a moment at the top, then slowly lower the sled platform back to the starting position.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qCNVnaU.gif','https://static.exercisedb.dev/media/qCNVnaU.gif',NULL),
('qcY50ZD','cable seated wide-grip row',NULL,'back','upper back','{"biceps","forearms"}','cable',NULL,'{"Step:1 Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Step:2 Grasp the handle with a wide overhand grip, palms facing down.","Step:3 Keep your back straight and lean slightly forward from the hips.","Step:4 Pull the handle towards your lower chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the peak of the contraction.","Step:6 Slowly release the handle back to the starting position, fully extending your arms.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qcY50ZD.gif','https://static.exercisedb.dev/media/qcY50ZD.gif',NULL),
('qDnGfDb','barbell revers wrist curl v. 2',NULL,'arms','forearms','{"biceps","brachialis"}','barbell',NULL,'{"Step:1 Sit on a bench with your feet flat on the ground and your knees bent.","Step:2 Hold a barbell with an overhand grip, palms facing down, and your hands shoulder-width apart.","Step:3 Rest your forearms on your thighs, allowing your wrists to hang off the edge.","Step:4 Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Step:5 Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qDnGfDb.gif','https://static.exercisedb.dev/media/qDnGfDb.gif',NULL),
('qdRxqCj','cable pulldown (pro lat bar)',NULL,'back','lats','{"biceps","forearms"}','cable',NULL,'{"Step:1 Adjust the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.","Step:2 Grasp the lat bar with an overhand grip, slightly wider than shoulder-width apart.","Step:3 Sit down and lean back slightly, keeping your chest up and your back straight.","Step:4 Pull the bar down towards your chest, squeezing your shoulder blades together.","Step:5 Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qdRxqCj.gif','https://static.exercisedb.dev/media/qdRxqCj.gif',NULL),
('qEse6fe','shoulder tap push-up',NULL,'chest','pectorals','{"triceps","core"}','body weight',NULL,'{"Step:1 Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.","Step:2 Lower your body towards the ground by bending your elbows, keeping them close to your sides.","Step:3 As you push back up, lift your right hand off the ground and tap your left shoulder.","Step:4 Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.","Step:5 Continue alternating shoulder taps with each push-up repetition.","Step:6 Maintain a stable core and avoid excessive hip rotation throughout the exercise.","Step:7 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qEse6fe.gif','https://static.exercisedb.dev/media/qEse6fe.gif',NULL),
('QfAKy1G','dumbbell cuban press',NULL,'shoulders','delts','{"triceps","upper back"}','dumbbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Step:2 Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.","Step:3 Rotate your wrists so that your palms are facing forward.","Step:4 Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.","Step:5 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/QfAKy1G.gif','https://static.exercisedb.dev/media/QfAKy1G.gif',NULL),
('qFHvMnv','micro style barbell speed squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves"}','barbell',NULL,'{"Step:1 Stand with your feet shoulder-width apart, toes slightly turned out.","Step:2 Hold the barbell across your upper back, resting it on your traps or rear delts.","Step:3 Engage your core and keep your chest up as you lower your hips back and down, as if sitting into a chair.","Step:4 (micro variation) Lower until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Drive through your heels to stand back up, squeezing your glutes at the top.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qFHvMnv.gif','https://static.exercisedb.dev/media/qFHvMnv.gif',NULL),
('QFmz6ch','seated lower back stretch',NULL,'back','lats','{"glutes","hamstrings"}','body weight',NULL,'{"Step:1 Sit on the edge of a chair with your feet flat on the ground.","Step:2 Place your hands on your thighs or on the sides of the chair for support.","Step:3 Slowly lean forward from your hips, keeping your back straight.","Step:4 Feel the stretch in your lower back and hold for 20-30 seconds.","Step:5 Slowly return to the starting position and repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/QFmz6ch.gif','https://static.exercisedb.dev/media/QFmz6ch.gif',NULL),
('qFpAkpP','cable standing lift',NULL,'core','abs','{"obliques","lower back"}','cable',NULL,'{"Step:1 Stand facing the cable machine with your feet shoulder-width apart.","Step:2 Hold the cable handle with both hands and position it at waist height.","Step:3 Engage your core and maintain a straight back throughout the exercise.","Step:4 Keeping your arms straight, exhale and lift the cable handle up towards your opposite shoulder, rotating your torso.","Step:5 Pause for a moment at the top, then inhale and slowly lower the cable handle back to the starting position.","Step:6 Repeat for the desired number of repetitions, then switch sides."}','https://static.exercisedb.dev/media/qFpAkpP.gif','https://static.exercisedb.dev/media/qFpAkpP.gif',NULL),
('qg2PGl6','barbell glute bridge two legs on bench (male)',NULL,'legs','glutes','{"hamstrings","core"}','barbell',NULL,'{"Step:1 Start by sitting on the edge of a bench with your upper back resting against it and your feet flat on the ground, hip-width apart.","Step:2 Place a barbell across your hips, holding it securely with both hands.","Step:3 Engage your glutes and core muscles, then press through your heels to lift your hips off the bench, creating a straight line from your knees to your shoulders.","Step:4 Pause for a moment at the top, squeezing your glutes.","Step:5 Slowly lower your hips back down to the starting position.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qg2PGl6.gif','https://static.exercisedb.dev/media/qg2PGl6.gif',NULL),
('qi996YS','barbell clean-grip front squat',NULL,'legs','glutes','{"quadriceps","hamstrings","calves","core"}','barbell',NULL,'{"Step:1 Start by standing with your feet shoulder-width apart and the barbell resting on your upper chest, with your elbows pointing forward.","Step:2 Lower your body by bending your knees and pushing your hips back, as if you are sitting back into a chair.","Step:3 Keep your chest up and your back straight as you lower down, making sure your knees do not go past your toes.","Step:4 Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Step:5 Pause for a moment at the bottom, then push through your heels to stand back up, extending your hips and knees.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/qi996YS.gif','https://static.exercisedb.dev/media/qi996YS.gif',NULL),
('Qj0HRAZ','fast style resistance band seated hip abduction',NULL,'legs','abductors','{"glutes","hamstrings"}','resistance band',NULL,'{"Step:1 Sit on a chair or bench with your back straight and feet flat on the ground.","Step:2 Wrap the resistance band around your thighs, just above your knees.","Step:3 Place your hands on the sides of the chair or bench for support.","Step:4 (fast variation) Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band.","Step:5 Pause for a moment at the end of the movement, then slowly bring your knees back together.","Step:6 Repeat for the desired number of repetitions."}','https://static.exercisedb.dev/media/Qj0HRAZ.gif','https://static.exercisedb.dev/media/Qj0HRAZ.gif',NULL)
